package com.accountalmanac;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class AccountAlmanacPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AccountAlmanacPlugin.class);
		RuneLite.main(args);
	}
}

package com.accountalmanac;

/**
 * How an item is shown in the Grand Exchange log and trade history.
 *
 * <p>Public because it is a return type on the public
 * {@link AccountAlmanacConfig} interface, which RuneLite implements with a
 * dynamic proxy that cannot reach package-private types.
 */
public enum ItemDisplayMode
{
	ICON_AND_NAME("Icon and name"),
	NAME_ONLY("Name only"),
	ICON_ONLY("Icon only");

	private final String label;

	ItemDisplayMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}

	boolean showsIcon()
	{
		return this != NAME_ONLY;
	}

	boolean showsName()
	{
		return this != ICON_ONLY;
	}
}

package com.accountalmanac;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.swing.JPanel;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

/**
 * A replica of the in-game stats interface for one account: three columns
 * by eight rows of skill cells, each with the skill's icon and its level,
 * then a total-level bar underneath.
 *
 * <p>The game shows a boosted level and a real level split diagonally in
 * each cell. Only the real level is ever recorded here - boosts are
 * transient and meaningless once an account is logged out - so this draws
 * one number per cell rather than the same value twice split by a divider,
 * which is what the game itself shows on an unboosted account anyway.
 *
 * <p>Hovering a cell gives the skill name and its exact experience.
 */
class StatsGridPanel extends JPanel
{
	private static final int CELL_WIDTH = 80;
	private static final int CELL_HEIGHT = 32;
	private static final int TOTAL_BAR_HEIGHT = 26;
	private static final int GAP = 2;
	private static final int TEXT_PADDING = 8;

	/** Sampled from the game's stats interface. */
	private static final Color CELL_BACKGROUND = new Color(62, 53, 41);
	private static final Color PANEL_BACKGROUND = new Color(42, 36, 28);
	private static final Color CELL_BORDER = new Color(28, 24, 18);
	private static final Color LEVEL_TEXT = new Color(255, 255, 0);

	private final SkillIconManager skillIconManager;
	private final List<Skill> order = SkillOrder.panelOrder();
	private final Map<Skill, BufferedImage> iconCache = new EnumMap<>(Skill.class);

	private AccountRecord record;

	StatsGridPanel(SkillIconManager skillIconManager)
	{
		this.skillIconManager = skillIconManager;
		setBackground(PANEL_BACKGROUND);
		setToolTipText("");

		int rows = (int) Math.ceil(order.size() / (double) SkillOrder.COLUMNS);
		setPreferredSize(new Dimension(
			SkillOrder.COLUMNS * CELL_WIDTH + (SkillOrder.COLUMNS + 1) * GAP,
			rows * CELL_HEIGHT + (rows + 1) * GAP + TOTAL_BAR_HEIGHT));
	}

	void setRecord(AccountRecord record)
	{
		this.record = record;
		repaint();
	}

	@Override
	public String getToolTipText(MouseEvent event)
	{
		Skill skill = skillAt(event.getPoint());
		if (skill == null || record == null)
		{
			return null;
		}
		return String.format("%s - level %d, %s xp",
			SkillOrder.prettify(skill.name()),
			record.skillLevel(skill.name()),
			Format.exact(record.skillXpFor(skill.name())));
	}

	private Skill skillAt(Point point)
	{
		int column = (point.x - GAP) / (CELL_WIDTH + GAP);
		int row = (point.y - GAP) / (CELL_HEIGHT + GAP);
		if (column < 0 || column >= SkillOrder.COLUMNS || row < 0)
		{
			return null;
		}
		int index = row * SkillOrder.COLUMNS + column;
		return index >= 0 && index < order.size() ? order.get(index) : null;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);

		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			// FRACTIONALMETRICS off pins glyphs to whole pixels - without it,
			// small text at odd cell positions can land on a half-pixel and
			// come out visibly soft. RuneLite's own bold UI font, not a
			// generic Swing default, is what makes this read as "in-game"
			// rather than as a plain Java panel.
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS,
				RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL,
				RenderingHints.VALUE_STROKE_PURE);
			g2.setFont(FontManager.getRunescapeBoldFont().deriveFont(15f));

			for (int i = 0; i < order.size(); i++)
			{
				int column = i % SkillOrder.COLUMNS;
				int row = i / SkillOrder.COLUMNS;
				int x = GAP + column * (CELL_WIDTH + GAP);
				int y = GAP + row * (CELL_HEIGHT + GAP);
				paintCell(g2, order.get(i), x, y);
			}

			paintTotal(g2);
		}
		finally
		{
			g2.dispose();
		}
	}

	private void paintCell(Graphics2D g2, Skill skill, int x, int y)
	{
		g2.setColor(CELL_BACKGROUND);
		g2.fillRect(x, y, CELL_WIDTH, CELL_HEIGHT);
		g2.setColor(CELL_BORDER);
		g2.drawRect(x, y, CELL_WIDTH, CELL_HEIGHT);

		BufferedImage icon = iconFor(skill);
		if (icon != null)
		{
			g2.drawImage(icon,
				x + 5,
				y + (CELL_HEIGHT - icon.getHeight()) / 2,
				null);
		}

		// An account seen before XP tracking existed, or a skill never
		// reported, reads as level 1 rather than 0 - the game has no level 0.
		int level = record == null ? 1 : Math.max(1, record.skillLevel(skill.name()));
		String text = Integer.toString(level);

		FontMetrics fm = g2.getFontMetrics();
		int textX = x + CELL_WIDTH - TEXT_PADDING - fm.stringWidth(text);
		// Standard single-line vertical centering: half the cap-to-baseline
		// span above the midpoint, then move down by the ascent to land the
		// baseline correctly - centers on the glyphs' visual body, not on
		// the font's full ascent-plus-descent box, which reads as too high.
		int textY = y + (CELL_HEIGHT + fm.getAscent() - fm.getDescent()) / 2;

		g2.setColor(LEVEL_TEXT);
		g2.drawString(text, textX, textY);
	}

	private void paintTotal(Graphics2D g2)
	{
		int rows = (int) Math.ceil(order.size() / (double) SkillOrder.COLUMNS);
		int y = GAP + rows * (CELL_HEIGHT + GAP);
		int width = getWidth() - 2 * GAP;

		g2.setColor(CELL_BACKGROUND);
		g2.fillRect(GAP, y, width, TOTAL_BAR_HEIGHT - GAP);
		g2.setColor(CELL_BORDER);
		g2.drawRect(GAP, y, width, TOTAL_BAR_HEIGHT - GAP);

		String text = "Total level: "
			+ (record == null ? "0" : Format.exact(record.totalLevel()));
		FontMetrics fm = g2.getFontMetrics();
		g2.setColor(LEVEL_TEXT);
		g2.drawString(text,
			GAP + (width - fm.stringWidth(text)) / 2,
			y + (TOTAL_BAR_HEIGHT - GAP + fm.getAscent() - fm.getDescent()) / 2);
	}

	/**
	 * Skill icons are static resources loaded from the client jar, so unlike
	 * item sprites they arrive fully formed and only need caching to avoid
	 * re-decoding them on every repaint.
	 */
	private BufferedImage iconFor(Skill skill)
	{
		if (skillIconManager == null)
		{
			return null;
		}
		BufferedImage cached = iconCache.get(skill);
		if (cached != null)
		{
			return cached;
		}
		try
		{
			BufferedImage icon = skillIconManager.getSkillImage(skill, true);
			if (icon != null)
			{
				iconCache.put(skill, icon);
			}
			return icon;
		}
		catch (RuntimeException e)
		{
			// A skill the installed client has no icon for - draw the cell
			// without one rather than losing the whole panel.
			return null;
		}
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.List;

/**
 * Root object persisted to {@code accounts.json}.
 *
 * <p>Replaces the older {@code VaultData}, which additionally held a KDF
 * salt and password verifier for the removed credential vault. Gson ignores
 * those unknown fields when reading an older file, so existing tracked
 * accounts survive the upgrade - only the encrypted credentials are dropped,
 * and those were unreadable without the master password anyway.
 */
class TrackerData
{
	/** Bumped when the on-disk shape changes in a way that needs migrating. */
	int schemaVersion = 2;

	List<AccountRecord> accounts = new ArrayList<>();

	void normalise()
	{
		if (accounts == null)
		{
			accounts = new ArrayList<>();
			return;
		}
		for (AccountRecord record : accounts)
		{
			record.normalise();
		}
	}
}

package com.accountalmanac;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * The keepsake items the random events hand out, keyed by item id.
 *
 * <p>Ids rather than names, because a name is a display string that Jagex can
 * reword at any time while the id is the thing the game actually stores. The
 * display name is taken from the bank snapshot at render time, so this table
 * only has to say <em>which</em> items count and where each one came from.
 *
 * <p>Only the rewards that survive the event are listed. The events also hand
 * out a great deal of transient junk - puzzle box pieces, broken tool heads,
 * the Quiz Master's wrong answers - and counting those would bury the items
 * anybody actually keeps.
 */
final class RandomEventItems
{
	private RandomEventItems()
	{
	}

	private static final Map<Integer, String> BY_ID = build();

	private static Map<Integer, String> build()
	{
		Map<Integer, String> m = new LinkedHashMap<>();

		// Frog Cave. The token is the trade-in, the rest is what it buys.
		m.put(6183, "Frog Cave");
		m.put(6188, "Frog Cave");
		m.put(6184, "Frog Cave");
		m.put(6185, "Frog Cave");
		m.put(6186, "Frog Cave");
		m.put(6187, "Frog Cave");

		// Lederhosen. Spelled "laderhosen" in the game cache; the id is what
		// matters and the displayed name comes from the snapshot.
		m.put(6180, "Lederhosen");
		m.put(6181, "Lederhosen");
		m.put(6182, "Lederhosen");

		// Mime.
		m.put(3057, "Mime");
		m.put(3058, "Mime");
		m.put(3059, "Mime");
		m.put(3060, "Mime");
		m.put(3061, "Mime");

		// Gravedigger - the zombie outfit. Named DIGGER in the cache.
		m.put(7592, "Gravedigger");
		m.put(7593, "Gravedigger");
		m.put(7594, "Gravedigger");
		m.put(7595, "Gravedigger");
		m.put(7596, "Gravedigger");

		// Drill Demon - the camo outfit.
		m.put(6654, "Drill Demon");
		m.put(6655, "Drill Demon");
		m.put(6656, "Drill Demon");

		// Beekeeper.
		m.put(25129, "Beekeeper");
		m.put(25131, "Beekeeper");
		m.put(25133, "Beekeeper");
		m.put(25135, "Beekeeper");
		m.put(25137, "Beekeeper");

		// Sandwich Lady.
		m.put(23312, "Sandwich Lady");
		m.put(23315, "Sandwich Lady");
		m.put(23318, "Sandwich Lady");

		// One-offs.
		m.put(20590, "Freaky Forester");
		m.put(2528, "Genie");
		m.put(6199, "Quiz Master");

		return Collections.unmodifiableMap(m);
	}

	static boolean isRandomEventItem(int itemId)
	{
		return BY_ID.containsKey(itemId);
	}

	/** Which event drops this item, or empty when it is not one of them. */
	static String sourceOf(int itemId)
	{
		String source = BY_ID.get(itemId);
		return source == null ? "" : source;
	}

	/** How many distinct reward items the table knows about. */
	static int trackedCount()
	{
		return BY_ID.size();
	}

	/**
	 * Whether an item is a burnt cooking failure.
	 *
	 * <p>Matched on the name rather than an id list. Every burnt item the game
	 * has is called "Burnt something", and new ones arrive with every cooking
	 * update - a name test picks those up with no change here, where a
	 * hardcoded id list would silently go stale.
	 */
	static boolean isBurnt(String itemName)
	{
		return itemName != null && itemName.regionMatches(true, 0, "Burnt ", 0, 6);
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/**
 * Counts Old School Bonds held across every tracked account.
 *
 * <p>Bonds are worth calling out separately from the item table: they are
 * membership rather than ordinary stock, they get scattered one at a time
 * across alts, and it is easy to forget one is sitting in a bank somewhere.
 *
 * <h2>The three ids</h2>
 *
 * <p>A bond exists in more than one form and only counting the tradeable one
 * would undercount:
 *
 * <ul>
 * <li>{@link ItemID#OSRS_BOND} - tradeable, has a Grand Exchange price.</li>
 * <li>{@link ItemID#BOUGHT_OSRS_BOND} - the form held briefly after buying.</li>
 * <li>{@link ItemID#OSRS_BOND_UNTRADEABLE} - what a bond becomes once it has
 * been traded to you or taken out of the exchange. Still a bond, still
 * redeemable for membership, but it has no market price, so it is counted
 * separately rather than valued at the tradeable price.</li>
 * </ul>
 */
final class Bonds
{
	private Bonds()
	{
	}

	/** Where the bonds are and what they are worth. */
	static class Holdings
	{
		int tradeable;
		int untradeable;

		/** Market value of the tradeable ones only. */
		long tradeableValue;

		/** Per-account counts, biggest holder first. */
		final List<AccountHolding> byAccount = new ArrayList<>();

		int total()
		{
			return tradeable + untradeable;
		}

		boolean isEmpty()
		{
			return total() == 0;
		}
	}

	static class AccountHolding
	{
		final AccountRecord record;
		final int count;

		AccountHolding(AccountRecord record, int count)
		{
			this.record = record;
			this.count = count;
		}
	}

	private static boolean isTradeableBond(int itemId)
	{
		return itemId == ItemID.OSRS_BOND || itemId == ItemID.BOUGHT_OSRS_BOND;
	}

	private static boolean isBond(int itemId)
	{
		return isTradeableBond(itemId) || itemId == ItemID.OSRS_BOND_UNTRADEABLE;
	}

	/**
	 * Totals bonds across the supplied accounts.
	 *
	 * <p>Bonds sitting in an active <b>sell</b> offer are counted too. They
	 * have left the bank container, which is why the bank snapshot alone misses
	 * them, but they are still owned - the same reasoning
	 * {@link ItemAggregator} applies to every other item. A <b>buy</b> offer is
	 * excluded: that bond has not been acquired yet.
	 */
	static Holdings count(List<AccountRecord> accounts)
	{
		Holdings holdings = new Holdings();

		for (AccountRecord record : accounts)
		{
			int forAccount = 0;

			for (BankItem item : record.bankItems)
			{
				if (!isBond(item.id) || item.quantity <= 0)
				{
					continue;
				}
				forAccount += item.quantity;
				if (isTradeableBond(item.id))
				{
					holdings.tradeable += item.quantity;
					holdings.tradeableValue += item.totalValue();
				}
				else
				{
					holdings.untradeable += item.quantity;
				}
			}

			for (GrandExchangeRecord offer : record.geOffers)
			{
				if (!offer.isSell() || !offer.isActive() || !isBond(offer.itemId))
				{
					continue;
				}
				int remaining = offer.remainingQuantity();
				if (remaining <= 0)
				{
					continue;
				}
				forAccount += remaining;
				if (isTradeableBond(offer.itemId))
				{
					holdings.tradeable += remaining;
					holdings.tradeableValue += offer.sellStockValue();
				}
				else
				{
					holdings.untradeable += remaining;
				}
			}

			if (forAccount > 0)
			{
				holdings.byAccount.add(new AccountHolding(record, forAccount));
			}
		}

		holdings.byAccount.sort(Comparator.comparingInt((AccountHolding h) -> h.count).reversed());
		return holdings;
	}
}

package com.accountalmanac;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/**
 * Atomic read/write of one JSON file, shared by the history and GE event
 * stores.
 *
 * <p>This is the same write dance {@link AccountStore} performs: serialise to a
 * sibling {@code .tmp} then {@link Files#move} it over the target with
 * {@code REPLACE_EXISTING}. {@code File.renameTo} is not used because it
 * silently refuses to overwrite an existing destination on Windows, unlike
 * POSIX {@code rename}. Writing in place instead would leave a truncated file
 * if the process died mid-write, which for this plugin means losing tracked
 * history that cannot be reconstructed.
 *
 * <p>{@code AccountStore} keeps its own copy of this logic rather than being
 * retrofitted onto it. Its version is in service and proven against the user's
 * live 40-account file, and rewriting working persistence code as a side
 * effect of adding features is how data gets lost.
 */
@Slf4j
final class JsonFile
{
	private JsonFile()
	{
	}

	/**
	 * Reads and normalises a JSON file, falling back to {@code empty} for a
	 * missing, unreadable or malformed file.
	 *
	 * <p>A parse failure is warned about and swallowed rather than propagated:
	 * a corrupt history file should cost the user their history, not stop the
	 * plugin from tracking accounts.
	 */
	static <T> T read(File file, Gson gson, Class<T> type, Supplier<T> empty)
	{
		if (file == null || !file.exists())
		{
			return empty.get();
		}
		try (Reader reader = new InputStreamReader(new FileInputStream(file), StandardCharsets.UTF_8))
		{
			T loaded = gson.fromJson(reader, type);
			return loaded == null ? empty.get() : loaded;
		}
		catch (JsonParseException | IOException e)
		{
			log.warn("Failed to read {}; starting empty", file.getName(), e);
			return empty.get();
		}
	}

	/**
	 * @return {@code true} if the file was fully written and swapped in
	 */
	/**
	 * Writes already-serialised JSON.
	 *
	 * <p>Split from serialisation on purpose. Callers hold a lock while turning
	 * their data into text - it has to be consistent - but must not hold it
	 * across the disk write, because the client thread contends on that same
	 * lock and would then be blocked on IO.
	 */
	static boolean writeText(File file, String json)
	{
		File dir = file.getParentFile();
		if (dir != null && !dir.exists() && !dir.mkdirs())
		{
			log.warn("Failed to create directory {}", dir);
			return false;
		}

		File tmp = new File(dir, file.getName() + ".tmp");
		try (Writer writer = new OutputStreamWriter(new FileOutputStream(tmp), StandardCharsets.UTF_8))
		{
			writer.write(json);
		}
		catch (IOException e)
		{
			log.warn("Failed to write {}", tmp.getName(), e);
			return false;
		}

		try
		{
			Files.move(tmp.toPath(), file.toPath(), StandardCopyOption.REPLACE_EXISTING);
			return true;
		}
		catch (IOException e)
		{
			log.warn("Failed to replace {}", file.getName(), e);
			return false;
		}
	}

	static boolean write(File file, Gson gson, Object data)
	{
		File dir = file.getParentFile();
		if (dir != null && !dir.exists() && !dir.mkdirs())
		{
			log.warn("Failed to create directory {}", dir);
			return false;
		}

		File tmp = new File(dir, file.getName() + ".tmp");
		try (Writer writer = new OutputStreamWriter(new FileOutputStream(tmp), StandardCharsets.UTF_8))
		{
			gson.toJson(data, writer);
		}
		catch (IOException e)
		{
			log.warn("Failed to write {}", tmp.getName(), e);
			return false;
		}

		try
		{
			Files.move(tmp.toPath(), file.toPath(), StandardCopyOption.REPLACE_EXISTING);
			return true;
		}
		catch (IOException e)
		{
			log.warn("Failed to replace {}", file.getName(), e);
			return false;
		}
	}
}

package com.accountalmanac;

import com.google.gson.Gson;
import java.io.File;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Append-only log of Grand Exchange events, persisted to
 * {@code ge-events.json}.
 *
 * <p>This is what the GE log, purchase history and sale history all read from.
 * Events are kept oldest-first on disk and returned newest-first for display,
 * which is the order every view of a log actually wants.
 *
 * <p>The log is capped rather than unbounded. A busy flipper generates a lot
 * of offers, and an unbounded file would eventually make every save rewrite
 * megabytes on the executor thread.
 */
@Slf4j
@Singleton
class GeEventStore
{
	private static final String FILE_NAME = "ge-events.json";

	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final File dataFile;

	private GeEventData data = new GeEventData();
	private volatile boolean dirty;

	/**
	 * Bumped on every change to the log.
	 *
	 * <p>Lets a reader tell "nothing has changed" apart from "I should re-read"
	 * without copying and sorting the whole list to find out. The viewer
	 * refreshes every five seconds while anything is dirty, and at a hundred
	 * thousand events that copy-and-sort on the Swing thread is what made the
	 * window stutter.
	 */
	private volatile long revision;

	@Inject
	GeEventStore(Gson gson, ScheduledExecutorService executor)
	{
		// Not pretty-printed, unlike the other two stores. This file is the one
		// that grows without bound, it is only ever read by code, and the
		// indentation costs about a third of its size - 100 MB of whitespace at
		// the upper end of the configurable range.
		this.gson = gson;
		this.executor = executor;
		this.dataFile = new File(new File(RuneLite.RUNELITE_DIR, "accountalmanac"), FILE_NAME);
	}

	void loadAsync(Runnable onLoaded)
	{
		executor.execute(() ->
		{
			synchronized (this)
			{
				data = JsonFile.read(dataFile, gson, GeEventData.class, GeEventData::new);
				data.normalise();
				revision++;
			}
			if (onLoaded != null)
			{
				onLoaded.run();
			}
		});
	}

	File file()
	{
		return dataFile;
	}

	/**
	 * Appends events and trims the log back to {@code maxEvents}, dropping the
	 * oldest first.
	 *
	 * @return {@code true} if anything was actually appended
	 */
	synchronized boolean append(Collection<GeEvent> events, int maxEvents)
	{
		if (events == null || events.isEmpty())
		{
			return false;
		}

		data.events.addAll(events);

		int cap = Math.max(100, maxEvents);
		if (data.events.size() > cap)
		{
			// subList().clear() on an ArrayList removes the range in one
			// System.arraycopy rather than shifting per removal.
			data.events.subList(0, data.events.size() - cap).clear();
		}

		dirty = true;
		revision++;
		return true;
	}

	/** Current revision, for readers deciding whether to re-read. */
	long revision()
	{
		return revision;
	}

	/** Every event, newest first. Defensive copy, safe for the Swing thread. */
	synchronized List<GeEvent> getEventsNewestFirst()
	{
		List<GeEvent> copy = new ArrayList<>(data.events);
		copy.sort(Comparator.comparingLong((GeEvent e) -> e.at).reversed());
		return copy;
	}

	synchronized int eventCount()
	{
		return data.events.size();
	}

	/** Oldest event timestamp, or 0 when the log is empty. */
	synchronized long earliestEventAt()
	{
		long earliest = 0L;
		for (GeEvent event : data.events)
		{
			if (earliest == 0L || event.at < earliest)
			{
				earliest = event.at;
			}
		}
		return earliest;
	}

	synchronized void removeAccount(long accountHash)
	{
		if (data.events.removeIf(e -> e.accountHash == accountHash))
		{
			dirty = true;
			revision++;
			saveAsync();
		}
	}

	private void saveAsync()
	{
		executor.execute(this::flushIfDirty);
	}

	/**
	 * @return {@code true} if there were unsaved events and they were written
	 */
	boolean flushIfDirty()
	{
		String json;
		synchronized (this)
		{
			if (!dirty)
			{
				return false;
			}
			json = serialiseLocked();
		}

		if (JsonFile.writeText(dataFile, json))
		{
			return true;
		}
		synchronized (this)
		{
			// Put it back so the next flush retries rather than dropping data.
			dirty = true;
		}
		return false;
	}

	/** Serialises the current state. Caller must hold the monitor. */
	private String serialiseLocked()
	{
		dirty = false;
		return gson.toJson(data);
	}

}

package com.accountalmanac;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Timestamped local copies of the tracked data files.
 *
 * <p>Backups live in {@code .runelite/accountalmanac/backups/}, inside the
 * plugin's own directory - the guidelines allow writing only under
 * {@code .runelite}, and putting them anywhere else would also mean the user
 * had to know a second location to look in.
 *
 * <p>The time of the last backup is read from the folder names rather than
 * stored in config. One less piece of state to keep in sync, and it stays
 * correct if the user deletes a backup folder by hand.
 */
@Slf4j
class BackupManager
{
	private static final String BACKUPS_DIR = "backups";
	private static final String PREFIX = "backup-";

	/** Dated copies of the Grand Exchange log, kept apart from the full backups. */
	private static final String GE_ARCHIVE_DIR = "ge-log-archive";
	private static final String GE_ARCHIVE_PREFIX = "ge-events-";
	private static final String GE_LOG = "ge-events.json";

	/** Sorts lexicographically in time order, which is why it is used for folder names. */
	private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

	private final File pluginDir;

	BackupManager()
	{
		this.pluginDir = new File(RuneLite.RUNELITE_DIR, "accountalmanac");
	}

	File backupsDir()
	{
		return new File(pluginDir, BACKUPS_DIR);
	}

	/**
	 * Runs a backup if one is due.
	 *
	 * @return the folder written, or {@code null} if nothing was due or the
	 *         copy failed
	 */
	File backupIfDue(long now, int intervalDays)
	{
		long last = lastBackupAt();
		if (last > 0L && now - last < TimeUnit.DAYS.toMillis(Math.max(1, intervalDays)))
		{
			return null;
		}
		return backupNow(now);
	}

	/**
	 * Copies every data file that exists into a new timestamped folder.
	 *
	 * <p>Returns {@code null} rather than an empty folder when there is nothing
	 * to copy, so a fresh install does not accumulate empty backups.
	 */
	File backupNow(long now)
	{
		File target = new File(backupsDir(), PREFIX + STAMP.format(local(now)));
		if (target.exists())
		{
			// Same-second retry - the existing folder is already this backup.
			return target;
		}
		if (!target.mkdirs())
		{
			log.warn("Failed to create backup directory {}", target);
			return null;
		}

		int copied = 0;
		for (String name : new String[]{"accounts.json", "history.json", "ge-events.json"})
		{
			File source = new File(pluginDir, name);
			if (!source.exists())
			{
				continue;
			}
			try
			{
				Files.copy(source.toPath(), new File(target, name).toPath(),
					StandardCopyOption.REPLACE_EXISTING);
				copied++;
			}
			catch (IOException e)
			{
				log.warn("Failed to back up {}", name, e);
			}
		}

		if (copied == 0)
		{
			// Nothing was there to save; do not leave an empty folder behind.
			deleteRecursively(target);
			return null;
		}

		log.debug("Wrote backup {} ({} files)", target.getName(), copied);
		return target;
	}

	/** Deletes the oldest backups until only {@code keep} remain. */
	int pruneOldBackups(int keep)
	{
		List<File> backups = listBackups();
		int limit = Math.max(1, keep);
		if (backups.size() <= limit)
		{
			return 0;
		}

		int removed = 0;
		// listBackups() is newest first, so everything past the limit is older.
		for (File stale : backups.subList(limit, backups.size()))
		{
			if (deleteRecursively(stale))
			{
				removed++;
			}
		}
		return removed;
	}

	File geArchiveDir()
	{
		return new File(pluginDir, GE_ARCHIVE_DIR);
	}

	/**
	 * Copies the Grand Exchange log into a dated file, once per period.
	 *
	 * <p>Which period a run belongs to comes from the machine's clock - see
	 * {@link GeLogArchive#periodKey}. The file for a period is written the
	 * first time the client runs inside it and never rewritten, so the copy
	 * holds the log as it stood at the end of the period before, and a client
	 * that was closed over a month end still archives when it next opens.
	 *
	 * @return the file written, or {@code null} when the schedule is off, this
	 *         period is already archived, or there is nothing to copy
	 */
	File archiveGeLogIfDue(long now, GeLogArchive schedule)
	{
		if (schedule == null || !schedule.isOn())
		{
			return null;
		}

		File source = new File(pluginDir, GE_LOG);
		if (!source.exists())
		{
			return null;
		}

		File target = new File(geArchiveDir(),
			GE_ARCHIVE_PREFIX + schedule.periodKey(local(now).toLocalDate()) + ".json");
		if (target.exists())
		{
			return null;
		}

		File dir = target.getParentFile();
		if (!dir.isDirectory() && !dir.mkdirs())
		{
			log.warn("Failed to create Grand Exchange archive directory {}", dir);
			return null;
		}

		try
		{
			Files.copy(source.toPath(), target.toPath(), StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			log.warn("Failed to archive the Grand Exchange log", e);
			return null;
		}

		log.debug("Archived the Grand Exchange log to {}", target.getName());
		return target;
	}

	/** Existing Grand Exchange archives, newest first. */
	List<File> listGeArchives()
	{
		File[] entries = geArchiveDir().listFiles(
			f -> f.isFile() && f.getName().startsWith(GE_ARCHIVE_PREFIX) && f.getName().endsWith(".json"));
		if (entries == null || entries.length == 0)
		{
			return Collections.emptyList();
		}
		List<File> archives = new ArrayList<>(Arrays.asList(entries));
		// By write time, not by name: keys only sort chronologically within one
		// schedule, and changing schedule mixes shapes - "2026" against
		// "2026-W39" - where sorting by name would prune the wrong file.
		archives.sort(Comparator.comparingLong(File::lastModified).reversed()
			.thenComparing(Comparator.comparing(File::getName).reversed()));
		return archives;
	}

	/** Deletes the oldest Grand Exchange archives until only {@code keep} remain. */
	int pruneGeArchives(int keep)
	{
		List<File> archives = listGeArchives();
		int limit = Math.max(1, keep);
		if (archives.size() <= limit)
		{
			return 0;
		}

		int removed = 0;
		for (File stale : archives.subList(limit, archives.size()))
		{
			if (stale.delete())
			{
				removed++;
			}
		}
		return removed;
	}

	/** Existing backup folders, newest first. */
	List<File> listBackups()
	{
		File dir = backupsDir();
		File[] entries = dir.listFiles(f -> f.isDirectory() && f.getName().startsWith(PREFIX));
		if (entries == null || entries.length == 0)
		{
			return Collections.emptyList();
		}
		List<File> backups = new ArrayList<>(Arrays.asList(entries));
		backups.sort(Comparator.comparing(File::getName).reversed());
		return backups;
	}

	/** Epoch millis of the most recent backup, or 0 if there is none. */
	long lastBackupAt()
	{
		List<File> backups = listBackups();
		for (File backup : backups)
		{
			long at = parseStamp(backup.getName());
			if (at > 0L)
			{
				return at;
			}
		}
		return 0L;
	}

	/**
	 * Parses the timestamp back out of a folder name, returning 0 for anything
	 * that does not parse - a folder the user renamed should be listed but must
	 * not be mistaken for a recent backup.
	 */
	private static long parseStamp(String folderName)
	{
		if (!folderName.startsWith(PREFIX))
		{
			return 0L;
		}
		try
		{
			LocalDateTime parsed = LocalDateTime.parse(folderName.substring(PREFIX.length()), STAMP);
			return parsed.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
		}
		catch (DateTimeParseException e)
		{
			return 0L;
		}
	}

	private static boolean deleteRecursively(File file)
	{
		File[] children = file.listFiles();
		if (children != null)
		{
			for (File child : children)
			{
				deleteRecursively(child);
			}
		}
		return file.delete();
	}

	private static LocalDateTime local(long epochMillis)
	{
		return LocalDateTime.ofInstant(Instant.ofEpochMilli(epochMillis), ZoneId.systemDefault());
	}
}

package com.accountalmanac;

/**
 * One stack in an account's last-seen bank snapshot.
 *
 * <p>The item name and unit price are captured at snapshot time rather than
 * looked up when rendering. {@code ItemManager} lookups need the client
 * thread and a running client, and the panel has to render banks for
 * accounts that aren't logged in - possibly with no client at all. Storing
 * them denormalised keeps the whole UI layer pure Swing.
 *
 * <p>{@code unitPrice} is therefore the price as of {@code lastUpdated} on
 * the owning {@link AccountRecord}, not the live price. Prices are refreshed
 * in bulk from the client thread; see {@code AccountAlmanacPlugin}.
 */
class BankItem
{
	/** Canonical item id - placeholders and noted variants already resolved. */
	int id;
	int quantity;
	String name = "";
	/** GE price per item at the time this snapshot was taken. */
	int unitPrice;

	/**
	 * High alchemy value per item, captured alongside the price.
	 *
	 * <p>Stored rather than looked up on demand because the lookup needs the
	 * client thread and an item composition, neither of which the viewer has
	 * when it is rendering a bank for an account that is not logged in.
	 */
	int haPrice;

	/**
	 * Whether the item is members-only, from the item composition.
	 *
	 * <p>Boxed on purpose: {@code null} means never captured, which is a
	 * different thing from {@code false} meaning free-to-play. Items stored
	 * before this existed read as null until a price refresh backfills them,
	 * and the filter treats unknown as its own case rather than quietly
	 * counting them as F2P.
	 */
	Boolean members;

	BankItem()
	{
	}

	BankItem(int id, int quantity, String name, int unitPrice, int haPrice)
	{
		this(id, quantity, name, unitPrice, haPrice, null);
	}

	BankItem(int id, int quantity, String name, int unitPrice, int haPrice, Boolean members)
	{
		this.members = members;
		this.id = id;
		this.quantity = quantity;
		this.name = name;
		this.unitPrice = unitPrice;
			this.haPrice = haPrice;
	}

	/** Combined high alchemy value of this stack. */
	long totalHaValue()
	{
		return (long) haPrice * quantity;
	}

	long totalValue()
	{
		return (long) unitPrice * quantity;
	}
}

package com.accountalmanac;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * Every user-settable option, and the reason they all live here.
 *
 * <h2>Why settings are config items and tracked data is not</h2>
 *
 * <p>The brief asked whether anything should use RuneLite's sync rather than
 * staying local. Everything on this interface is stored through
 * {@code ConfigManager}, which means it persists across restarts and travels
 * with a RuneLite account profile if one is signed in. That is right for
 * preferences: they are small, they are not sensitive, and wanting the same
 * number format on a second PC is a reasonable expectation.
 *
 * <p>Tracked data deliberately does <em>not</em> go through config, and stays
 * in {@code .runelite/accountalmanac/}:
 *
 * <ul>
 * <li><b>Size.</b> Config values are single strings in a key-value store. The
 * account file is already around 1.8&nbsp;MB across forty accounts, plus
 * snapshot history and the GE log on top. That is not what the config store is
 * for.</li>
 * <li><b>Sensitivity.</b> The data is a list of every alt the user owns, with
 * login names, banks and net worth. Preferences syncing off the machine is
 * fine; that roster is exactly the thing the user asked to keep local.</li>
 * <li><b>Recoverability.</b> Local files can be copied, versioned and restored
 * by the backup option. A synced blob cannot be rolled back by hand.</li>
 * </ul>
 *
 * <p>Per-account metadata - labels, categories, hidden and banned flags - is
 * data rather than preference and stays with the account file for the same
 * reasons, so it survives independently of any RuneLite account.
 */
@ConfigGroup(AccountAlmanacConfig.GROUP)
public interface AccountAlmanacConfig extends Config
{
	String GROUP = "accountalmanac";

	// ------------------------------------------------------------------
	// Sections
	// ------------------------------------------------------------------

	@ConfigSection(
		name = "Numbers",
		description = "How amounts are written out.",
		position = 10
	)
	String numbersSection = "numbers";

	@ConfigSection(
		name = "Colours",
		description = "Colours used for login age, gains and losses.",
		position = 20
	)
	String coloursSection = "colours";

	@ConfigSection(
		name = "Login reminders",
		description = "When an account counts as overdue for a login.",
		position = 30
	)
	String remindersSection = "reminders";

	@ConfigSection(
		name = "History and backups",
		description = "How much history is kept, and automatic local backups.",
		position = 40
	)
	String historySection = "history";

	@ConfigSection(
		name = "Grand Exchange log",
		description = "Recording of offers, sales and collections.",
		position = 50
	)
	String geSection = "ge";

	@ConfigSection(
		name = "Privacy",
		description = "Hiding account names for screenshots and screen sharing.",
		position = 55
	)
	String privacySection = "privacy";


	// ------------------------------------------------------------------
	// General
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "includeGrandExchange",
		name = "Count GE offers as wealth",
		description = "Include coins and stock tied up in outstanding Grand Exchange offers when totalling an account's wealth.",
		position = 1
	)
	default boolean includeGrandExchange()
	{
		return true;
	}

	@ConfigItem(
		keyName = "minimumItemValue",
		name = "Hide items under (gp)",
		description = "Items whose total value across all accounts falls below this are left out of the aggregate item list. Set to 0 to show everything.",
		position = 2
	)
	default int minimumItemValue()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "maxChartSlices",
		name = "Max chart slices",
		description = "Accounts beyond this many are grouped into one 'Other' slice. The chart's own 'Show all' button expands past it.",
		position = 3
	)
	@Range(min = 1, max = 60)
	default int maxChartSlices()
	{
		return 10;
