/**
 * Tracks every account logged into via this client - display name, bank
 * contents, Grand Exchange offers, skill levels and combat level - and
 * aggregates them into a cross-account wealth view.
 *
 * <p>Nothing here touches the network. All state lives under
 * {@code .runelite/accountalmanac/}, split across three files: the account
 * roster, snapshot history for timeframe comparisons, and the Grand Exchange
 * event log. See {@link AccountStore}, {@link HistoryStore} and
 * {@link GeEventStore}.
 *
 * <p>A bank can only be read while it is open, so each account's contents
 * are a snapshot from the last time its bank was opened in this client.
 * Grand Exchange offers do not have that limitation - the client reports
 * all eight slots shortly after login.
 */
@Slf4j
@PluginDescriptor(
	name = "Account Almanac",
	description = "Tracks bank contents, GE offers, stats and combat level across every account you play, with cross-account totals, history and charts",
	tags = {"alts", "accounts", "bank", "wealth", "stats", "combat", "grand", "exchange"}
)
public class AccountAlmanacPlugin extends Plugin
{
	/** How often dirty in-memory state is flushed to disk and the UI refreshed. */
	private static final int FLUSH_INTERVAL_SECONDS = 5;

	/** How often backups and pruning are considered. */
	private static final int MAINTENANCE_INTERVAL_MINUTES = 60;

	/**
	 * How long after login the client's Grand Exchange state burst is still
	 * arriving. Offer changes seen inside this window are marked approximate,
	 * because they may have happened while logged out or in another client
	 * rather than at the moment they were noticed.
	 */
	private static final long GE_SYNC_WINDOW_MILLIS = TimeUnit.SECONDS.toMillis(12);

	/** GE slots the client reports; once all have arrived the burst is over. */
	private static final int GE_SLOT_COUNT = 8;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private AccountAlmanacConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private AccountStore store;

	@Inject
	private HistoryStore historyStore;

	@Inject
	private GeEventStore geEventStore;

	@Inject
	private ScheduledExecutorService executor;

	private final BackupManager backupManager = new BackupManager();

	private AlmanacSidebarPanel panel;
	private NavigationButton navButton;
	private Long currentAccountHash;
	private ScheduledFuture<?> flushTask;
	private ScheduledFuture<?> maintenanceTask;
	private boolean needsNameUpdate;

	private long geSyncUntil;
	private int geSyncSlotsSeen;

	/**
	 * Whether the start-up reprice has actually produced prices yet this
	 * session.
	 *
	 * <p>RuneLite loads its price data asynchronously, so an attempt made while
	 * the plugin is starting can find nothing and silently do nothing. Being
	 * logged in guarantees the cache is warm, so the first login retries it -
	 * which is also the moment the figures are about to be looked at.
	 */
	private boolean repricedThisSession;

	/**
	 * Which account the periodic flush last refreshed a history point for, its
	 * wealth at the time, and when. See {@link #refreshSnapshotIfDue}. Touched
	 * only by the periodic flush, which always runs on the one executor thread.
	 */
	private Long snapshotAccountHash;
	private long snapshotWealth;
	private long snapshotRefreshedAt;

	@Override
	protected void startUp() throws Exception
	{
		currentAccountHash = null;
		geSyncUntil = 0L;
		geSyncSlotsSeen = 0;
		repricedThisSession = false;

		Format.applyConfig(config);
		LoginAge.applyConfig(config);

		panel = new AlmanacSidebarPanel(store, historyStore, geEventStore, config,
			configManager, this, itemManager, skillIconManager, spriteManager);

		store.loadAsync(() ->
		{
			SwingUtilities.invokeLater(panel::rebuild);
			refreshPricesOnStartup();
		});
		historyStore.loadAsync(() -> SwingUtilities.invokeLater(panel::rebuild));
		geEventStore.loadAsync(() -> SwingUtilities.invokeLater(panel::rebuild));

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Account Almanac")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		// Stat changes fire on every XP drop, far too often to save-to-disk
		// and rebuild the Swing panel on each one. AccountStore just marks
		// itself dirty on those; this periodically flushes to disk and
		// refreshes the UI at a sane, human-perceptible rate instead.
		flushTask = executor.scheduleWithFixedDelay(this::periodicFlush,
			FLUSH_INTERVAL_SECONDS, FLUSH_INTERVAL_SECONDS, TimeUnit.SECONDS);

		maintenanceTask = executor.scheduleWithFixedDelay(this::runMaintenance,
			1, MAINTENANCE_INTERVAL_MINUTES, TimeUnit.MINUTES);

		if (config.backupOnSession())
		{
			// Queued rather than run inline: startUp must not touch disk.
			executor.execute(() -> backupNow());
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		if (flushTask != null)
		{
			flushTask.cancel(false);
			flushTask = null;
		}
		if (maintenanceTask != null)
		{
			maintenanceTask.cancel(false);
			maintenanceTask = null;
		}

		// A final snapshot so a session's progress is not lost because the
		// client closed between intervals. Cheap - it touches memory only.
		recordSnapshotForCurrentAccount();

		// The writes are queued rather than performed here. shutDown() runs on
		// the Swing thread when the plugin is toggled off in the config panel,
		// and three synchronous JSON writes there froze the whole client for as
		// long as the event log took to serialise. The guidelines are explicit
		// that shutDown must not block.
		//
		// Nothing is lost by queueing: the periodic flush runs every five
		// seconds, so at most that much is outstanding, and the executor is
		// RuneLite's own shared one which outlives this plugin being disabled.
		executor.execute(() ->
		{
			store.flushIfDirty();
			historyStore.flushIfDirty();
			geEventStore.flushIfDirty();
		});

		if (config.backupOnSession())
		{
			// Queued behind the flushes above so it copies the freshly written
			// files rather than the previous ones.
			executor.execute(this::backupNow);
		}

		if (panel != null)
		{
			panel.closeViewer();
		}
		panel = null;
		navButton = null;
		currentAccountHash = null;
		needsNameUpdate = false;
		geSyncUntil = 0L;
		geSyncSlotsSeen = 0;
	}

	/** Flushes all three stores and refreshes the panel if anything changed. */
	private void periodicFlush()
	{
		// Wrapped because scheduleWithFixedDelay treats an escaping exception as
		// fatal to the task - RuneLite's handler rethrows, so one bad tick would
		// silently stop all flushing and UI refresh for the rest of the session.
		// The underlying race is fixed, but nothing here is worth that failure
		// mode.
		try
		{
			flushOnce();
		}
		catch (RuntimeException e)
		{
			log.warn("Periodic flush failed; continuing", e);
		}
	}

	private void flushOnce()
	{
		long now = System.currentTimeMillis();
		boolean changed = refreshSnapshotIfDue(now);
		changed |= store.flushIfDue(now);
		changed |= historyStore.flushIfDirty();
		changed |= geEventStore.flushIfDirty();

		if (changed)
		{
			refreshPanel();
		}
	}

	/**
	 * Refreshes the logged-in account's history point from the periodic flush.
	 *
	 * <p>A newly logged-in account, or a change in its bank or Grand Exchange
	 * value, goes in straight away. XP movement alone waits for
	 * {@link AccountStore#SKILL_SAVE_INTERVAL_MILLIS}, the same cadence skill
	 * changes reach the account file at: XP moves on every drop, and refreshing
	 * each time rewrote the history file every few seconds while training.
	 * Logout and shutdown still record a point immediately.
	 */
	private boolean refreshSnapshotIfDue(long now)
	{
		Long hash = currentAccountHash;
		AccountRecord record = hash == null ? null : store.findAccount(hash);
		if (record == null)
		{
			return false;
		}

		long wealth = record.bankValue + record.geValue();
		if (hash.equals(snapshotAccountHash) && wealth == snapshotWealth
			&& now - snapshotRefreshedAt < AccountStore.SKILL_SAVE_INTERVAL_MILLIS)
		{
			return false;
		}

		snapshotAccountHash = hash;
		snapshotWealth = wealth;
		snapshotRefreshedAt = now;
		return historyStore.recordSnapshot(record, now, config.snapshotIntervalHours());
	}

	/**
	 * Backups and pruning. Runs hourly, but only acts when the configured
	 * interval has actually elapsed - {@link BackupManager} decides that from
	 * the existing backup folders rather than from a timer, so restarting the
	 * client does not reset the schedule.
	 */
	private void runMaintenance()
	{
		try
		{
			if (config.autoBackup())
			{
				File written = backupManager.backupIfDue(System.currentTimeMillis(), config.backupIntervalDays());
				if (written != null)
				{
					int pruned = backupManager.pruneOldBackups(config.backupsToKeep());
					log.debug("Backup written to {} ({} old backups pruned)", written.getName(), pruned);
				}
			}

			archiveGeLogIfDue();
		}
		catch (RuntimeException e)
		{
			// A failed backup must never take the plugin down with it.
			log.warn("Automatic backup failed", e);
		}
	}

	/**
	 * Copies the Grand Exchange log into a dated archive once per period, on
	 * its own schedule rather than the backup one: the log is the only file
	 * that discards data as it grows, so it is the only one where an old copy
	 * holds something the current file cannot.
	 */
	private void archiveGeLogIfDue()
	{
		GeLogArchive schedule = config.geLogArchive();
		if (schedule == null || !schedule.isOn())
		{
			return;
		}

		// The archive is a copy of the file, so anything still only in memory
		// has to reach disk first or it would be missing from the copy.
		geEventStore.flushIfDirty();

		File archived = backupManager.archiveGeLogIfDue(System.currentTimeMillis(), schedule);
		if (archived != null)
		{
			int pruned = backupManager.pruneGeArchives(config.geLogArchivesToKeep());
			log.debug("Archived the Grand Exchange log to {} ({} old archives pruned)",
				archived.getName(), pruned);
		}
	}

	/**
	 * Snapshots the logged-in account. {@link HistoryStore} applies the
	 * throttle, so calling this every flush is cheap and simply refreshes the
	 * tip of the account's history until the interval rolls over.
	 */
	private boolean recordSnapshotForCurrentAccount()
	{
		Long hash = currentAccountHash;
		if (hash == null)
		{
			return false;
		}
		AccountRecord record = store.findAccount(hash);
		if (record == null)
		{
			return false;
		}
		return historyStore.recordSnapshot(record, System.currentTimeMillis(), config.snapshotIntervalHours());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AccountAlmanacConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		// Number formats and colours are read at render time, so adopting the
		// new values and repainting is all that is needed - no restart.
		Format.applyConfig(config);
		LoginAge.applyConfig(config);
		refreshPanel();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			long hash = client.getAccountHash();
			if (hash == -1L)
			{
				return;
			}
			currentAccountHash = hash;
			needsNameUpdate = true;

			// Prices are certainly loaded by now, unlike at plugin start-up.
			if (!repricedThisSession && config.refreshPricesOnStartup())
			{
				repricedThisSession = true;
				log.debug("Repricing stored items on first login of the session");
				refreshPrices(this::refreshPanel);
			}

			// Open the window during which GE offer changes are treated as
			// possibly-historic rather than as happening right now.
			geSyncUntil = System.currentTimeMillis() + GE_SYNC_WINDOW_MILLIS;
			geSyncSlotsSeen = 0;

			tryUpdateDisplayName();
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			// Capture where the account finished before letting go of it.
			boolean wasLoggedIn = currentAccountHash != null;
			recordSnapshotForCurrentAccount();
			if (wasLoggedIn)
			{
				// Saved now rather than by the periodic flush: skill changes
				// otherwise wait up to AccountStore.SKILL_SAVE_INTERVAL_MILLIS,
				// and a client closed from the login screen should not depend on
				// that timer. Queued, because this runs on the client thread.
				executor.execute(() ->
				{
					store.flushIfDirty();
					historyStore.flushIfDirty();
				});
			}
			currentAccountHash = null;
			needsNameUpdate = false;
			geSyncUntil = 0L;
			geSyncSlotsSeen = 0;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The local player (and its name) isn't always populated yet on the
		// exact tick GameStateChanged fires LOGGED_IN - keep retrying each
		// tick until it actually shows up, instead of a single attempt that
		// can silently lose the race and leave the account unnamed.
		if (needsNameUpdate)
		{
			tryUpdateDisplayName();
			tryUpdatePlaytime();
			tryUpdateQuestPoints();
			tryUpdateSummaryCounts();
		}

		// Two of the Account Summary counters exist nowhere else, so they are
		// taken whenever that screen happens to be open.
		readAccountSummaryPanel();
	}

	/**
	 * Quests completed and collection log slots filled, both straight from
	 * vars, so they are current on every login without opening anything.
	 */
	private void tryUpdateSummaryCounts()
	{
		if (currentAccountHash == null)
		{
			return;
		}
		store.updateSummaryCounts(currentAccountHash,
			client.getVarbitValue(VarbitID.QUESTS_COMPLETED_COUNT),
			client.getVarbitValue(VarbitID.QUESTS_TOTAL_COUNT),
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT),
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX));
	}

	/**
	 * Reads achievement diary and combat task counts off the Account Summary
	 * screen while it is open.
	 *
	 * <p>Neither has a whole-account var to read - the game keeps diary tasks
	 * per region and combat tasks per boss, and both totals move with every
	 * update. That screen already does the arithmetic, so the figures are read
	 * from its own text: a label such as "Combat Tasks Completed:" followed by
	 * "17/855". While it is closed the last capture simply stands.
	 */
	private void readAccountSummaryPanel()
	{
		if (currentAccountHash == null)
		{
			return;
		}

		Widget contents = client.getWidget(InterfaceID.AccountSummarySidepanel.SUMMARY_CONTENTS);
		if (contents == null || contents.isHidden())
		{
			return;
		}

		List<String> texts = new ArrayList<>();
		collectText(contents, texts, 0);

		int[] achievements = null;
		int[] combat = null;
		String label = "";
		for (String raw : texts)
		{
			String text = Text.removeTags(raw).trim();
			if (text.isEmpty())
			{
				continue;
			}
			int[] fraction = parseFraction(text);
			if (fraction == null)
			{
				// Not a count, so it names whichever count comes next.
				label = text.toLowerCase(Locale.ROOT);
				continue;
			}
			if (label.contains("achievement"))
			{
				achievements = fraction;
			}
			else if (label.contains("combat"))
			{
				combat = fraction;
			}
		}

		if (achievements == null && combat == null)
		{
			return;
		}
		store.updateSummaryTasks(currentAccountHash,
			achievements == null ? 0 : achievements[0],
			achievements == null ? 0 : achievements[1],
			combat == null ? 0 : combat[0],
			combat == null ? 0 : combat[1]);
	}

	/** Every piece of text under a widget, in layout order. */
	private static void collectText(Widget widget, List<String> into, int depth)
	{
		// The screen nests a few levels; the cap stops a malformed tree looping.
		if (widget == null || depth > 4)
		{
			return;
		}

		String text = widget.getText();
		if (text != null && !text.isEmpty())
		{
			into.add(text);
		}

		Widget[][] groups = {widget.getStaticChildren(), widget.getDynamicChildren(), widget.getNestedChildren()};
		for (Widget[] children : groups)
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				collectText(child, into, depth + 1);
			}
		}
	}

	/** {@code "17/855"} as {@code [17, 855]}, or null when it is not a count. */
	private static int[] parseFraction(String text)
	{
		int slash = text.indexOf('/');
		if (slash <= 0 || slash == text.length() - 1)
		{
			return null;
		}
		try
		{
			int done = Integer.parseInt(text.substring(0, slash).replace(",", "").trim());
			int total = Integer.parseInt(text.substring(slash + 1).replace(",", "").trim());
			return total > 0 && done >= 0 ? new int[]{done, total} : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private void tryUpdateDisplayName()
	{
		if (currentAccountHash == null)
		{
			return;
		}
		Player local = client.getLocalPlayer();
		String name = local != null ? local.getName() : null;
		if (name != null && !name.isEmpty())
		{
			store.touchAccount(currentAccountHash, name, readLoginName(), readAccountType());
			needsNameUpdate = false;
			refreshPanel();
		}
	}

	/**
	 * Best-effort login identity.
	 *
	 * <p>{@code getLauncherDisplayName()} is the account name as assigned by
	 * the Jagex launcher - this is what {@code ConfigManager} itself uses
	 * internally to key per-account config profiles, so it is the correct,
	 * currently-supported way to identify a Jagex account. It is preferred.
	 *
	 * <p>There used to be a fallback to {@code getUsername()}, which reads the
	 * client's own login screen field for accounts not using the launcher. It
	 * was removed: on the classic login flow that field holds whatever was
	 * typed to log in, which is frequently an email address, and a tracker has
	 * no business recording one. The launcher name is an account label and
	 * carries no such risk.
	 *
	 * <p>This can come back blank on a non-launcher login. An empty result is
	 * discarded by the store rather than overwriting a value captured earlier,
	 * and it is never inferred from the display name - a guessed login name
	 * would be worse than no login name at all.
	 */
	private String readLoginName()
	{
		return readLauncherName();
	}

	/** The Jagex launcher's account name, which is available before login too. */
	private String readLauncherName()
	{
		String launcherName = client.getLauncherDisplayName();
		return launcherName == null ? "" : launcherName.trim();
	}

	/**
	 * Ironman variant, read from the game's own account-type varbit.
	 *
	 * <p>Replaces the deprecated {@code Client.getAccountType()}, which read
	 * this same varbit. The names returned are the ones that method's enum
	 * used, so values stored by earlier versions keep matching.
	 */
	private String readAccountType()
	{
		switch (client.getVarbitValue(VarbitID.IRONMAN))
		{
			case 1:
				return "IRONMAN";
			case 2:
				return "ULTIMATE_IRONMAN";
			case 3:
				return "HARDCORE_IRONMAN";
			case 4:
				return "GROUP_IRONMAN";
			case 5:
				return "HARDCORE_GROUP_IRONMAN";
			default:
				return "NORMAL";
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (currentAccountHash == null || event.getContainerId() != InventoryID.BANK)
		{
			return;
		}

		ItemContainer container = event.getItemContainer();
		if (container == null)
		{
			return;
		}

		// Already on the client thread here, so ItemManager lookups are safe.
		// Names and prices are captured now and stored alongside the
		// quantities, so the panel can render banks for accounts that aren't
		// logged in without touching the client at all.
		Map<Integer, BankItem> merged = new LinkedHashMap<>();
		long value = 0L;

		for (Item item : container.getItems())
		{
			if (item.getId() <= 0 || item.getQuantity() <= 0)
			{
				// Placeholders sit at quantity 0 and would otherwise show up
				// as zero-value rows in every aggregate view.
				continue;
			}

			int canonicalId = itemManager.canonicalize(item.getId());
			int unitPrice = itemManager.getItemPrice(canonicalId);
			value += (long) unitPrice * item.getQuantity();

			BankItem existing = merged.get(canonicalId);
			if (existing != null)
			{
				// Noted and unnoted stacks of the same item canonicalise to
				// one id, so they have to be summed rather than overwrite.
				existing.quantity += item.getQuantity();
			}
			else
			{
				net.runelite.api.ItemComposition composition = itemManager.getItemComposition(canonicalId);
				merged.put(canonicalId, new BankItem(canonicalId, item.getQuantity(),
					composition.getName(), unitPrice, composition.getHaPrice(),
					composition.isMembers()));
			}
		}

		store.updateBank(currentAccountHash, new ArrayList<>(merged.values()), value);
		refreshPanel();
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (currentAccountHash == null)
		{
			return;
		}

		GrandExchangeOffer offer = event.getOffer();
		if (offer == null)
		{
			return;
		}

		GrandExchangeRecord record = new GrandExchangeRecord();
		record.slot = event.getSlot();
		record.state = offer.getState().name();
		record.itemId = offer.getItemId();
		record.pricePerItem = offer.getPrice();
		record.totalQuantity = offer.getTotalQuantity();
		record.quantitySold = offer.getQuantitySold();
		record.spent = offer.getSpent();
		record.updatedAt = System.currentTimeMillis();

		if (record.itemId > 0)
		{
			record.itemName = itemManager.getItemComposition(record.itemId).getName();
			// Captured now, on the client thread, so stock in a sell offer is
			// valued at what it is worth rather than at what it was listed for.
			record.marketPrice = itemManager.getItemPrice(record.itemId);
		}

		// Swap in the new state and get back what was there, so the change can
		// be turned into log events. Atomic inside the store - see updateGeOffer.
		GrandExchangeRecord previous = store.updateGeOffer(currentAccountHash, record);

		if (config.logGeEvents())
		{
			logGeChange(previous, record);
		}
	}

	/**
	 * Turns one slot change into log events. The item name is copied from the
	 * new record onto events derived from the old one, because a collected
	 * slot reports item id 0 and the name would otherwise be lost.
	 */
	private void logGeChange(GrandExchangeRecord previous, GrandExchangeRecord current)
	{
		boolean approximate = consumeGeSyncSlot();

		List<GeEvent> events = GeEventTracker.diff(
			previous, current,
			currentAccountHash,
			store.labelFor(currentAccountHash),
			System.currentTimeMillis(),
			approximate);

		if (events.isEmpty())
		{
			return;
		}

		// Fill in any item name the diff could not resolve from the record it
		// was derived from.
		for (GeEvent geEvent : events)
		{
			if (geEvent.itemName.isEmpty() && geEvent.itemId > 0)
			{
				geEvent.itemName = itemManager.getItemComposition(geEvent.itemId).getName();
			}
		}

		geEventStore.append(events, config.maxGeEvents());
	}

	/**
	 * Whether the post-login state burst is still arriving, counting this
	 * offer event against it. Named for the fact that it mutates: each call
	 * consumes one slot of the burst allowance.
	 *
	 * <p>The burst ends when all eight slots have reported once or when the
	 * window elapses, whichever comes first - the slot count handles the
	 * common case immediately, and the timeout covers an account that never
	 * reports eight slots.
	 */
	private boolean consumeGeSyncSlot()
	{
		if (geSyncUntil == 0L)
		{
			return false;
		}
		if (geSyncSlotsSeen < GE_SLOT_COUNT)
		{
			geSyncSlotsSeen++;
			return System.currentTimeMillis() < geSyncUntil;
		}
		geSyncUntil = 0L;
		return false;
	}

	/**
	 * Captures the account's reported playtime.
	 *
	 * <p>Read on a tick rather than once at login because the varp is not
	 * populated the instant the game state flips - the same race the display
	 * name has. The store ignores zero, so an early read costs nothing.
	 */
	private void tryUpdatePlaytime()
	{
		if (currentAccountHash == null)
		{
			return;
		}
		store.updatePlaytime(currentAccountHash,
			client.getVarbitValue(VarbitID.ACCOUNT_SUMMARY_DISPLAY_PLAYTIME));
	}

	/**
	 * Captures the account's quest points and the game's current maximum.
	 *
	 * <p>Read on a tick for the same reason as playtime: neither var is
	 * populated on the exact tick the game state flips to logged in. The
	 * store ignores a zero maximum, so an early read costs nothing.
	 *
	 * <p>The maximum comes from the game rather than a constant in here,
	 * so a quest release moves the denominator without a plugin update.
	 */
	private void tryUpdateQuestPoints()
	{
		if (currentAccountHash == null)
		{
			return;
		}
		store.updateQuestPoints(currentAccountHash,
			client.getVarpValue(VarPlayerID.QP),
			client.getVarbitValue(VarbitID.QP_MAX));
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (currentAccountHash == null)
		{
			return;
		}
		// getLevel() is the real level; getBoostedLevel() is transient and
		// would be meaningless once the account is logged out.
		store.updateSkill(currentAccountHash, event.getSkill().name(),
			event.getLevel(), event.getXp());
	}

	/**
	 * Re-prices every stored bank snapshot against current GE prices.
	 *
	 * <p>Snapshots are taken at different times, so without this an
	 * account's value reflects prices from whenever its bank was last
	 * opened - which makes cross-account totals compare stale numbers
	 * against fresh ones. Pricing needs the client thread, so this hops
	 * there, then goes back off-thread before touching disk.
	 *
	 * @param onComplete run on the Swing thread once prices are applied
	 */
	void refreshPrices(Runnable onComplete)
	{
		Set<Integer> ids = store.allBankItemIds();
		if (ids.isEmpty())
		{
			SwingUtilities.invokeLater(onComplete);
			return;
		}

		clientThread.invoke(() ->
		{
			Map<Integer, Integer> prices = new HashMap<>(ids.size());
			// Alch values come from the item composition, which is available for
			// any id on this thread - the bank does not need to have been
			// opened. Collected here so every stored item gets one, rather than
			// only the ones seen since alch values started being recorded.
			Map<Integer, Integer> alchPrices = new HashMap<>(ids.size());
			// Members flag comes from the same composition lookup, so stored
			// items from before it was recorded get one without a second pass.
			Map<Integer, Boolean> membersById = new HashMap<>(ids.size());
			for (Integer id : ids)
			{
				net.runelite.api.ItemComposition comp = itemManager.getItemComposition(id);
				membersById.put(id, comp.isMembers());
				int ha = comp.getHaPrice();
				if (ha > 0)
				{
					alchPrices.put(id, ha);
				}
				int price = itemManager.getItemPrice(id);
				// A zero is never published. It means one of two things and
				// they are indistinguishable here: an untradeable item, which
				// already stores 0 and so needs no update, or an item cache
				// that is not warm yet, which is transient. Writing it would
				// overwrite a good stored price with nothing - and run at
				// start-up across forty accounts, that empties every bank.
				// Omitting the key makes applyPrices keep what it has.
				if (price > 0)
				{
					prices.put(id, price);
				}
			}

			executor.execute(() ->
			{
				// Baselines are updated before the new prices land, so the
				// comparison is against what was there previously.
				if (historyStore.updatePriceBaselines(prices, System.currentTimeMillis(),
					TimeUnit.HOURS.toMillis(config.priceMovementHours())))
				{
					historyStore.flushIfDirty();
				}

				store.applyAlchPrices(alchPrices);
				store.applyMembersFlags(membersById);

				if (store.applyPrices(prices))
				{
					store.flushIfDirty();
					// Every account's wealth was just restated at current
					// prices. That is genuinely new information about all of
					// them, not just the one logged in, so it is worth a
					// history point for each.
					snapshotAllAccounts();
				}
				SwingUtilities.invokeLater(onComplete);
			});
		});
	}

	/**
	 * Brings every stored price up to date when the client starts.
	 *
	 * <p>Snapshots are taken whenever a bank happened to be open, so without
	 * this the totals mix prices from different days - an account banked last
	 * week is compared against one banked an hour ago. Repricing on start-up
	 * means every figure shown is against the same market.
	 *
	 * <p>When the setting is off this still runs for offers that have no market
	 * price at all, since their stock would otherwise be valued at nothing.
	 * That case is a one-off after upgrading and normally does nothing.
	 */
	private void refreshPricesOnStartup()
	{
		if (config.refreshPricesOnStartup())
		{
			log.debug("Repricing all stored items against current prices");
			refreshPrices(() ->
			{
				// Only counts as done if prices were actually available; the
				// login retry covers the case where they were not.
				repricedThisSession = store.hasPricedItems();
				refreshPanel();
			});
			return;
		}

		for (AccountRecord record : store.getAccounts())
		{
			for (GrandExchangeRecord offer : record.geOffers)
			{
				if (offer.needsMarketPrice())
				{
					log.debug("Pricing stored Grand Exchange offers for the first time");
					refreshPrices(this::refreshPanel);
					return;
				}
			}
		}
	}

	/**
	 * Records a history snapshot for every account with something worth
	 * recording. Called after a reprice rather than on a timer, so history
	 * only gains points when the underlying figures actually moved.
	 */
	private void snapshotAllAccounts()
	{
		long now = System.currentTimeMillis();
		int interval = config.snapshotIntervalHours();
		boolean any = false;
		for (AccountRecord record : store.getAccounts())
		{
			any |= historyStore.recordSnapshot(record, now, interval);
		}
		if (any)
		{
			historyStore.flushIfDirty();
		}
	}

	/**
	 * Runs a backup on the calling thread. Start-up and shut-down already queue
	 * it on the executor; the settings tab goes through
	 * {@link #backupInBackground} instead.
	 */
	File backupNow()
	{
		// Flush first, or the backup captures the last saved state rather than
		// the current one.
		store.flushIfDirty();
		historyStore.flushIfDirty();
		geEventStore.flushIfDirty();

		File written = backupManager.backupNow(System.currentTimeMillis());
		if (written != null)
		{
			backupManager.pruneOldBackups(config.backupsToKeep());
		}
		return written;
	}

	/**
	 * Runs {@link #backupNow} on the background executor, for the settings
	 * tab's button. A backup serialises and copies every data file -
	 * megabytes - and run on the Swing thread it froze the whole client window
	 * until it finished.
	 *
	 * @param onDone run on the Swing thread with the backup folder ({@code null}
	 *               when there was nothing to back up) or the error that stopped it
	 */
	void backupInBackground(java.util.function.BiConsumer<File, RuntimeException> onDone)
	{
		executor.execute(() ->
		{
			File written = null;
			RuntimeException failure = null;
			try
			{
				written = backupNow();
			}
			catch (RuntimeException e)
			{
				log.warn("Manual backup failed", e);
				failure = e;
			}
			File result = written;
			RuntimeException error = failure;
			SwingUtilities.invokeLater(() -> onDone.accept(result, error));
		});
	}

	BackupManager backups()
	{
		return backupManager;
	}

	/** Account hash to display label, for chart legends. */
	Map<Long, String> accountLabels()
	{
		Map<Long, String> labels = new HashMap<>();
		for (AccountRecord record : store.getAccounts())
		{
			labels.put(record.accountHash, NameMasker.display(record, config.namePrivacy()));
		}
		return labels;
	}

	/** The account currently logged in, or {@code null} at the login screen. */
	Long currentAccountHash()
	{
		return currentAccountHash;
	}

	private void refreshPanel()
	{
		AlmanacSidebarPanel current = panel;
		if (current != null)
		{
			SwingUtilities.invokeLater(current::rebuild);
		}
	}

	@Provides
	AccountAlmanacConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AccountAlmanacConfig.class);
	}
}

package com.accountalmanac;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A donut chart with an inline legend, drawn directly with Graphics2D.
 *
 * <p>Deliberately not a charting library - AGENTS.md forbids pulling extra
 * dependencies through runelite-client, and a pie with a legend is a couple
 * of {@link Arc2D} calls. This is a sidebar/window component, never an
 * overlay, so the per-frame cost rule for overlays does not apply.
 *
 * <p>By default anything past {@code maxSlices} collapses into one "Other"
 * wedge so a roster of forty accounts still gets a readable pie. A "Show
 * all" toggle underneath switches to the uncapped list instead, scrolling
 * within a fixed-height viewport rather than growing the panel itself - the
 * surrounding layout stays put whichever mode is showing.
 */
class PieChartPanel extends JPanel
{
	private static final int VIEWPORT_HEIGHT = 340;

	private final DonutCanvas canvas;
	private final JButton toggleButton = new JButton();

	private List<ItemAggregator.Slice> fullSlices = Collections.emptyList();
	private int maxSlices = 10;
	private boolean expanded;

	/**
	 * @param valuesAreGp {@code true} to format slice values as coins,
	 *                    {@code false} to show raw quantities
	 */
	PieChartPanel(boolean valuesAreGp)
	{
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		canvas = new DonutCanvas(valuesAreGp);

		JScrollPane scroll = new JScrollPane(canvas);
		scroll.setBorder(null);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.setPreferredSize(new Dimension(220, VIEWPORT_HEIGHT));
		scroll.getVerticalScrollBar().setUnitIncrement(16);

		toggleButton.setFont(FontManager.getRunescapeSmallFont());
		toggleButton.setVisible(false);
		toggleButton.addActionListener(e ->
		{
			expanded = !expanded;
			applySlices();
		});

		JPanel toggleRow = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 4));
		toggleRow.setOpaque(false);
		toggleRow.add(toggleButton);

		add(scroll, BorderLayout.CENTER);
		add(toggleRow, BorderLayout.SOUTH);
	}

	void setEmptyMessage(String message)
	{
		canvas.setEmptyMessage(message);
	}

	/**
	 * Replaces the chart contents. {@code input} is kept in full - only the
	 * collapsed view discards anything - so toggling "Show all" later never
	 * needs the caller to resupply data.
	 */
	void setSlices(List<ItemAggregator.Slice> input, int maxSlices)
	{
		this.fullSlices = input;
		this.maxSlices = Math.max(1, maxSlices);
		this.expanded = false;
		applySlices();
	}

	private void applySlices()
	{
		boolean hasOverflow = fullSlices.size() > maxSlices;
		toggleButton.setVisible(hasOverflow);
		toggleButton.setText(expanded ? "Show top " + maxSlices : "Show all " + fullSlices.size());

		canvas.setSlices(expanded ? fullSlices : capSlices(fullSlices, maxSlices));
	}

	/** Collapses anything past {@code limit} into one "Other (N)" wedge. */
	private static List<ItemAggregator.Slice> capSlices(List<ItemAggregator.Slice> input, int limit)
	{
		List<ItemAggregator.Slice> trimmed = new ArrayList<>();
		for (int i = 0; i < input.size() && i < limit; i++)
		{
			trimmed.add(input.get(i));
		}

		if (input.size() > limit)
		{
			long other = 0L;
			for (int i = limit; i < input.size(); i++)
			{
				other += input.get(i).value;
			}
			if (other > 0L)
			{
				trimmed.add(new ItemAggregator.Slice(
					"Other (" + (input.size() - limit) + ")", other, 0L));
			}
		}

		return trimmed;
	}

	/** The actual donut + legend painting, unchanged from before apart from living in its own scrollable canvas now. */
	private static class DonutCanvas extends JPanel
	{
		private static final Color[] PALETTE = {
			new Color(219, 166, 76),   // runelite gold
			new Color(88, 150, 214),   // blue
			new Color(106, 176, 106),  // green
			new Color(198, 91, 91),    // red
			new Color(157, 121, 199),  // purple
			new Color(214, 143, 74),   // orange
			new Color(90, 179, 179),   // teal
			new Color(197, 128, 165),  // pink
			new Color(150, 158, 84),   // olive
			new Color(120, 132, 176),  // slate
			new Color(180, 110, 60),   // brown
			new Color(130, 130, 130),  // grey ("Other")
		};

		private static final int DIAMETER = 150;
		private static final int LEGEND_ROW_HEIGHT = 17;
		private static final int SWATCH = 10;
		private static final double DONUT_INNER_RATIO = 0.55;

		private final boolean valuesAreGp;

		private List<ItemAggregator.Slice> slices = Collections.emptyList();
		private long total;
		private String emptyMessage = "No data yet";

		DonutCanvas(boolean valuesAreGp)
		{
			this.valuesAreGp = valuesAreGp;
			setBackground(ColorScheme.DARK_GRAY_COLOR);
			setFont(FontManager.getRunescapeSmallFont());
			// Registers the component with ToolTipManager. The text itself is
			// produced per-position by getToolTipText below; without this call
			// that override is never consulted.
			setToolTipText("");
		}

		/**
		 * Exact figure for whichever slice is under the cursor.
		 *
		 * <p>The chart is painted straight onto one canvas, so there is no
		 * per-slice component to hang a tooltip on - the position has to be
		 * resolved back to a slice by hand. Both the legend rows and the
		 * wedges themselves answer, since either is a natural thing to point
		 * at.
		 *
		 * <p>Worth having because every figure drawn here is abbreviated:
		 * "3.3K" could be anything from 3,250 to 3,349.
		 */
		@Override
		public String getToolTipText(MouseEvent event)
		{
			int index = sliceAt(event.getX(), event.getY());
			if (index < 0 || index >= slices.size())
			{
				return null;
			}

			ItemAggregator.Slice slice = slices.get(index);
			double pct = total > 0L ? 100.0 * slice.value / total : 0.0;
			return String.format("%s: %s%s  (%.2f%%)",
				slice.label,
				Format.exact(slice.value),
				valuesAreGp ? " gp" : "",
				pct);
		}

		/** Index of the slice at a point, or -1. Checks the legend, then the wedges. */
		private int sliceAt(int x, int y)
		{
			if (slices.isEmpty() || total <= 0L)
			{
				return -1;
			}

			int legendTop = DIAMETER + 20 - LEGEND_ROW_HEIGHT;
			if (y >= legendTop)
			{
				int row = (y - legendTop) / LEGEND_ROW_HEIGHT;
				return row >= 0 && row < slices.size() ? row : -1;
			}

			// Inside the ring: convert the offset from centre into an angle and
			// walk the slices the same way they were drawn.
			int cx = getWidth() / 2;
			int cy = 8 + DIAMETER / 2;
			double dx = x - cx;
			double dy = y - cy;
			double radius = Math.sqrt(dx * dx + dy * dy);
			double outer = DIAMETER / 2.0;
			if (radius > outer || radius < outer * DONUT_INNER_RATIO)
			{
				return -1;
			}

			// Painting starts at 90 degrees and sweeps clockwise; screen y grows
			// downward, so the angle is negated to match.
			double degrees = Math.toDegrees(Math.atan2(-dy, dx));
			double swept = 90.0 - degrees;
			if (swept < 0.0)
			{
				swept += 360.0;
			}

			double cursor = 0.0;
			for (int i = 0; i < slices.size(); i++)
			{
				cursor += 360.0 * ((double) slices.get(i).value / (double) total);
				if (swept <= cursor)
				{
					return i;
				}
			}
			return slices.size() - 1;
		}

		void setEmptyMessage(String message)
		{
			this.emptyMessage = message;
		}

		void setSlices(List<ItemAggregator.Slice> slices)
		{
			this.slices = slices;
			long sum = 0L;
			for (ItemAggregator.Slice slice : slices)
			{
				sum += slice.value;
			}
			this.total = sum;

			int height = DIAMETER + 16 + Math.max(1, slices.size()) * LEGEND_ROW_HEIGHT + 8;
			setPreferredSize(new Dimension(200, height));
			revalidate();
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);

			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
					RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

				if (slices.isEmpty() || total <= 0L)
				{
					paintEmpty(g2);
					return;
				}

				paintDonut(g2);
				paintLegend(g2);
			}
			finally
			{
				g2.dispose();
			}
		}

		private void paintEmpty(Graphics2D g2)
		{
			g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			FontMetrics fm = g2.getFontMetrics();
			int x = Math.max(4, (getWidth() - fm.stringWidth(emptyMessage)) / 2);
			g2.drawString(emptyMessage, x, 24);
		}

		private void paintDonut(Graphics2D g2)
		{
			int cx = getWidth() / 2;
			int originX = cx - DIAMETER / 2;
			int originY = 8;

			// Arc2D takes degrees as doubles; accumulating the running start in
			// double and only rounding at draw time avoids the 1-2 degree gap
			// that integer angles leave at the end of the circle.
			double startAngle = 90.0;

			for (int i = 0; i < slices.size(); i++)
			{
				ItemAggregator.Slice slice = slices.get(i);
				double extent = -360.0 * ((double) slice.value / (double) total);

				g2.setColor(colorFor(i, slice));
				g2.fill(new Arc2D.Double(originX, originY, DIAMETER, DIAMETER,
					startAngle, extent, Arc2D.PIE));

				startAngle += extent;
			}

			// Punch the middle out to make it a donut, then ring it so adjacent
			// same-ish colours still read as separate wedges.
			int innerDiameter = (int) (DIAMETER * DONUT_INNER_RATIO);
			int innerOffset = (DIAMETER - innerDiameter) / 2;
			g2.setColor(getBackground());
			g2.fill(new Ellipse2D.Double(originX + innerOffset, originY + innerOffset,
				innerDiameter, innerDiameter));

			g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
			g2.setStroke(new BasicStroke(1f));
			g2.draw(new Ellipse2D.Double(originX, originY, DIAMETER, DIAMETER));

			// Total in the hole.
			String centre = valuesAreGp ? Format.gp(total) : Format.quantity(total);
			g2.setColor(ColorScheme.BRAND_ORANGE);
			FontMetrics fm = g2.getFontMetrics();
			g2.drawString(centre,
				cx - fm.stringWidth(centre) / 2,
				originY + DIAMETER / 2 + fm.getAscent() / 2 - 2);
		}

		private void paintLegend(Graphics2D g2)
		{
			FontMetrics fm = g2.getFontMetrics();
			int y = DIAMETER + 20;
			int textWidth = getWidth() - (SWATCH + 12);

			for (int i = 0; i < slices.size(); i++)
			{
				ItemAggregator.Slice slice = slices.get(i);
				double pct = 100.0 * slice.value / total;

				g2.setColor(colorFor(i, slice));
				g2.fillRect(4, y - SWATCH + 2, SWATCH, SWATCH);

				String amount = valuesAreGp ? Format.gp(slice.value) : Format.quantity(slice.value);
				String right = String.format("%.1f%%", pct);
				String left = slice.label + "  " + amount;

				g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				int rightWidth = fm.stringWidth(right);
				g2.drawString(truncate(fm, left, textWidth - rightWidth - 6), SWATCH + 8, y);

				g2.setColor(ColorScheme.BRAND_ORANGE);
				g2.drawString(right, getWidth() - rightWidth - 4, y);

				y += LEGEND_ROW_HEIGHT;
			}
		}

		/** "Other" always takes the grey at the end of the palette. */
		private Color colorFor(int index, ItemAggregator.Slice slice)
		{
			if (slice.accountHash == 0L && slice.label.startsWith("Other"))
			{
				return PALETTE[PALETTE.length - 1];
			}
			return PALETTE[index % (PALETTE.length - 1)];
		}

		private static String truncate(FontMetrics fm, String text, int maxWidth)
		{
			if (maxWidth <= 0 || fm.stringWidth(text) <= maxWidth)
			{
				return text;
			}
			String ellipsis = "...";
			int available = maxWidth - fm.stringWidth(ellipsis);
			if (available <= 0)
			{
				return ellipsis;
			}
			int end = text.length();
			while (end > 0 && fm.stringWidth(text.substring(0, end)) > available)
			{
				end--;
			}
			return text.substring(0, end) + ellipsis;
		}
	}
}

package com.accountalmanac;

import java.awt.BorderLayout;
import java.awt.Font;
import java.awt.Insets;
import java.util.Comparator;
import java.util.List;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar panel: combined wealth across every tracked account, the most recent
 * login, any accounts overdue for one, a button that opens the full
 * {@link WealthViewerFrame}, filter and sort controls, then one
 * {@link AccountRowPanel} per account.
 *
 * <p>The sidebar deliberately stays a summary. A {@code PluginPanel} is
 * fixed at roughly 225px wide, so the item tables and charts live in the
 * separate viewer window instead.
 */
class AlmanacSidebarPanel extends PluginPanel
{
	/**
	 * Sort fields. Direction is a separate control rather than being baked into
	 * the list - "Wealth (high to low)" and "Wealth (low to high)" as two
	 * entries doubles the dropdown for every field added, and left "Recently
	 * updated" with no way to see the least recently updated at all, which is
	 * usually the more useful question.
	 */
	private static final String SORT_WEALTH = "Wealth";
	private static final String SORT_NAME = "Name";
	private static final String SORT_RECENT = "Recently updated";
	private static final String SORT_LAST_LOGIN = "Last login";
	private static final String SORT_COMBAT = "Combat level";
	private static final String SORT_TOTAL_LEVEL = "Total level";
	private static final String SORT_BANK_SEEN = "Bank last seen";

	/** Down-pointing triangle, the conventional "descending" marker. */
	private static final String ARROW_DESC = "▼";
	private static final String ARROW_ASC = "▲";

	private final AccountStore store;
	private final HistoryStore historyStore;
	private final GeEventStore geEventStore;
	private final AccountAlmanacConfig config;
	private final ConfigManager configManager;
	private final AccountAlmanacPlugin plugin;
	private final ItemManager itemManager;
	private final SkillIconManager skillIconManager;
	private final SpriteManager spriteManager;

	private final JLabel totalLabel = new JLabel();
	private final JLabel breakdownLabel = new JLabel();
	private final JLabel lastLoginLabel = new JLabel();
	private final JLabel reminderLabel = new JLabel();
	private final JButton viewerButton = new JButton("Open bank viewer");
	private final JPanel rowsContainer = new JPanel();
	private final JComboBox<String> groupBox = new JComboBox<>();
	private final JComboBox<String> sortBox = new JComboBox<>(new String[] {
		SORT_WEALTH, SORT_NAME, SORT_RECENT, SORT_LAST_LOGIN,
		SORT_COMBAT, SORT_TOTAL_LEVEL, SORT_BANK_SEEN
	});

	private final JButton sortDirectionButton = new JButton();

	/**
	 * Which way the chosen field sorts. Reset to the field's natural direction
	 * when the field changes - biggest wealth and most recent activity are what
	 * you almost always want first, but A to Z is the natural reading for a
	 * name, so a single global default would be wrong half the time.
	 */
	private boolean sortDescending = true;

	/**
	 * Guards the group dropdown against firing a rebuild while {@link #rebuild}
	 * is repopulating it, which would recurse.
	 */
	private boolean updatingGroups;

	private WealthViewerFrame viewer;

	AlmanacSidebarPanel(AccountStore store, HistoryStore historyStore, GeEventStore geEventStore,
		AccountAlmanacConfig config, ConfigManager configManager,
		AccountAlmanacPlugin plugin, ItemManager itemManager,
		SkillIconManager skillIconManager, SpriteManager spriteManager)
	{
		super();
		this.store = store;
		this.historyStore = historyStore;
		this.geEventStore = geEventStore;
		this.config = config;
		this.configManager = configManager;
		this.plugin = plugin;
		this.spriteManager = spriteManager;
		this.itemManager = itemManager;
		this.skillIconManager = skillIconManager;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(buildHeader(), BorderLayout.NORTH);

		rowsContainer.setLayout(new BoxLayout(rowsContainer, BoxLayout.Y_AXIS));
		rowsContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(rowsContainer, BorderLayout.CENTER);
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(new EmptyBorder(8, 8, 8, 8));

		totalLabel.setForeground(ColorScheme.BRAND_ORANGE);
		totalLabel.setFont(totalLabel.getFont().deriveFont(Font.BOLD, 15f));
		totalLabel.setAlignmentX(LEFT_ALIGNMENT);

		breakdownLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		breakdownLabel.setFont(FontManager.getRunescapeSmallFont());
		breakdownLabel.setAlignmentX(LEFT_ALIGNMENT);

		// The most recent login is the first thing asked for on the main tab,
		// so it sits directly under the headline total rather than in a table.
		lastLoginLabel.setFont(FontManager.getRunescapeSmallFont());
		lastLoginLabel.setAlignmentX(LEFT_ALIGNMENT);

		reminderLabel.setFont(FontManager.getRunescapeSmallFont());
		reminderLabel.setAlignmentX(LEFT_ALIGNMENT);

		viewerButton.setAlignmentX(LEFT_ALIGNMENT);
		viewerButton.setToolTipText("Open the full cross-account item table and charts");
		viewerButton.addActionListener(e -> openViewer());

		JPanel groupRow = new JPanel(new BorderLayout(4, 0));
		groupRow.setOpaque(false);
		groupRow.setAlignmentX(LEFT_ALIGNMENT);
		JLabel groupLabel = new JLabel("Group: ");
		groupLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		groupBox.addActionListener(e ->
		{
			if (!updatingGroups)
			{
				rebuild();
			}
		});
		groupRow.add(groupLabel, BorderLayout.WEST);
		groupRow.add(groupBox, BorderLayout.CENTER);

		JPanel sortRow = new JPanel(new BorderLayout(4, 0));
		sortRow.setOpaque(false);
		sortRow.setAlignmentX(LEFT_ALIGNMENT);
		JLabel sortLabel = new JLabel("Sort: ");
		sortLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		sortBox.addActionListener(e ->
		{
			if (!updatingGroups)
			{
				sortDescending = defaultDescendingFor((String) sortBox.getSelectedItem());
				rebuild();
			}
		});

		// Plain UI font rather than the RuneScape one: the triangles are not in
		// the game font and would render as missing-glyph boxes.
		sortDirectionButton.setMargin(new Insets(1, 4, 1, 4));
		sortDirectionButton.addActionListener(e ->
		{
			sortDescending = !sortDescending;
			rebuild();
		});

		sortRow.add(sortLabel, BorderLayout.WEST);
		sortRow.add(sortBox, BorderLayout.CENTER);
		sortRow.add(sortDirectionButton, BorderLayout.EAST);

		header.add(totalLabel);
		header.add(Box.createVerticalStrut(2));
		header.add(breakdownLabel);
		header.add(Box.createVerticalStrut(4));
		header.add(lastLoginLabel);
		header.add(Box.createVerticalStrut(2));
		header.add(reminderLabel);
		header.add(Box.createVerticalStrut(8));
		header.add(viewerButton);
		header.add(Box.createVerticalStrut(8));
		header.add(groupRow);
		header.add(Box.createVerticalStrut(4));
		header.add(sortRow);

		return header;
	}

	private void openViewer()
	{
		ensureViewer();
		viewer.reload();
		showViewerWindow();
	}

	/** Opens the viewer already switched to one account's Stats tab. */
	private void openViewerToStats(long accountHash)
	{
		ensureViewer();
		viewer.reload();
		viewer.showStats(accountHash);
		showViewerWindow();
	}

	private void ensureViewer()
	{
		if (viewer == null)
		{
			viewer = new WealthViewerFrame(store, historyStore, geEventStore, config,
				configManager, plugin, itemManager, skillIconManager, spriteManager);
		}
	}

	private void showViewerWindow()
	{
		// No toFront() or requestFocus(): hub plugins may not change which
		// window is focused.
		viewer.setVisible(true);
	}

	/**
	 * Disposes the viewer window if it is open. Called from the plugin's
	 * {@code shutDown()} so disabling the plugin does not strand a frame
	 * holding a reference to the old store.
	 */
	void closeViewer()
	{
		WealthViewerFrame current = viewer;
		viewer = null;
		if (current != null)
		{
			SwingUtilities.invokeLater(current::dispose);
		}
	}

	void rebuild()
	{
		List<AccountRecord> all = store.getAccounts();
		long now = System.currentTimeMillis();
		boolean includeGe = config.includeGrandExchange();

		refreshGroupOptions(all);
		List<AccountRecord> accounts = AccountFilter.apply(all, (String) groupBox.getSelectedItem());

		// Totals follow the same rule everywhere: hidden accounts do not count.
		// Using the filtered list here would make the headline total change
		// whenever the user browsed a group, which is a filter, not a total.
		List<AccountRecord> counted = AccountFilter.visibleOnly(all);

		long bankTotal = 0L;
		long geTotal = 0L;
		for (AccountRecord record : counted)
		{
			bankTotal += record.bankValue;
			geTotal += record.geValue();
		}
		long grand = includeGe ? bankTotal + geTotal : bankTotal;

		totalLabel.setText(Format.gp(grand));
		totalLabel.setToolTipText(Format.exact(grand) + " gp");

		int hiddenCount = AccountFilter.hiddenCount(all);
		breakdownLabel.setText(String.format("across %d account%s%s%s",
			counted.size(),
			counted.size() == 1 ? "" : "s",
			includeGe && geTotal > 0 ? "  (" + Format.gp(geTotal) + " in GE)" : "",
			hiddenCount > 0 ? "  [" + hiddenCount + " hidden]" : ""));

		updateLastLoginLabel(all, now);
		updateReminderLabel(all, now);

		String sortField = (String) sortBox.getSelectedItem();
		updateSortDirectionButton(sortField);
		accounts.sort(comparatorFor(sortField, sortDescending));

		rowsContainer.removeAll();
		if (accounts.isEmpty())
		{
			JLabel empty = new JLabel("<html>No accounts tracked yet.<br><br>"
				+ "Log into an account through this client to add it, then open its "
				+ "bank to record the contents.</html>");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setBorder(new EmptyBorder(8, 8, 8, 8));
			rowsContainer.add(empty);
		}
		else
		{
			for (AccountRecord record : accounts)
			{
				long hash = record.accountHash;
				rowsContainer.add(new AccountRowPanel(record, store, config,
					this::rebuild, () -> openViewerToStats(hash), () -> removeAccount(hash)));
				rowsContainer.add(Box.createVerticalStrut(4));
			}
		}

		// Re-applied after the rows are rebuilt, since they are new components
		// each time and would otherwise come back in the default palette.
		ThemeApplier.apply(this, config.viewerTheme());

		rowsContainer.revalidate();
		rowsContainer.repaint();

		WealthViewerFrame current = viewer;
		if (current != null && current.isVisible())
		{
			current.reload();
		}
	}

	/**
	 * Deletes an account from all three stores. Kept here rather than in the
	 * row because the row only holds the account store - leaving history and
	 * GE events behind would resurrect a "removed" account's data the moment
	 * anything aggregated across those files.
	 */
	private void removeAccount(long accountHash)
	{
		store.removeAccount(accountHash);
		historyStore.removeAccount(accountHash);
		geEventStore.removeAccount(accountHash);
		rebuild();
	}

	/**
	 * The single most recently played account, stated in full local date and
	 * time. This is the "when was I last on" answer, so it is spelled out
	 * rather than abbreviated to a relative age.
	 */
	private void updateLastLoginLabel(List<AccountRecord> accounts, long now)
	{
		AccountRecord mostRecent = null;
		for (AccountRecord record : accounts)
		{
			if (record.lastLoginAt <= 0L)
			{
				continue;
			}
			if (mostRecent == null || record.lastLoginAt > mostRecent.lastLoginAt)
			{
				mostRecent = record;
			}
		}

		if (mostRecent == null)
		{
			lastLoginLabel.setText("No logins recorded yet");
			lastLoginLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			lastLoginLabel.setToolTipText(null);
			return;
		}

		// No <b> here. This label is set in the RuneScape small font, which
		// has no bold face, so Swing synthesises one by double-striking the
		// glyphs - which renders as a blur beside the crisp text around it.
		lastLoginLabel.setText("<html>Last login: "
			+ escape(NameMasker.display(mostRecent, config.namePrivacy())) + "<br>"
			+ LoginAge.friendly(mostRecent.lastLoginAt) + "</html>");
		lastLoginLabel.setForeground(LoginAgeColours.forTimestamp(mostRecent.lastLoginAt, now, config));
		lastLoginLabel.setToolTipText(LoginAge.describeAge(mostRecent.lastLoginAt, now)
			+ " - " + LoginAge.exact(mostRecent.lastLoginAt));
	}

	private void updateReminderLabel(List<AccountRecord> accounts, long now)
	{
		List<LoginReminders.Reminder> due = LoginReminders.overdue(accounts, now,
			config.reminderAfterDays(), config.remindOnlyWithOffers());

		if (due.isEmpty())
		{
			reminderLabel.setText("No accounts overdue");
			reminderLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			reminderLabel.setToolTipText(null);
			return;
		}

		reminderLabel.setText(due.size() + (due.size() == 1 ? " account" : " accounts")
			+ " overdue (" + config.reminderAfterDays() + "d+)");
		reminderLabel.setForeground(config.staleLoginColour());

		// The full list belongs in a tooltip rather than the sidebar; forty
		// accounts of reminders would push everything else off screen.
		StringBuilder tip = new StringBuilder("<html>");
		int shown = 0;
		for (LoginReminders.Reminder reminder : due)
		{
			if (shown++ == 12)
			{
				tip.append("...and ").append(due.size() - 12).append(" more");
				break;
			}
			tip.append(escape(reminder.describe(config.namePrivacy()))).append("<br>");
		}
		tip.append("</html>");
		reminderLabel.setToolTipText(tip.toString());
	}

	/**
	 * Repopulates the group dropdown, preserving the current selection when it
	 * still exists. Rebuilt on every refresh because categories appear and
	 * disappear as the user assigns them.
	 */
	private void refreshGroupOptions(List<AccountRecord> accounts)
	{
		List<String> groups = AccountFilter.groupsFor(accounts);
		String selected = (String) groupBox.getSelectedItem();

		if (matchesCurrentModel(groups))
		{
			return;
		}

		updatingGroups = true;
		try
		{
			groupBox.setModel(new DefaultComboBoxModel<>(groups.toArray(new String[0])));
			groupBox.setSelectedItem(groups.contains(selected) ? selected : AccountFilter.ALL_VISIBLE);
		}
		finally
		{
			updatingGroups = false;
		}
	}

	private boolean matchesCurrentModel(List<String> groups)
	{
		if (groupBox.getItemCount() != groups.size())
		{
			return false;
		}
		for (int i = 0; i < groups.size(); i++)
		{
			if (!groups.get(i).equals(groupBox.getItemAt(i)))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Ascending comparator for a field; the caller reverses it for descending.
	 * Building it one way round and flipping keeps the two directions exactly
	 * consistent, rather than two hand-written comparators that can disagree on
	 * tie-breaks.
	 */
	private static Comparator<AccountRecord> ascendingFor(String sortField)
	{
		if (SORT_NAME.equals(sortField))
		{
			return Comparator.comparing(AccountRecord::label, String.CASE_INSENSITIVE_ORDER);
		}
		if (SORT_RECENT.equals(sortField))
		{
			return Comparator.comparingLong(AccountRecord::lastActivityAt);
		}
		if (SORT_LAST_LOGIN.equals(sortField))
		{
			// Strictly the login timestamp, unlike "Recently updated" which
			// also counts bank snapshots.
			return Comparator.comparingLong(r -> r.lastLoginAt);
		}
		if (SORT_COMBAT.equals(sortField))
		{
			return Comparator.comparingInt(r -> r.combatLevel);
		}
		if (SORT_TOTAL_LEVEL.equals(sortField))
		{
			return Comparator.comparingInt(AccountRecord::totalLevel);
		}
		if (SORT_BANK_SEEN.equals(sortField))
		{
			return Comparator.comparingLong(r -> r.lastSnapshotAt);
		}
		return Comparator.comparingLong(AccountRecord::totalWealth);
	}

	private static Comparator<AccountRecord> comparatorFor(String sortField, boolean descending)
	{
		Comparator<AccountRecord> ascending = ascendingFor(sortField);
		return descending ? ascending.reversed() : ascending;
	}

	/** The direction a field is most often wanted in when first selected. */
	private static boolean defaultDescendingFor(String sortField)
	{
		// A to Z reads naturally for a name; everything else here is a number
		// or a date, where the largest or most recent is the interesting end.
		return !SORT_NAME.equals(sortField);
	}

	/**
	 * Points the arrow the right way and explains what it means for the field
	 * currently chosen - "newest first" and "highest first" are the same
	 * direction but not the same words, and an unlabelled triangle leaves the
	 * user guessing which.
	 */
	private void updateSortDirectionButton(String sortField)
	{
		sortDirectionButton.setText(sortDescending ? ARROW_DESC : ARROW_ASC);
		sortDirectionButton.setToolTipText("Sorted " + describeDirection(sortField)
			+ " - click to reverse");
	}

	private String describeDirection(String sortField)
	{
		if (SORT_NAME.equals(sortField))
		{
			return sortDescending ? "Z to A" : "A to Z";
		}
		if (SORT_RECENT.equals(sortField) || SORT_LAST_LOGIN.equals(sortField)
			|| SORT_BANK_SEEN.equals(sortField))
		{
			return sortDescending ? "most recent first" : "least recent first";
		}
		return sortDescending ? "highest first" : "lowest first";
	}

	/** Minimal escaping for the HTML-rendered labels above. */
	static String escape(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.accountalmanac;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * One account's summary row in the sidebar: name, combat level, wealth
 * split between bank and GE, when its bank was last seen, and controls for
 * the user-editable login label and note.
 *
 * <p>Rebuilt wholesale by {@link AlmanacSidebarPanel} rather than mutated
 * in place, so it holds no listeners that would need unregistering.
 */
class AccountRowPanel extends JPanel
{
	private final AccountRecord record;
	private final AccountStore store;
	private final AccountAlmanacConfig config;
	private final Runnable onChanged;
	private final Runnable onRemove;

	/**
	 * @param onOpenStats double-click handler over the details area - opens
	 *                    the wealth viewer's Stats tab for this account
	 * @param onRemove    performs the actual deletion once both confirmations
	 *                    pass. Injected rather than done here because removing
	 *                    an account has to clear its snapshot history and GE
	 *                    events too, and those stores live a level up
	 */
	AccountRowPanel(AccountRecord record, AccountStore store,
		AccountAlmanacConfig config, Runnable onChanged, Runnable onOpenStats,
		Runnable onRemove)
	{
		this.record = record;
		this.store = store;
		this.config = config;
		this.onChanged = onChanged;
		this.onRemove = onRemove;

		setLayout(new BorderLayout());
		// A hidden account is dimmed rather than removed, so it is obvious at a
		// glance that it is present but excluded from the totals.
		setBackground(record.hidden
			? ColorScheme.DARK_GRAY_COLOR
			: ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 250));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel details = buildDetails(config);
		details.setToolTipText("Double-click to view stats");
		details.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		// A plain MouseListener on the container alone only fires for gaps
		// between the labels - Swing delivers clicks to the deepest
		// component under the cursor, and a JLabel with no listener of its
		// own just swallows the event rather than passing it up. Attaching
		// the same listener to every child as well is what makes the whole
		// row double-clickable, not just the padding around the text.
		attachDoubleClick(details, onOpenStats);

		add(details, BorderLayout.CENTER);
		add(buildActions(), BorderLayout.SOUTH);
	}

	private static void attachDoubleClick(Component component, Runnable action)
	{
		component.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getClickCount() == 2)
				{
					action.run();
				}
			}
		});
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				attachDoubleClick(child, action);
			}
		}
	}

	private JPanel buildDetails(AccountAlmanacConfig config)
	{
		JPanel details = new JPanel();
		details.setLayout(new BoxLayout(details, BoxLayout.Y_AXIS));
		details.setOpaque(false);

		JLabel name = new JLabel(NameMasker.display(record, config.namePrivacy()));
		name.setForeground(ColorScheme.BRAND_ORANGE);
		name.setFont(name.getFont().deriveFont(Font.BOLD, 13f));

		boolean hasIronBadge = AccountTypeBadge.isIronmanVariant(record.accountType);
		if (hasIronBadge || record.banned || record.hidden)
		{
			JPanel nameRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
			nameRow.setOpaque(false);
			nameRow.setAlignmentX(LEFT_ALIGNMENT);
			nameRow.add(name);
			if (hasIronBadge)
			{
				nameRow.add(buildTypeBadge());
			}
			if (record.banned)
			{
				nameRow.add(buildBadge("BANNED", config.staleLoginColour(),
					"Marked banned" + (record.bannedAt > 0L
						? " on " + LoginAge.exact(record.bannedAt)
						: "")));
			}
			if (record.hidden)
			{
				nameRow.add(buildBadge("HIDDEN", ColorScheme.MEDIUM_GRAY_COLOR,
					"Excluded from wealth totals and statistics"));
			}
			details.add(nameRow);
		}
		else
		{
			name.setAlignmentX(LEFT_ALIGNMENT);
			details.add(name);
		}

		long wealth = config.includeGrandExchange() ? record.totalWealth() : record.bankValue;
		JLabel value = new JLabel(Format.gp(wealth));
		value.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		value.setToolTipText(Format.exact(wealth) + " gp");
		value.setAlignmentX(LEFT_ALIGNMENT);
		details.add(value);

		long geValue = record.geValue();
		if (geValue > 0L)
		{
			details.add(small("GE: " + Format.gp(geValue)));
		}

		// Two short lines rather than one long one: the sidebar is narrow, and
		// everything on a single row was being cut off mid-number.
		StringBuilder levels = new StringBuilder();
		if (record.combatLevel > 0)
		{
			levels.append("cb ").append(record.combatLevel);
		}
		if (record.totalLevel() > 0)
		{
			if (levels.length() > 0)
			{
				levels.append("  -  ");
			}
			levels.append(Format.exact(record.totalLevel())).append(" total");
		}
		if (levels.length() > 0)
		{
			details.add(small(levels.toString()));
		}

		StringBuilder counts = new StringBuilder();
		if (record.hasQuestPoints())
		{
			counts.append(record.questPointsLabel()).append(" qp");
		}
		int stacks = record.bankStackCount();
		if (stacks > 0)
		{
			if (counts.length() > 0)
			{
				counts.append("  -  ");
			}
			counts.append(Format.exact(stacks)).append(" items");
		}
		if (counts.length() > 0)
		{
			details.add(small(counts.toString()));
		}

		// Last login gets its own coloured line rather than being folded into
		// the meta row - it is the field most often being scanned for, and the
		// colour is the whole point of the green/yellow/red thresholds.
		long now = System.currentTimeMillis();
		JLabel lastLogin = small("last login: " + LoginAge.describeAge(record.lastLoginAt, now));
		lastLogin.setForeground(LoginAgeColours.forTimestamp(record.lastLoginAt, now, config));
		lastLogin.setToolTipText(record.lastLoginAt > 0L
			? LoginAge.friendly(record.lastLoginAt)
			: "This account has not been logged into since tracking began");
		details.add(lastLogin);

		String category = record.categoryLabel();
		if (!category.isEmpty())
		{
			details.add(small("group: " + category));
		}

		// "never opened" is meaningfully different from an empty bank: the
		// client simply has not seen this account's bank yet.
		details.add(small(record.hasBankSnapshot()
			? "bank seen " + Format.relativeTime(record.lastSnapshotAt)
			: "bank never opened"));

		int activeOffers = 0;
		for (GrandExchangeRecord offer : record.geOffers)
		{
			if (offer.isActive())
			{
				activeOffers++;
			}
		}
		if (activeOffers > 0)
		{
			details.add(small(activeOffers + (activeOffers == 1 ? " GE offer" : " GE offers")));
		}

		if (record.loginName != null && !record.loginName.isEmpty())
		{
			details.add(small("login name: "
				+ NameMasker.displayField(record.loginName, record.accountHash, config.namePrivacy())));
		}
		if (record.loginLabel != null && !record.loginLabel.isEmpty())
		{
			details.add(small("label: "
				+ NameMasker.displayField(record.loginLabel, record.accountHash, config.namePrivacy())));
		}
		if (record.note != null && !record.note.isEmpty())
		{
			details.add(small("note: " + record.note));
		}

		return details;
	}

	private JLabel small(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * Small filled pill (e.g. "HCIM") next to the account name. Painted
	 * directly rather than styled via a border, so the pill's rounded shape
	 * and fill are pixel-exact regardless of look-and-feel.
	 */
	/**
	 * The account type marker: the game's own helm icon where one exists,
	 * otherwise the text pill. Group ironman has no bundled art, and a failed
	 * image load returns null, so both fall through to text rather than
	 * leaving a gap where the marker should be.
	 */
	private JLabel buildTypeBadge()
	{
		BufferedImage icon = AccountTypeBadge.icon(record.accountType);
		if (icon != null)
		{
			JLabel badge = new JLabel(new ImageIcon(icon));
			badge.setToolTipText(AccountTypeBadge.fullLabel(record.accountType));
			return badge;
		}
		return buildBadge(
			AccountTypeBadge.shortLabel(record.accountType),
			AccountTypeBadge.color(record.accountType),
			AccountTypeBadge.fullLabel(record.accountType));
	}

	private JLabel buildBadge(String text, Color background, String tooltip)
	{
		JLabel badge = new JLabel(text)
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				try
				{
					g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
						RenderingHints.VALUE_ANTIALIAS_ON);
					g2.setColor(background);
					g2.fillRoundRect(0, 0, getWidth(), getHeight(), 8, 8);
				}
				finally
				{
					g2.dispose();
				}
				super.paintComponent(g);
			}
		};
		badge.setOpaque(false);
		badge.setForeground(Color.WHITE);
		badge.setFont(FontManager.getRunescapeSmallFont());
		badge.setHorizontalAlignment(SwingConstants.CENTER);
		badge.setBorder(BorderFactory.createEmptyBorder(1, 6, 1, 6));
		badge.setToolTipText(tooltip);
		return badge;
	}

	private JPanel buildActions()
	{
		JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
		actions.setOpaque(false);

		actions.add(button("Label", "Set a login label for this account", e -> editLoginLabel()));
		actions.add(button("Note", "Set a free-text note for this account", e -> editNote()));
		actions.add(button("Group", "Set this account's grouping, e.g. Main, Pure, Zerker",
			e -> editCategory()));
		actions.add(button(record.hidden ? "Unhide" : "Hide",
			record.hidden
				? "Count this account towards wealth totals and statistics again"
				: "Exclude this account from wealth totals and statistics, without deleting it",
			e -> toggleHidden()));
		actions.add(button(record.banned ? "Un-ban" : "Banned",
			record.banned
				? "Clear the banned flag on this account"
				: "Mark this account as banned",
			e -> toggleBanned()));
		actions.add(Box.createHorizontalStrut(4));
		actions.add(button("Remove", "Stop tracking this account", e -> confirmRemove()));

		return actions;
	}

	private JButton button(String text, String tooltip, java.awt.event.ActionListener listener)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setToolTipText(tooltip);
		button.setMargin(new java.awt.Insets(1, 5, 1, 5));
		button.addActionListener(listener);
		return button;
	}

	private void editLoginLabel()
	{
		String updated = (String) JOptionPane.showInputDialog(this,
			"Label identifying which login this account belongs to.\n"
				+ "This is a nickname only - never store a password here.",
			"Login label",
			JOptionPane.PLAIN_MESSAGE, null, null, record.loginLabel);

		if (updated != null)
		{
			store.updateLoginLabel(record.accountHash, updated.trim());
			onChanged.run();
		}
	}

	private void editNote()
	{
		String updated = (String) JOptionPane.showInputDialog(this,
			"Note for " + NameMasker.display(record, config.namePrivacy()),
			"Account note",
			JOptionPane.PLAIN_MESSAGE, null, null, record.note);

		if (updated != null)
		{
			store.updateNote(record.accountHash, updated.trim());
			onChanged.run();
		}
	}

	/**
	 * Editable combo rather than a fixed list, so the presets are one click
	 * away but a grouping the user invents still works.
	 */
	private void editCategory()
	{
		JComboBox<String> input = new JComboBox<>(
			AccountCategory.presetLabels().toArray(new String[0]));
		input.setEditable(true);
		input.setSelectedItem(record.category == null ? "" : record.category);

		int result = JOptionPane.showConfirmDialog(this, input,
			"Group for " + NameMasker.display(record, config.namePrivacy()),
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);

		if (result == JOptionPane.OK_OPTION)
		{
			Object selected = input.getSelectedItem();
			store.updateCategory(record.accountHash,
				selected == null ? "" : selected.toString());
			onChanged.run();
		}
	}

	/**
	 * Hiding needs no confirmation - it destroys nothing and the button
	 * immediately offers to undo itself.
	 */
	private void toggleHidden()
	{
		store.updateHidden(record.accountHash, !record.hidden);
		onChanged.run();
	}

	private void toggleBanned()
	{
		store.updateBanned(record.accountHash, !record.banned);
		onChanged.run();
	}

	/**
	 * Two separate confirmations, not one dialog worded strongly - a second
	 * dialog is a second deliberate click, which a single "are you sure"
	 * does not force. Removal deletes the account's entire stored history
	 * (bank snapshot, GE offers, skills) with no undo.
	 */
	private void confirmRemove()
	{
		int first = JOptionPane.showConfirmDialog(this,
			"Stop tracking " + NameMasker.display(record, config.namePrivacy()) + "?\n\n"
				+ "This deletes its stored bank snapshot, GE offers, skill history, "
				+ "wealth snapshots and Grand Exchange event log. There is no undo.",
			"Remove account",
			JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);

		if (first != JOptionPane.YES_OPTION)
		{
			return;
		}

		int second = JOptionPane.showConfirmDialog(this,
			"Really remove " + NameMasker.display(record, config.namePrivacy())
				+ "? This cannot be undone.",
			"Confirm removal",
			JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);

		if (second == JOptionPane.YES_OPTION)
		{
			onRemove.run();
		}
	}
}

package com.accountalmanac;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;

/**
 * Display strings and colors for an {@code AccountRecord.accountType}
 * value - the raw {@code AccountType.name()} string, e.g. {@code
 * "IRONMAN"}.
 *
 * <h2>Where the icons come from</h2>
 *
 * <p>The game's own account-type sprites exist ({@code SpriteID.AccountIcons}
 * and {@code SpriteID.IronIcons}) but their constants are still unnamed
 * ({@code _0}..{@code _5}) with no documented mapping to an
 * {@code AccountType}. Guessing which index is which risks labelling a
 * Hardcore Ironman as a regular one, which is worse than no icon at all.
 *
 * <p>RuneLite itself ships the real 18x18 helm icons as ordinary resources
 * for its hiscore panel, keyed by name rather than by index. Those are used
 * here: correct art, no guesswork, and no second copy of an asset that is
 * already on the classpath. They are loaded by resource path rather than by
 * referencing the owning plugin class, so this does not compile-depend on
 * another plugin's internals.
 *
 * <p>Group ironman has no bundled icon, so those keep the text badge. Every
 * lookup falls back to text if the resource is missing, because an icon that
 * fails to load must degrade to a readable label rather than to nothing.
 */
@Slf4j
final class AccountTypeBadge
{
	/** RuneLite's own hiscore panel icons - the official helm art. */
	private static final String ICON_PATH = "/net/runelite/client/plugins/hiscore/";

	/** Loaded once and reused; a miss is cached as absent so it is not retried per repaint. */
	private static final Map<String, BufferedImage> ICONS = new HashMap<>();

	private AccountTypeBadge()
	{
	}

	/**
	 * Helm icon for an account type, or {@code null} when there is none - a
	 * normal account, a group ironman, or a resource that failed to load.
	 * Callers fall back to {@link #shortLabel}.
	 */
	static synchronized BufferedImage icon(String accountType)
	{
		String file = iconFileFor(accountType);
		if (file == null)
		{
			return null;
		}
		if (ICONS.containsKey(file))
		{
			return ICONS.get(file);
		}

		BufferedImage loaded = null;
		try (InputStream in = AccountTypeBadge.class.getResourceAsStream(ICON_PATH + file))
		{
			if (in != null)
			{
				loaded = ImageIO.read(in);
			}
			else
			{
				log.debug("Account type icon {} not present; falling back to a text badge", file);
			}
		}
		catch (IOException e)
		{
			log.debug("Could not read account type icon {}", file, e);
		}

		// Cached even when null, so a missing resource is looked up once.
		ICONS.put(file, loaded);
		return loaded;
	}

	private static String iconFileFor(String accountType)
	{
		switch (accountType)
		{
			case "IRONMAN":
				return "ironman.png";
			case "HARDCORE_IRONMAN":
				return "hardcore_ironman.png";
			case "ULTIMATE_IRONMAN":
				return "ultimate_ironman.png";
			default:
				// Group ironman variants have no bundled art.
				return null;
		}
	}

	/** "" for a normal or not-yet-known account - callers should skip the badge entirely in that case. */
	static String shortLabel(String accountType)
	{
		switch (accountType)
		{
			case "IRONMAN":
				return "IM";
			case "HARDCORE_IRONMAN":
				return "HCIM";
			case "ULTIMATE_IRONMAN":
				return "UIM";
			case "GROUP_IRONMAN":
				return "GIM";
			case "HARDCORE_GROUP_IRONMAN":
				return "HCGIM";
			default:
				return "";
		}
	}

	/** Full name for tables and tooltips. "-" when never captured. */
	static String fullLabel(String accountType)
	{
		switch (accountType)
		{
			case "NORMAL":
				return "Normal";
			case "IRONMAN":
				return "Ironman";
			case "HARDCORE_IRONMAN":
				return "Hardcore Ironman";
			case "ULTIMATE_IRONMAN":
				return "Ultimate Ironman";
			case "GROUP_IRONMAN":
				return "Group Ironman";
			case "HARDCORE_GROUP_IRONMAN":
				return "Hardcore Group Ironman";
			default:
				return "-";
		}
	}

	static Color color(String accountType)
	{
		switch (accountType)
		{
			case "IRONMAN":
				return new Color(150, 111, 51);
			case "HARDCORE_IRONMAN":
				return new Color(178, 34, 34);
			case "ULTIMATE_IRONMAN":
				return new Color(50, 50, 50);
			case "GROUP_IRONMAN":
				return new Color(46, 125, 87);
			case "HARDCORE_GROUP_IRONMAN":
				return new Color(150, 40, 40);
			default:
				return Color.GRAY;
		}
	}

	static boolean isIronmanVariant(String accountType)
	{
		return !shortLabel(accountType).isEmpty();
	}
}

package com.accountalmanac;

import java.util.Map;

/**
 * The standard OSRS combat level formula, computed from real (unboosted)
 * skill levels. See https://oldschool.runescape.wiki/w/Combat_level.
 */
final class CombatLevel
{
	private CombatLevel()
	{
	}

	static int calculate(Map<String, Integer> skills)
	{
		int attack = skills.getOrDefault("ATTACK", 1);
		int strength = skills.getOrDefault("STRENGTH", 1);
		int defence = skills.getOrDefault("DEFENCE", 1);
		int hitpoints = skills.getOrDefault("HITPOINTS", 10);
		int prayer = skills.getOrDefault("PRAYER", 1);
		int ranged = skills.getOrDefault("RANGED", 1);
		int magic = skills.getOrDefault("MAGIC", 1);

		double base = 0.25 * (defence + hitpoints + Math.floor(prayer / 2.0));
		double melee = 0.325 * (attack + strength);
		double range = 0.325 * Math.floor(3 * ranged / 2.0);
		double mage = 0.325 * Math.floor(3 * magic / 2.0);

		return (int) Math.floor(base + Math.max(melee, Math.max(range, mage)));
	}
}

package com.accountalmanac;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Turns a real account name into whatever the privacy setting says to show.
 *
 * <p>Strictly a display concern. The stored roster, the Grand Exchange event
 * log and the backups all keep real names - {@link AccountRecord#label()} is
 * the persistence-safe accessor and is deliberately left alone, because that is
 * what gets written into logged events. Masking anything on the way to disk
 * would quietly corrupt the user's own records.
 *
 * <p>Mirrors the web viewer's implementation so the two agree on which stand-in
 * belongs to which account.
 */
final class NameMasker
{
	/**
	 * Paired adjective and noun, deliberately RuneScape-flavoured. A stand-in
	 * that reads as a plausible account name makes a shared screenshot look
	 * normal, which is the point - obviously redacted names invite the question
	 * of what was redacted.
	 */
	private static final String[] ADJECTIVES = {
		"Iron", "Swift", "Grim", "Bold", "Runic", "Ancient", "Silent", "Cursed",
		"Golden", "Frozen", "Shadow", "Wild", "Noble", "Rusty", "Sacred", "Crimson",
		"Molten", "Hollow", "Gilded", "Savage", "Weary", "Restless", "Feral", "Solemn",
		"Vagrant", "Emerald", "Obsidian", "Thorned", "Stormy", "Dusty", "Lucky", "Grizzled",
	};

	private static final String[] NOUNS = {
		"Falcon", "Warden", "Ranger", "Sage", "Reaver", "Scout", "Herald", "Knight",
		"Drake", "Mage", "Archer", "Rogue", "Titan", "Wraith", "Hunter", "Pilgrim",
		"Bandit", "Monk", "Squire", "Corsair", "Ranger", "Smith", "Oracle", "Nomad",
		"Lancer", "Fletcher", "Miner", "Angler", "Brewer", "Cutter", "Tanner", "Digger",
	};

	/** Fixed width, so a column of them does not hint at name lengths. */
	private static final String ASTERISKS = "*****";

	/** Assigned stand-ins, so two accounts are never shown as the same person. */
	private static final Map<Long, String> ASSIGNED = new HashMap<>();

	private NameMasker()
	{
	}

	/**
	 * The name to display for an account.
	 *
	 * @param privacy current setting; {@code null} is treated as
	 *                {@link NamePrivacy#REAL} so a missing config never
	 *                accidentally hides everything
	 */
	static String display(AccountRecord record, NamePrivacy privacy)
	{
		if (record == null)
		{
			return "";
		}
		// LOGIN_ONLY leaves the character name alone - it is public in game.
		if (privacy == null || !privacy.masksDisplayName())
		{
			return record.label();
		}
		if (privacy == NamePrivacy.ASTERISKS)
		{
			return ASTERISKS;
		}
		if (privacy == NamePrivacy.HIDDEN)
		{
			return "Account " + shortId(record.accountHash);
		}
		return standInFor(record.accountHash);
	}

	/** Masks a secondary identity field - the login name or the user's label. */
	static String displayField(String value, long accountHash, NamePrivacy privacy)
	{
		if (privacy == null || !privacy.isMasked())
		{
			return value == null ? "" : value;
		}
		// An empty field stays empty; masking a blank would invent an identity
		// that was never there.
		if (value == null || value.isEmpty() || "-".equals(value))
		{
			return value == null ? "" : value;
		}
		if (privacy == NamePrivacy.ASTERISKS)
		{
			return ASTERISKS;
		}
		if (privacy == NamePrivacy.HIDDEN)
		{
			return "-";
		}
		return standInFor(accountHash);
	}

	/**
	 * A stable stand-in for one account.
	 *
	 * <p>Derived from the account hash rather than assigned in list order, so
	 * the same account keeps the same name across restarts, re-sorts and filter
	 * changes.
	 */
	private static synchronized String standInFor(long accountHash)
	{
		String existing = ASSIGNED.get(accountHash);
		if (existing != null)
		{
			return existing;
		}

		// A display label, not a security boundary, so a cheap stable mix is
		// exactly the right tool.
		int h = Long.hashCode(accountHash);
		h = Math.abs(h == Integer.MIN_VALUE ? 0 : h);

		String name = ADJECTIVES[h % ADJECTIVES.length]
			+ " " + NOUNS[(h / ADJECTIVES.length) % NOUNS.length];

		Set<String> taken = new HashSet<>(ASSIGNED.values());
		if (taken.contains(name))
		{
			int suffix = 2;
			while (taken.contains(name + " " + suffix))
			{
				suffix++;
			}
			name = name + " " + suffix;
		}

		ASSIGNED.put(accountHash, name);
		return name;
	}

	/** Last four digits of the hash - enough to tell accounts apart. */
	private static String shortId(long accountHash)
	{
		String key = Long.toString(Math.abs(accountHash));
		return key.length() <= 4 ? key : key.substring(key.length() - 4);
	}
}

