	// ------------------------------------------------------------------
	// Refresh
	// ------------------------------------------------------------------

	/** How often the stored-data summary is actually recomputed. */
	private static final long SUMMARY_INTERVAL_MILLIS = 30_000L;

	private long summaryRefreshedAt;

	/**
	 * Updates the read-only summaries.
	 *
	 * <p>Called on the Swing thread whenever the viewer reloads, which is every
	 * five seconds while anything is dirty. Recomputing it costs a full scan of
	 * the event log holding the store's lock, plus a directory listing for the
	 * backups - neither of which belongs on a five-second loop for a panel of
	 * static text that is usually not even the visible tab. Throttled instead;
	 * the numbers being half a minute stale costs nothing.
	 */
	void reload()
	{
		long now = System.currentTimeMillis();
		if (summaryRefreshedAt != 0L && now - summaryRefreshedAt < SUMMARY_INTERVAL_MILLIS)
		{
			return;
		}
		summaryRefreshedAt = now;

		StringBuilder sb = new StringBuilder();
		sb.append("Folder: ").append(store.file().getParentFile().getAbsolutePath()).append('\n');
		sb.append("Accounts file: ").append(describeFile(store.file())).append('\n');
		sb.append("History file: ").append(describeFile(historyStore.file()))
			.append("  (").append(historyStore.totalSnapshotCount()).append(" snapshots");
		long earliest = historyStore.earliestSnapshotAt();
		if (earliest > 0L)
		{
			sb.append(", oldest ").append(LoginAge.exact(earliest));
		}
		sb.append(")\n");
		sb.append("GE event log: ").append(describeFile(geEventStore.file()))
			.append("  (").append(geEventStore.eventCount()).append(" events");
		long firstEvent = geEventStore.earliestEventAt();
		if (firstEvent > 0L)
		{
			sb.append(", oldest ").append(LoginAge.exact(firstEvent));
		}
		sb.append(")\n");

		List<File> backups = plugin.backups().listBackups();
		if (backups.isEmpty())
		{
			sb.append("Backups: none yet");
		}
		else
		{
			sb.append("Backups: ").append(backups.size())
				.append(", most recent ").append(backups.get(0).getName());
		}

		dataSummary.setText(sb.toString());
	}

	private static String describeFile(File file)
	{
		if (file == null || !file.exists())
		{
			return "not written yet";
		}
		double kb = file.length() / 1024.0;
		if (kb >= 1024.0)
		{
			return String.format(Locale.ROOT, "%.1f MB", kb / 1024.0);
		}
		return String.format(Locale.ROOT, "%.0f KB", kb);
	}

	/**
	 * Backs up without holding the Swing thread - see
	 * {@link AccountAlmanacPlugin#backupInBackground}. The button stays
	 * disabled until the result is back, so a second click cannot queue another
	 * copy behind the first.
	 */
	private void runBackupNow(JButton button)
	{
		String idleText = button.getText();
		button.setEnabled(false);
		button.setText("Backing up...");

		plugin.backupInBackground((written, error) ->
		{
			button.setText(idleText);
			button.setEnabled(true);
			if (error != null)
			{
				JOptionPane.showMessageDialog(this,
					"The backup failed: " + error.getMessage(),
					"Backup", JOptionPane.ERROR_MESSAGE);
			}
			else if (written == null)
			{
				JOptionPane.showMessageDialog(this,
					"Nothing to back up yet - no data files have been written.",
					"Backup", JOptionPane.INFORMATION_MESSAGE);
			}
			else
			{
				JOptionPane.showMessageDialog(this,
					"Backup written to:\n" + written.getAbsolutePath(),
					"Backup", JOptionPane.INFORMATION_MESSAGE);
			}
			reload();
		});
	}

	// ------------------------------------------------------------------
	// Control builders
	// ------------------------------------------------------------------

	private JComboBox<NumberFormatMode> formatBox(String key, NumberFormatMode current)
	{
		JComboBox<NumberFormatMode> box = new JComboBox<>(NumberFormatMode.values());
		box.setSelectedItem(current);
		box.addActionListener(e ->
		{
			if (!populating)
			{
				write(key, box.getSelectedItem());
			}
		});
		return box;
	}

	private JSpinner daySpinner(String key, int current, int min, int max)
	{
		return spinner(key, current, min, max, " days");
	}

	private JSpinner spinner(String key, int current, int min, int max, String suffix)
	{
		JSpinner spinner = new JSpinner(new SpinnerNumberModel(
			Math.max(min, Math.min(max, current)), min, max, 1));
		spinner.setPreferredSize(new Dimension(90, spinner.getPreferredSize().height));
		spinner.addChangeListener(e ->
		{
			if (!populating)
			{
				write(key, spinner.getValue());
			}
		});
		if (!suffix.isEmpty())
		{
			spinner.setToolTipText("Measured in" + suffix);
		}
		return spinner;
	}

	/**
	 * A button showing the current colour, opening a chooser on click. Painted
	 * as its own background rather than using a swatch icon so it stays legible
	 * at any look-and-feel.
	 */
	private JButton colourButton(String key, Color current)
	{
		JButton button = new JButton("          ");
		button.setBackground(current);
		button.setOpaque(true);
		button.setBorderPainted(true);
		button.setToolTipText("Click to change");
		button.addActionListener(e ->
		{
			Color chosen = JColorChooser.showDialog(this, "Choose colour", button.getBackground());
			if (chosen != null)
			{
				button.setBackground(chosen);
				write(key, chosen);
			}
		});
		return button;
	}

	/**
	 * Writes one setting. Going through {@code ConfigManager} rather than
	 * holding state here is what makes it persist and what makes the plugin's
	 * own {@code onConfigChanged} fire, which repaints everything already
	 * showing.
	 */
	private void write(String key, Object value)
	{
		configManager.setConfiguration(AccountAlmanacConfig.GROUP, key, value);
		if (onChanged != null)
		{
			onChanged.run();
		}
	}

	// ------------------------------------------------------------------
	// Layout helpers
	// ------------------------------------------------------------------

	private static JPanel grid()
	{
		JPanel panel = new JPanel(new GridBagLayout());
		panel.setOpaque(false);
		return panel;
	}

	private static void addRow(JPanel grid, int row, String label,
		java.awt.Component control, String hint)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.insets = new Insets(3, 0, 3, 8);
		c.gridy = row;
		c.anchor = GridBagConstraints.WEST;

		c.gridx = 0;
		JLabel name = new JLabel(label);
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		name.setPreferredSize(new Dimension(150, name.getPreferredSize().height));
		grid.add(name, c);

		c.gridx = 1;
		grid.add(control, c);

		if (!hint.isEmpty())
		{
			c.gridx = 2;
			c.weightx = 1.0;
			JLabel hintLabel = new JLabel(hint);
			hintLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			hintLabel.setFont(FontManager.getRunescapeSmallFont());
			grid.add(hintLabel, c);
		}
	}

	private static JPanel section(String title, String description, java.awt.Component body)
	{
		JPanel panel = new JPanel(new BorderLayout(0, 6));
		panel.setOpaque(false);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(0, 0, 10, 0)));
		panel.setAlignmentX(LEFT_ALIGNMENT);

		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setOpaque(false);

		JLabel titleLabel = new JLabel(title);
		titleLabel.setForeground(ColorScheme.BRAND_ORANGE);
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setAlignmentX(LEFT_ALIGNMENT);
		header.add(titleLabel);

		if (!description.isEmpty())
		{
			JLabel descriptionLabel = new JLabel("<html><body style='width:640px'>"
				+ AlmanacSidebarPanel.escape(description) + "</body></html>");
			descriptionLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			descriptionLabel.setFont(FontManager.getRunescapeSmallFont());
			descriptionLabel.setAlignmentX(LEFT_ALIGNMENT);
			header.add(descriptionLabel);
		}

		panel.add(header, BorderLayout.NORTH);
		panel.add(body, BorderLayout.CENTER);
		return panel;
	}
}

package com.accountalmanac;

/**
 * One Grand Exchange slot as of the last time the client reported it.
 *
 * <p>The client fires {@code GrandExchangeOfferChanged} for all eight slots
 * shortly after login, so simply recording every event gives a complete
 * picture of an account's GE state without needing the GE interface opened.
 * That is unlike bank contents, which are only readable while the bank is
 * actually open.
 *
 * <p>{@code state} is the {@code GrandExchangeOfferState} enum name rather
 * than the enum itself so that an unrecognised future state deserialises
 * cleanly instead of throwing.
 */
class GrandExchangeRecord
{
	/** GE slot index, 0-7. */
	int slot;
	int itemId;
	String itemName = "";
	/** GrandExchangeOfferState.name(), e.g. "BUYING", "SOLD", "EMPTY". */
	String state = "EMPTY";
	/** The price per item this offer was listed at - what you asked for, not what it is worth. */
	int pricePerItem;

	/**
	 * Market price per item at the time this offer was last seen or repriced.
	 *
	 * <p>Kept separate from {@link #pricePerItem} because the two answer
	 * different questions, and conflating them badly distorts wealth. A hail
	 * mary listing of 999,000 on an ornament kit worth 3,953 overstated one
	 * account by 1.3 billion; a lowball listing understates just as hard in the
	 * other direction. What you asked for is not what you have.
	 *
	 * <p>0 means never priced - see {@link #sellStockValue()}.
	 */
	int marketPrice;
	int totalQuantity;
	int quantitySold;
	/** Coins already spent (buy) or received (sell) on this offer. */
	long spent;
	long updatedAt;

	boolean isActive()
	{
		return !"EMPTY".equals(state);
	}

	/** True for the buy-side states, including cancelled and completed ones. */
	boolean isBuy()
	{
		return "BUYING".equals(state) || "BOUGHT".equals(state) || "CANCELLED_BUY".equals(state);
	}

	boolean isSell()
	{
		return "SELLING".equals(state) || "SOLD".equals(state) || "CANCELLED_SELL".equals(state);
	}

	/** "Buy" / "Sell" / "" - the column the table groups on. */
	String typeLabel()
	{
		if (isBuy())
		{
			return "Buy";
		}
		if (isSell())
		{
			return "Sell";
		}
		return "";
	}

	/** Human-readable status rather than the raw enum name. */
	String stateLabel()
	{
		switch (state)
		{
			case "BUYING":
				return "Buying";
			case "BOUGHT":
				return "Bought";
			case "SELLING":
				return "Selling";
			case "SOLD":
				return "Sold";
			case "CANCELLED_BUY":
				return "Cancelled buy";
			case "CANCELLED_SELL":
				return "Cancelled sell";
			case "EMPTY":
				return "Empty";
			default:
				return state;
		}
	}

	/** Filled fraction of the offer, 0.0-1.0. */
	double progress()
	{
		if (totalQuantity <= 0)
		{
			return 0.0;
		}
		return Math.min(1.0, (double) quantitySold / (double) totalQuantity);
	}

	int remainingQuantity()
	{
		return Math.max(0, totalQuantity - quantitySold);
	}

	/**
	 * What this offer is currently worth to the account. Returns 0 for an empty
	 * slot.
	 *
	 * <p>The two sides are valued differently on purpose:
	 *
	 * <ul>
	 * <li>A <b>buy</b> offer really has escrowed {@code remaining x listed
	 * price} in coins. That gp is unspendable until the offer fills or is
	 * cancelled, but it is genuinely yours and genuinely that amount, so the
	 * listed price is the correct figure.</li>
	 * <li>A <b>sell</b> offer holds items, not coins. Nobody has agreed to pay
	 * your asking price, so valuing the stock at it is wishful thinking. It is
	 * worth what the same item in your bank is worth - the market price.</li>
	 * </ul>
	 */
	long committedValue()
	{
		if (!isActive())
		{
			return 0L;
		}
		if (isSell())
		{
			return sellStockValue();
		}
		return (long) remainingQuantity() * pricePerItem;
	}

	/**
	 * Market value of the unsold stock sitting in this sell offer.
	 *
	 * <p>Returns 0 rather than falling back to the listed price when the market
	 * price is unknown. Falling back would reintroduce exactly the distortion
	 * this field exists to remove, and understating briefly is recoverable -
	 * any login or a "Refresh prices" fills it in - whereas a bogus billion in
	 * the totals is not obviously wrong until someone goes looking.
	 */
	/**
	 * How far the listed price sits from the market price, as a fraction.
	 *
	 * <p>Positive means listed above market, negative below. Returns null when
	 * the market price has never been captured, which is a different thing
	 * from a nil difference and must not be drawn as one.
	 */
	Double priceVsMarket()
	{
		if (marketPrice <= 0 || pricePerItem <= 0)
		{
			return null;
		}
		return (pricePerItem - (double) marketPrice) / marketPrice;
	}

	/**
	 * Whether the gap favours the account holding this offer.
	 *
	 * <p>The same gap means opposite things on the two sides of the book:
	 * listing a buy below market is a bargain, while listing a sell below it
	 * is undercutting. Judged here rather than at the drawing site so both the
	 * table and the export agree.
	 */
	boolean priceGapFavourable()
	{
		Double gap = priceVsMarket();
		if (gap == null)
		{
			return false;
		}
		return isBuy() ? gap <= 0 : gap >= 0;
	}

	long sellStockValue()
	{
		if (marketPrice <= 0)
		{
			return 0L;
		}
		return (long) remainingQuantity() * marketPrice;
	}

	/** True when the market price for this offer's item has not been captured yet. */
	boolean needsMarketPrice()
	{
		return isActive() && itemId > 0 && marketPrice <= 0;
	}
}

package com.accountalmanac;

import java.awt.Color;
import net.runelite.client.ui.ColorScheme;

/**
 * Maps a login age onto the user's configured colours.
 *
 * <p>Kept in one place so the sidebar, the accounts table and the reminder
 * list cannot drift apart on where the boundaries sit. The thresholds
 * themselves are settings, defaulting to the requested green under 7 days,
 * yellow from 7, red from 12.
 */
final class LoginAgeColours
{
	private LoginAgeColours()
	{
	}

	static Color forTimestamp(long epochMillis, long now, AccountAlmanacConfig config)
	{
		return forStatus(LoginAge.statusOf(epochMillis, now,
			config.warnAfterDays(), config.staleAfterDays()), config);
	}

	static Color forStatus(LoginAge.Status status, AccountAlmanacConfig config)
	{
		switch (status)
		{
			case FRESH:
				return config.freshLoginColour();
			case WARNING:
				return config.warningLoginColour();
			case STALE:
				return config.staleLoginColour();
			case NEVER:
			default:
				// Never logged in is not a staleness problem, it is an absence
				// of data - colouring it red would read as an alarm.
				return ColorScheme.LIGHT_GRAY_COLOR;
		}
	}
}

package com.accountalmanac;

/**
 * A single thing that happened to a Grand Exchange slot.
 *
 * <p>These are derived from transitions between {@code GrandExchangeOfferState}
 * values rather than reported directly - the client tells you what a slot
 * <em>is</em>, never what just <em>changed</em>, so the tracker keeps the
 * previous state per slot and diffs it. See {@link GeEventTracker}.
 */
enum GeEventType
{
	BUY_STARTED("Started buy offer", false),
	BUY_COMPLETED("Finished buy offer", false),
	BUY_CANCELLED("Cancelled buy offer", false),

	SELL_STARTED("Started sell offer", true),
	SELL_COMPLETED("Finished sell offer", true),
	SELL_CANCELLED("Cancelled sell offer", true),

	/**
	 * Items taken out of the collection box. Applies to both sides: a buy
	 * yields the items bought, a cancelled sell returns the unsold stock.
	 */
	COLLECTED_ITEMS("Collected items", false),

	/**
	 * Coins taken out of the collection box. A completed sell yields the sale
	 * proceeds; a buy can also yield coins back, either because it filled
	 * below the price offered or because it was cancelled with escrow left.
	 */
	COLLECTED_COINS("Collected coins", false);

	private final String label;
	private final boolean sellSide;

	GeEventType(String label, boolean sellSide)
	{
		this.label = label;
		this.sellSide = sellSide;
	}

	String label()
	{
		return label;
	}

	@Override
	public String toString()
	{
		return label;
	}

	boolean isSellSide()
	{
		return sellSide;
	}

	/**
	 * True for anything that moved goods or coins, completed or cancelled.
	 * A partially-filled offer that was then cancelled still bought or sold
	 * something, so it belongs in purchase/sale history too.
	 */
	boolean isTradeOutcome()
	{
		return this == BUY_COMPLETED || this == SELL_COMPLETED
			|| this == BUY_CANCELLED || this == SELL_CANCELLED;
	}

	/** Parses a stored name, returning {@code null} for an unknown value. */
	static GeEventType fromName(String name)
	{
		if (name == null)
		{
			return null;
		}
		for (GeEventType type : values())
		{
			if (type.name().equals(name))
			{
				return type;
			}
		}
		return null;
	}
}

package com.accountalmanac;

import java.text.NumberFormat;
import java.time.Duration;
import java.time.Instant;
import java.util.Locale;

/**
 * Number and time formatting, driven by the user's display settings.
 *
 * <p>The chosen modes are held in static fields rather than being threaded
 * through every panel as a parameter. That is a deliberate trade: the
 * alternative was passing a formatter into {@code PieChartPanel},
 * {@code AccountRowPanel}, {@code StatsGridPanel}, every table model and every
 * cell renderer, which is a wide refactor of working display code in service of
 * a settings feature. The fields are {@code volatile} and only ever written by
 * {@link #applyConfig}, which runs on plugin start and whenever config changes;
 * everything else reads them from the Swing thread.
 */
final class Format
{
	private static volatile NumberFormatMode wealthMode = NumberFormatMode.ABBREVIATED;
	private static volatile NumberFormatMode changeMode = NumberFormatMode.ABBREVIATED;
	private static volatile NumberFormatMode xpMode = NumberFormatMode.FULL_WITH_COMMAS;
	private static volatile NumberFormatMode quantityMode = NumberFormatMode.ABBREVIATED;

	private Format()
	{
	}

	/**
	 * Adopts the user's formatting preferences. Called on start-up and on every
	 * config change, so the tables re-render in the newly chosen style without
	 * a client restart.
	 */
	static void applyConfig(AccountAlmanacConfig config)
	{
		if (config == null)
		{
			return;
		}
		wealthMode = orDefault(config.wealthFormat(), NumberFormatMode.ABBREVIATED);
		changeMode = orDefault(config.gpChangeFormat(), NumberFormatMode.ABBREVIATED);
		xpMode = orDefault(config.statGainFormat(), NumberFormatMode.FULL_WITH_COMMAS);
		quantityMode = orDefault(config.quantityFormat(), NumberFormatMode.ABBREVIATED);
	}

	private static NumberFormatMode orDefault(NumberFormatMode mode, NumberFormatMode fallback)
	{
		return mode == null ? fallback : mode;
	}

	/** Coin amount in the user's wealth style, e.g. {@code "1.4M gp"}. */
	static String gp(long gp)
	{
		return wealthMode.format(gp) + " gp";
	}

	/** Coin amount with no unit suffix, for columns headed "gp" already. */
	static String gpBare(long gp)
	{
		return wealthMode.format(gp);
	}

	/**
	 * A signed change, e.g. {@code "+1.4M"} / {@code "-320.5K"}. Zero is
	 * rendered without a sign, since "+0" reads as a gain that did not happen.
	 */
	static String gpChange(long delta)
	{
		if (delta == 0L)
		{
			return "0";
		}
		String magnitude = changeMode.format(Math.abs(delta));
		return (delta > 0L ? "+" : "-") + magnitude;
	}

	/** A signed experience change, e.g. {@code "+1,204,551"}. */
	static String xpChange(long delta)
	{
		if (delta == 0L)
		{
			return "0";
		}
		String magnitude = xpMode.format(Math.abs(delta));
		return (delta > 0L ? "+" : "-") + magnitude;
	}

	/** Bare count in the user's quantity style, e.g. {@code "1.4M"}. */
	static String quantity(long amount)
	{
		return quantityMode.format(amount);
	}

	/**
	 * Full grouped number regardless of settings, e.g. {@code "1,438,204"}.
	 * Used for tooltips, where the whole point is to show what an abbreviated
	 * cell is hiding.
	 */
	static String exact(long amount)
	{
		return NumberFormat.getIntegerInstance(Locale.ROOT).format(amount);
	}

	/** Signed full grouped number, for tooltips on change cells. */
	static String exactChange(long delta)
	{
		if (delta == 0L)
		{
			return "0";
		}
		return (delta > 0L ? "+" : "-") + exact(Math.abs(delta));
	}

	static String relativeTime(long epochMillis)
	{
		if (epochMillis <= 0)
		{
			return "never updated";
		}
		Duration d = Duration.between(Instant.ofEpochMilli(epochMillis), Instant.now());
		long minutes = d.toMinutes();
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		long hours = d.toHours();
		if (hours < 24)
		{
			return hours + "h ago";
		}
		return d.toDays() + "d ago";
	}
}

package com.accountalmanac;

import java.io.BufferedWriter;
import java.io.Closeable;
import java.io.File;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;

/**
 * Streams rows to a CSV file.
 *
 * <p>Written a row at a time straight through a buffered writer. Building the
 * whole file in memory first would mean holding a second copy of a bank
 * export - twelve thousand rows across forty accounts - for no gain, since
 * nothing needs to see the text before it lands on disk.
 *
 * <p>Quoting follows RFC 4180: a field is quoted only when it has to be, and
 * embedded quotes are doubled. Values are written raw - unformatted numbers,
 * epoch millis for times - because the point of a CSV is to be computed on. A
 * spreadsheet can format 1200000 however the reader likes; it cannot get the
 * number back out of "1.2M".
 */
final class Csv implements Closeable
{
	private final Writer out;
	/** Reused across rows; a per-row builder would allocate one per line. */
	private final StringBuilder line = new StringBuilder(256);

	private Csv(Writer out)
	{
		this.out = out;
	}

	/**
	 * Opens a file and writes the header row.
	 *
	 * <p>UTF-8 without a byte order mark. A BOM would make Excel guess the
	 * encoding correctly on a double-click, but it also shows up as stray
	 * characters in every parser that does not expect one, and these files are
	 * meant to be read by tools as much as by people.
	 */
	static Csv open(File file, String... headers) throws IOException
	{
		Writer w = new BufferedWriter(new OutputStreamWriter(
			Files.newOutputStream(file.toPath()), StandardCharsets.UTF_8), 1 << 16);
		Csv csv = new Csv(w);
		csv.row((Object[]) headers);
		return csv;
	}

	/** Writes one row. Nulls become empty fields. */
	void row(Object... cells) throws IOException
	{
		line.setLength(0);
		for (int i = 0; i < cells.length; i++)
		{
			if (i > 0)
			{
				line.append(',');
			}
			append(cells[i]);
		}
		// \r\n is what RFC 4180 specifies, and it is what Excel expects on
		// Windows regardless of what the file is opened with elsewhere.
		line.append('\r').append('\n');
		out.write(line.toString());
	}

	private void append(Object cell)
	{
		if (cell == null)
		{
			return;
		}
		// Numbers and booleans can never need quoting or escaping, and they are
		// the bulk of every export, so they skip the scan entirely.
		if (cell instanceof Number || cell instanceof Boolean)
		{
			line.append(cell);
			return;
		}

		String text = cell.toString();
		if (text.isEmpty())
		{
			return;
		}

		boolean quote = needsQuoting(text);
		if (!quote)
		{
			line.append(text);
			return;
		}

		line.append('"');
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (c == '"')
			{
				line.append('"');
			}
			line.append(c);
		}
		line.append('"');
	}

	/**
	 * Whether a field has to be quoted: it contains the separator, a quote, or
	 * a line break.
	 *
	 * <p>Deliberately nothing more. Quoting a field that begins with {@code =}
	 * is sometimes offered as protection against a spreadsheet evaluating it
	 * as a formula, but it is not: Excel drops the quotes on import and
	 * evaluates it anyway. The only things that work are mangling the value or
	 * refusing to write it, and neither belongs in an export of the user's own
	 * data that the same user is about to open.
	 */
	private static boolean needsQuoting(String text)
	{
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (c == ',' || c == '"' || c == '\n' || c == '\r')
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public void close() throws IOException
	{
		out.close();
	}
}

package com.accountalmanac;

import java.awt.Component;
import java.awt.Container;
import javax.swing.AbstractButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JSplitPane;
import javax.swing.JTextField;
import javax.swing.text.JTextComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTabbedPane;
import javax.swing.JTable;
import javax.swing.JTextArea;
import javax.swing.JViewport;
import javax.swing.table.JTableHeader;

/**
 * Paints a {@link ViewerTheme} onto an existing Swing component tree.
 *
 * <p>Done by walking the tree rather than through {@code UIManager}, because
 * {@code UIManager} defaults are global to the JVM: changing them would repaint
 * RuneLite's own windows and every other plugin's panel along with this one.
 * Walking a specific component keeps the change contained to this plugin's own
 * sidebar panel and viewer window, and leaves the rest of the client alone.
 *
 * <p>Two things are deliberately skipped:
 *
 * <ul>
 * <li>Anything whose colour carries meaning - a gain in green, a stale login in
 * red, an item stack above the game's own colour threshold. Those are set by
 * their renderers on every paint, so they survive this untouched, which is what
 * should happen: they encode information, not decoration.</li>
 * <li>{@link StatsGridPanel}, which is a deliberate replica of the in-game
 * stats interface. That panel is brown in the game whatever else is on screen,
 * and recolouring it would make it a worse replica, not a better-themed one.</li>
 * </ul>
 */
final class ThemeApplier
{
	private ThemeApplier()
	{
	}

	static void apply(Component root, ViewerTheme theme)
	{
		if (root == null || theme == null)
		{
			return;
		}
		paint(root, theme);
	}

	private static void paint(Component component, ViewerTheme theme)
	{
		// The in-game stats replica keeps its own palette, and so does anything
		// inside it.
		if (component instanceof StatsGridPanel)
		{
			return;
		}

		if (component instanceof JTable)
		{
			JTable table = (JTable) component;
			table.setBackground(theme.background());
			table.setForeground(theme.text());
			table.setGridColor(theme.grid());
			table.setSelectionBackground(theme.selection());
			table.setSelectionForeground(theme.text());

			JTableHeader header = table.getTableHeader();
			if (header != null)
			{
				header.setBackground(theme.altBackground());
				header.setForeground(theme.dimText());
			}
		}
		else if (component instanceof JTextArea)
		{
			JTextArea area = (JTextArea) component;
			area.setBackground(theme.altBackground());
			area.setForeground(theme.dimText());
		}
		else if (component instanceof JLabel)
		{
			// Only labels still on a theme colour are repainted. One that has
			// been given a meaningful colour - a login age, a reminder count -
			// is left as it is.
			JLabel label = (JLabel) component;
			if (isThemeColour(label))
			{
				label.setForeground(theme.text());
			}
		}
		else if (component instanceof JComboBox)
		{
			// Dropdowns kept RuneLite's dark default, which on a light theme is
			// a dark control on a pale panel - the reason the light themes
			// looked broken. The popup list takes the same colours, since it is
			// a separate component that inherits nothing from the box.
			JComboBox<?> box = (JComboBox<?>) component;
			box.setBackground(theme.altBackground());
			box.setForeground(theme.text());
			paintComboPopup(box, theme);
		}
		else if (component instanceof JTextComponent)
		{
			// Covers the search and filter fields as well as text areas.
			JTextComponent text = (JTextComponent) component;
			text.setBackground(theme.altBackground());
			text.setForeground(theme.text());
			text.setCaretColor(theme.text());
			if (text instanceof JTextField)
			{
				text.setSelectionColor(theme.selection());
				text.setSelectedTextColor(theme.text());
			}
		}
		else if (component instanceof AbstractButton)
		{
			// Buttons, checkboxes and radio buttons. A checkbox sits directly on
			// the panel, so it takes the panel colour rather than the secondary
			// surface a raised button wants.
			AbstractButton button = (AbstractButton) component;
			boolean flat = !(button instanceof javax.swing.JButton);
			button.setBackground(flat ? theme.background() : theme.altBackground());
			button.setForeground(theme.text());
		}
		else if (component instanceof JSplitPane)
		{
			component.setBackground(theme.background());
		}
		else if (component instanceof JScrollPane)
		{
			JScrollPane scroll = (JScrollPane) component;
			scroll.setBackground(theme.background());
			JViewport viewport = scroll.getViewport();
			if (viewport != null)
			{
				viewport.setBackground(theme.background());
			}
		}
		else if (component instanceof JTabbedPane || component instanceof JPanel)
		{
			component.setBackground(theme.background());
			component.setForeground(theme.text());
		}

		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				paint(child, theme);
			}
		}
	}

	/**
	 * Colours a combo box's drop-down list.
	 *
	 * <p>The popup is a separate component that is not in the tree being
	 * walked, so it never gets reached by recursion and has to be asked for
	 * directly. Without this the list stays dark on the light themes even once
	 * the box itself is correct.
	 */
	private static void paintComboPopup(JComboBox<?> box, ViewerTheme theme)
	{
		if (box.getUI() == null)
		{
			return;
		}
		javax.accessibility.Accessible child = box.getUI().getAccessibleChild(box, 0);
		if (child instanceof Component)
		{
			findList((Component) child, theme);
		}
	}

	private static void findList(Component component, ViewerTheme theme)
	{
		if (component instanceof JList)
		{
			JList<?> list = (JList<?>) component;
			list.setBackground(theme.altBackground());
			list.setForeground(theme.text());
			list.setSelectionBackground(theme.selection());
			list.setSelectionForeground(theme.text());
			return;
		}
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				findList(child, theme);
			}
		}
	}

	/**
	 * Whether a label is still wearing a theme colour rather than a meaningful
	 * one. Checked against every theme's palette, not just the active one, so
	 * switching themes repeatedly does not gradually freeze labels at whatever
	 * colour the previous theme left them.
	 */
	private static boolean isThemeColour(JLabel label)
	{
		java.awt.Color current = label.getForeground();
		if (current == null)
		{
			return true;
		}
		for (ViewerTheme candidate : ViewerTheme.values())
		{
			if (current.equals(candidate.text())
				|| current.equals(candidate.dimText())
				|| current.equals(candidate.accent()))
			{
				return true;
			}
		}
		return false;
	}
}

package com.accountalmanac;

/**
 * One logged Grand Exchange event, as written to {@code ge-events.json}.
 *
 * <p>{@link #type} is the {@link GeEventType} name rather than the enum, for
 * the same reason {@link GrandExchangeRecord#state} is - an unrecognised value
 * from a newer version deserialises cleanly instead of throwing and taking the
 * whole log with it.
 */
class GeEvent
{
	/** Local PC time the event was recorded, epoch millis. */
	long at;

	long accountHash;

	/** Account label at the time, so the log stays readable if a name changes. */
	String accountLabel = "";

	/** {@link GeEventType} name. */
	String type = "";

	/** GE slot index 0-7, or -1 when not slot-specific. */
	int slot = -1;

	int itemId;
	String itemName = "";

	/**
	 * Quantity this event concerns: the offer size for a start, the filled
	 * amount for a completion or cancellation, the collected amount for a
	 * collection.
	 */
	int quantity;

	/** The per-item price the offer was listed at. */
	int pricePerItem;

	/**
	 * Coins actually moved by this event: spent for a buy, received for a
	 * sell, collected for a collection. For a start event this is the value
	 * committed to the offer.
	 */
	long totalValue;

	/**
	 * Set when the event was inferred at login rather than witnessed live -
	 * the offer changed while the account was logged out, so the timestamp is
	 * when it was noticed, not when it happened.
	 *
	 * <p>Kept explicit rather than silently pretending the login time is the
	 * trade time, because purchase history is the one place where a wrong
	 * timestamp quietly corrupts the user's own record of what they paid.
	 */
	boolean approximate;

	GeEvent()
	{
	}

	GeEvent(long at, long accountHash, String accountLabel, GeEventType type)
	{
		this.at = at;
		this.accountHash = accountHash;
		this.accountLabel = accountLabel == null ? "" : accountLabel;
		this.type = type.name();
	}

	GeEventType typeOrNull()
	{
		return GeEventType.fromName(type);
	}

	String typeLabel()
	{
		GeEventType parsed = typeOrNull();
		return parsed == null ? type : parsed.label();
	}

	/**
	 * Coins per item actually transacted, which is not always
	 * {@link #pricePerItem}: a buy offer fills at or below the price you
	 * listed, so what you actually paid per item is the total divided by the
	 * count. Falls back to the listed price when nothing was filled.
	 */
	long actualUnitPrice()
	{
		if (quantity <= 0)
		{
			return pricePerItem;
		}
		return totalValue / quantity;
	}

	void normalise()
	{
		if (type == null)
		{
			type = "";
		}
		if (itemName == null)
		{
			itemName = "";
		}
		if (accountLabel == null)
		{
			accountLabel = "";
		}
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.TimeUnit;

/**
 * One account's snapshots over time, oldest first.
 *
 * <p>Snapshots are appended at a throttled cadence rather than on every
 * change, and older ones are thinned as they age. Without thinning, a year of
 * daily snapshots across forty accounts would be roughly fifteen thousand
 * records each carrying a skill map, which is a lot of JSON to rewrite every
 * time one account gains experience.
 */
class AccountHistory
{
	/** Retain every snapshot newer than this at full daily resolution. */
	private static final long FULL_DETAIL_DAYS = 30L;

	/** Between full detail and this age, thin to roughly one per week. */
	private static final long WEEKLY_DETAIL_DAYS = 180L;

	private static final long ONE_DAY_MILLIS = TimeUnit.DAYS.toMillis(1);
	private static final long ONE_WEEK_MILLIS = TimeUnit.DAYS.toMillis(7);
	private static final long ONE_MONTH_MILLIS = TimeUnit.DAYS.toMillis(30);

	long accountHash;

	List<HistorySnapshot> snapshots = new ArrayList<>();

	AccountHistory()
	{
	}

	AccountHistory(long accountHash)
	{
		this.accountHash = accountHash;
	}

	void normalise()
	{
		if (snapshots == null)
		{
			snapshots = new ArrayList<>();
			return;
		}
		for (HistorySnapshot snapshot : snapshots)
		{
			snapshot.normalise();
		}
		snapshots.sort(Comparator.comparingLong(s -> s.at));
	}

	HistorySnapshot latest()
	{
		return snapshots.isEmpty() ? null : snapshots.get(snapshots.size() - 1);
	}

	HistorySnapshot earliest()
	{
		return snapshots.isEmpty() ? null : snapshots.get(0);
	}

	boolean isEmpty()
	{
		return snapshots.isEmpty();
	}

	/**
	 * The most recent snapshot taken at or before {@code cutoff} - the baseline
	 * a timeframe comparison subtracts from the present.
	 *
	 * <p>Returns {@code null} when history does not reach back that far, which
	 * callers must surface rather than silently substituting the oldest
	 * snapshot: reporting a year of gains from a week of data would be wrong,
	 * and quietly so. {@link #baselineFor} is the forgiving variant, for
	 * callers that explicitly want "as far back as we go".
	 */
	HistorySnapshot atOrBefore(long cutoff)
	{
		HistorySnapshot best = null;
		for (HistorySnapshot snapshot : snapshots)
		{
			if (snapshot.at <= cutoff)
			{
				best = snapshot;
			}
			else
			{
				// Sorted ascending, so nothing further can qualify.
				break;
			}
		}
		return best;
	}

	/**
	 * Baseline for a timeframe. For {@link Timeframe#ALL_TIME} this is the
	 * earliest snapshot; otherwise the newest one at or before the cutoff, or
	 * {@code null} if history is too short to cover the window.
	 */
	HistorySnapshot baselineFor(Timeframe timeframe, long now)
	{
		if (timeframe.isAllTime())
		{
			return earliest();
		}
		return atOrBefore(timeframe.cutoffFrom(now));
	}

	/**
	 * Appends a snapshot if enough time has passed since the last one.
	 *
	 * <p>The most recent snapshot is <em>replaced</em> rather than kept when
	 * inside the interval, so the newest figures are always current while the
	 * record count stays bounded. The very first snapshot for an account is
	 * always accepted, since it is the baseline everything else measures from.
	 *
	 * @param minIntervalMillis smallest gap between retained snapshots
	 * @return {@code true} if the stored history actually changed
	 */
	boolean record(HistorySnapshot snapshot, long minIntervalMillis)
	{
		if (snapshot == null || snapshot.isEmpty())
		{
			return false;
		}

		// Replaced wholesale rather than mutated, for the same reason the skill
		// maps are: this runs on the executor thread while the Swing thread
		// iterates the list to render the Wealth history tab.
		HistorySnapshot last = latest();
		if (last == null)
		{
			List<HistorySnapshot> updated = new ArrayList<>(snapshots);
			updated.add(snapshot);
			snapshots = updated;
			return true;
		}

		if (snapshot.at - last.at >= minIntervalMillis)
		{
			List<HistorySnapshot> updated = new ArrayList<>(snapshots);
			updated.add(snapshot);
			snapshots = updated;
			prune(snapshot.at);
			return true;
		}

		// Inside the interval: refresh the tip so "now" is accurate, but only
		// when something actually moved, or an idle account would rewrite the
		// file on every flush.
		if (last.totalWealth() != snapshot.totalWealth()
			|| last.totalXp != snapshot.totalXp
			|| last.totalLevel != snapshot.totalLevel)
		{
			List<HistorySnapshot> updated = new ArrayList<>(snapshots);
			updated.set(updated.size() - 1, snapshot);
			snapshots = updated;
			return true;
		}

		return false;
	}

	/**
	 * Thins older snapshots: daily inside 30 days, weekly out to 180 days,
	 * monthly beyond that. The oldest snapshot is always kept, because it is
	 * the all-time baseline.
	 */
	void prune(long now)
	{
		if (snapshots.size() < 3)
		{
			return;
		}

		List<HistorySnapshot> kept = new ArrayList<>(snapshots.size());
		HistorySnapshot previousKept = null;

		for (int i = 0; i < snapshots.size(); i++)
		{
			HistorySnapshot snapshot = snapshots.get(i);
			boolean isFirst = i == 0;
			boolean isLast = i == snapshots.size() - 1;

			if (isFirst || isLast)
			{
				kept.add(snapshot);
				previousKept = snapshot;
				continue;
			}

			long ageDays = TimeUnit.MILLISECONDS.toDays(Math.max(0L, now - snapshot.at));
			long requiredGap;
			if (ageDays <= FULL_DETAIL_DAYS)
			{
				requiredGap = ONE_DAY_MILLIS;
			}
			else if (ageDays <= WEEKLY_DETAIL_DAYS)
			{
				requiredGap = ONE_WEEK_MILLIS;
			}
			else
			{
				requiredGap = ONE_MONTH_MILLIS;
			}

			if (previousKept == null || snapshot.at - previousKept.at >= requiredGap)
			{
				kept.add(snapshot);
				previousKept = snapshot;
			}
		}

		snapshots = kept;
	}
}

package com.accountalmanac;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/**
 * How dates and times are written out.
 *
 * <p>Always the machine's own local clock, never UTC or a game-server time -
 * "when did I last play this" is a question about your day, not Jagex's.
 *
 * <p>Public because it is a return type on the public
 * {@link AccountAlmanacConfig} interface, which RuneLite implements with a
 * dynamic proxy that cannot reach package-private types.
 */
public enum DateFormatMode
{
	/** {@code 2026-09-10 16:58} - unambiguous, and sorts as text. */
	ISO("2026-09-10 16:58", "yyyy-MM-dd HH:mm"),

	/** {@code SEP-10-2026} - month first. */
	MONTH_FIRST("SEP-10-2026", "MMM-dd-yyyy"),

	/** {@code 10-SEP-2026} - day first. */
	DAY_FIRST("10-SEP-2026", "dd-MMM-yyyy"),

	/** {@code SEP-10-2026 16:58} - month first, with the time. */
	MONTH_FIRST_TIME("SEP-10-2026 16:58", "MMM-dd-yyyy HH:mm"),

	/** {@code Thu 10 Sep 2026, 4:58 PM} - spelled out. */
	FRIENDLY("Thu 10 Sep 2026, 4:58 PM", "EEE d MMM yyyy, h:mm a");

	private final String label;
	private final DateTimeFormatter formatter;

	DateFormatMode(String label, String pattern)
	{
		this.label = label;
		// ROOT so month abbreviations do not change with the system locale -
		// a column that reads SEP on one machine and SET on another is worse
		// than one that is simply always English.
		this.formatter = DateTimeFormatter.ofPattern(pattern, Locale.ROOT);
	}

	@Override
	public String toString()
	{
		return label;
	}

	/** Formats an epoch-millis timestamp, or "never" when it is unset. */
	String format(long epochMillis)
	{
		if (epochMillis <= 0L)
		{
			return "never";
		}
		String text = formatter.format(
			LocalDateTime.ofInstant(Instant.ofEpochMilli(epochMillis), ZoneId.systemDefault()));
		// Uppercase reads better for the abbreviated-month styles and matches
		// how the option is labelled.
		return this == MONTH_FIRST || this == DAY_FIRST || this == MONTH_FIRST_TIME
			? text.toUpperCase(Locale.ROOT)
			: text;
	}
}

package com.accountalmanac;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.IntFunction;
import net.runelite.client.ui.FontManager;

/**
 * Renders stored Grand Exchange offers as an image styled after the in-game
 * Grand Exchange.
 *
 * <p>Drawn from stored offers rather than the live interface, for the same
 * reason the bank export is: the offers worth seeing together belong to
 * accounts that are not logged in, and the game can only show you the eight
 * slots in front of you. This lays every tracked account's slots out at once.
 *
 * <p>The window frame, stone ground and text shadowing are shared with
 * {@link BankScreenshot}, so the two exports are visibly the same interface.
 *
 * <p>Pure drawing - no client access and no IO - so it is safe on the Swing
 * thread. Item sprites arrive through the supplied resolver; a null simply
 * leaves that slot without one.
 */
final class GeScreenshot
{
	/** Which side of the book to draw. */
	enum Side
	{
		ALL("Buys and sells"),
		BUY("Buy offers only"),
		SELL("Sell offers only");

		private final String label;

		Side(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}

		boolean accepts(GrandExchangeRecord offer)
		{
			switch (this)
			{
				case BUY:
					return offer.isBuy();
				case SELL:
					return offer.isSell();
				case ALL:
				default:
					return true;
			}
		}
	}

	/** How the offer boxes are ordered. */
	enum Sort
	{
		PROGRESS_DESC("Closest to done first"),
		PROGRESS_ASC("Furthest from done first"),
		COMMITTED_DESC("Most gp committed first"),
		COMMITTED_ASC("Least gp committed first"),
		UNIT_PRICE_DESC("Highest unit price first"),
		ACCOUNT("Account, A to Z"),
		ITEM("Item name, A to Z");

		private final String label;

		Sort(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}

		Comparator<Entry> comparator()
		{
			Comparator<Entry> byAccount =
				Comparator.comparing(e -> e.account == null ? "" : e.account,
					String.CASE_INSENSITIVE_ORDER);
			switch (this)
			{
				case PROGRESS_ASC:
					return Comparator.comparingDouble((Entry e) -> e.offer.progress())
						.thenComparing(byAccount);
				case COMMITTED_DESC:
					return Comparator.comparingLong((Entry e) -> e.offer.committedValue())
						.reversed().thenComparing(byAccount);
				case COMMITTED_ASC:
					return Comparator.comparingLong((Entry e) -> e.offer.committedValue())
						.thenComparing(byAccount);
				case UNIT_PRICE_DESC:
					return Comparator.comparingLong((Entry e) -> e.offer.pricePerItem)
						.reversed().thenComparing(byAccount);
				case ACCOUNT:
					return byAccount.thenComparing(e -> e.offer.itemName == null ? "" : e.offer.itemName,
						String.CASE_INSENSITIVE_ORDER);
				case ITEM:
					return Comparator.comparing((Entry e) -> e.offer.itemName == null ? "" : e.offer.itemName,
						String.CASE_INSENSITIVE_ORDER).thenComparing(byAccount);
				case PROGRESS_DESC:
				default:
					return Comparator.comparingDouble((Entry e) -> e.offer.progress())
						.reversed().thenComparing(byAccount);
			}
		}
	}

	/** One offer together with the account holding it. */
	static final class Entry
	{
		final String account;
		final GrandExchangeRecord offer;

		Entry(String account, GrandExchangeRecord offer)
		{
			this.account = account;
			this.offer = offer;
		}
	}

	// A slot box, sized so the item, its name and a progress bar fit without
	// the name having to be truncated for anything but the longest items.
	private static final int BOX_W = 172;
	private static final int BOX_H = 92;
	private static final int GAP = 6;
	private static final int COLS = 4;

	private static final int EDGE = 8;
	private static final int PAD = 8;
	private static final int TITLE_H = 22;
	private static final int INFO_H = 16;
	private static final int FOOT_H = 20;

	// The game colours the two sides of the book differently, and the progress
	// bar goes green only once an offer has actually completed.
	private static final Color BUY = new Color(0x6A, 0xA8, 0x4F);
	private static final Color SELL = new Color(0xC0, 0x6C, 0x3E);
	private static final Color BAR_TRACK = new Color(0x22, 0x1D, 0x16);
	private static final Color BAR_DONE = new Color(0x3C, 0xA0, 0x3C);
	private static final Color WHITE = new Color(0xE6, 0xE6, 0xE6);
	// A gap that favours the holder is green; against them, red. Which way
	// round that is depends on the side of the book - see priceGapFavourable.
	private static final Color GOOD = new Color(0x5A, 0xC8, 0x5A);
	private static final Color BAD = new Color(0xD0, 0x50, 0x40);

	private GeScreenshot()
	{
	}

	/**
	 * @param title  heading for the export
	 * @param offers every tracked slot, with the account that holds it
	 * @param side   buys, sells, or both
	 * @param sort   how the boxes are ordered
	 * @param showMarketGap draw how far each listing sits from market price
	 * @param icons  item id to sprite, may return null
	 * @param frame  sprite id to the game's frame piece, may return null
	 */
	static BankScreenshot.Rendered render(String title, List<Entry> offers, Side side,
		Sort sort, boolean showMarketGap,
		IntFunction<Image> icons, IntFunction<BufferedImage> frame)
	{
		List<Entry> shown = new ArrayList<>();
		for (Entry entry : offers)
		{
			// Empty slots are not offers. Including them would pad the picture
			// with blank boxes that say nothing about what is on the market.
			if (entry != null && entry.offer != null && entry.offer.isActive()
				&& side.accepts(entry.offer))
			{
				shown.add(entry);
			}
		}
		shown.sort((sort == null ? Sort.PROGRESS_DESC : sort).comparator());

		int cols = Math.min(COLS, Math.max(1, shown.size()));
		int rows = Math.max(1, (shown.size() + cols - 1) / cols);
		int gridW = cols * BOX_W + (cols - 1) * GAP;
		int gridH = rows * BOX_H + (rows - 1) * GAP;

		int width = EDGE * 2 + PAD * 2 + Math.max(gridW, 320);
		int height = EDGE * 2 + TITLE_H + INFO_H + gridH + FOOT_H + PAD;

		long committed = 0L;
		int buys = 0;
		int sells = 0;
		for (Entry entry : shown)
		{
			committed += entry.offer.committedValue();
			if (entry.offer.isBuy())
			{
				buys++;
			}
			else if (entry.offer.isSell())
			{
				sells++;
			}
		}

		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		List<BankScreenshot.Slot> slots = new ArrayList<>(shown.size());
		Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);

			BankScreenshot.stone(g, width, height);
			BankScreenshot.steelFrame(g, width, height, frame);

			Font rsBold = FontManager.getRunescapeBoldFont();
			Font rsSmall = FontManager.getRunescapeSmallFont();

			String heading = title == null || title.isEmpty() ? "Grand Exchange" : title;
			g.setFont(rsBold);
			int tw = g.getFontMetrics().stringWidth(heading);
			BankScreenshot.shadowed(g, heading, (width - tw) / 2, EDGE + 15,
				BankScreenshot.ORANGE);

			g.setFont(rsSmall);
			String info = shown.size() + (shown.size() == 1 ? " offer" : " offers")
				+ "  -  " + buys + " buying, " + sells + " selling"
				+ "  -  " + Format.exact(committed) + " gp committed";
			int iw = g.getFontMetrics().stringWidth(info);
			BankScreenshot.shadowed(g, info, (width - iw) / 2, EDGE + TITLE_H + 11,
				BankScreenshot.PARCHMENT);

			int gx = EDGE + PAD;
			int gy = EDGE + TITLE_H + INFO_H;

			for (int i = 0; i < shown.size(); i++)
			{
				Entry entry = shown.get(i);
				int bx = gx + (i % cols) * (BOX_W + GAP);
				int by = gy + (i / cols) * (BOX_H + GAP);
				drawSlot(g, bx, by, entry, icons, rsSmall, showMarketGap);
				slots.add(new BankScreenshot.Slot(
					new Rectangle(bx, by, BOX_W, BOX_H), asItem(entry.offer),
					tooltipFor(entry)));
			}

			if (shown.isEmpty())
			{
				g.setFont(rsSmall);
				String none = "No " + (side == Side.ALL ? "" : side.toString().toLowerCase())
					+ " offers are open";
				BankScreenshot.shadowed(g, none, gx, gy + 20, BankScreenshot.PARCHMENT);
			}

			g.setFont(rsSmall);
			BankScreenshot.shadowed(g, side + "  -  "
					+ (sort == null ? Sort.PROGRESS_DESC : sort), gx, gy + gridH + 14,
				BankScreenshot.PARCHMENT);
		}
		finally
		{
			g.dispose();
		}
		return new BankScreenshot.Rendered(image, slots);
	}

	/**
	 * How far a listing sits from the market price, as a percentage.
	 *
	 * <p>Always a percentage, however extreme. A hail-mary listing at 253
	 * times the market reads as +25,171%, and that is the point - the size of
	 * the number is the signal. Grouped so the long ones stay readable.
	 *
	 * <p>Rounded to whole percent: anything finer is noise against a market
	 * price that moves while the offer sits there.
	 */
	static String marketGapLabel(GrandExchangeRecord offer)
	{
		Double gap = offer.priceVsMarket();
		if (gap == null)
		{
			return "";
		}
		long pct = Math.round(gap * 100);
		return (pct > 0 ? "+" : "") + Format.exact(pct) + "%";
	}

	/**
	 * Hover text for an offer box.
	 *
	 * <p>Leads with the account, because that is the thing the picture cannot
	 * show at a glance once a dozen accounts are laid out together.
	 */
	private static String tooltipFor(Entry entry)
	{
		GrandExchangeRecord offer = entry.offer;
		return (entry.account == null || entry.account.isEmpty() ? "Unknown account" : entry.account)
			+ "  -  " + (offer.isBuy() ? "buying " : "selling ") + offer.itemName
			+ "  -  " + Format.exact(offer.quantitySold) + " / " + Format.exact(offer.totalQuantity)
			+ " (" + Math.round(offer.progress() * 100) + "%)"
			+ "  -  " + Format.exact(offer.pricePerItem) + " gp each"
			+ (offer.priceVsMarket() == null ? "  (market price unknown)"
				: "  (" + marketGapLabel(offer) + " vs market "
					+ Format.exact(offer.marketPrice) + " gp)")
			+ "  -  " + Format.gp(offer.committedValue()) + " committed";
	}

	/** One offer box: account, item, progress bar and the price line. */
	private static void drawSlot(Graphics2D g, int x, int y, Entry entry,
		IntFunction<Image> icons, Font rsSmall, boolean showMarketGap)
	{
		GrandExchangeRecord offer = entry.offer;
		Color accent = offer.isBuy() ? BUY : SELL;

		g.setColor(BankScreenshot.WELL);
		g.fillRect(x, y, BOX_W, BOX_H);
		BankScreenshot.bevel(g, x, y, BOX_W, BOX_H, false);

		// A coloured strip along the top is how the side reads at a glance.
		g.setColor(accent);
		g.fillRect(x + 1, y + 1, BOX_W - 2, 3);

		g.setFont(rsSmall);
		BankScreenshot.shadowed(g, offer.isBuy() ? "Buy" : "Sell", x + 5, y + 16, accent);

		String account = entry.account == null ? "" : entry.account;
		int aw = g.getFontMetrics().stringWidth(account);
		BankScreenshot.shadowed(g, account, x + BOX_W - 5 - aw, y + 16,
			BankScreenshot.PARCHMENT);

		Image sprite = icons == null ? null : icons.apply(offer.itemId);
		if (sprite != null)
		{
			g.drawImage(sprite, x + 5, y + 22, null);
		}

		BankScreenshot.shadowed(g, trim(g, offer.itemName, BOX_W - 52),
			x + 44, y + 34, WHITE);

		// Progress across the bottom, filled to what has actually traded.
		int barX = x + 44;
		int barY = y + 42;
		int barW = BOX_W - 49;
		g.setColor(BAR_TRACK);
		g.fillRect(barX, barY, barW, 7);
		double p = offer.progress();
		int fill = (int) Math.round(barW * p);
		if (fill > 0)
		{
			g.setColor(ProgressColours.forFraction(p));
			g.fillRect(barX, barY, fill, 7);
		}
		BankScreenshot.bevel(g, barX, barY, barW, 7, false);

		// Three figures on one line was the bug: unit price, the market badge
		// and the committed value all drew at y+80 and ran into each other on
		// anything wide. Committed moves up to share the quantity line, and
		// each pair is laid out left-and-right with an overlap guard.
		String qty = Format.exact(offer.quantitySold) + " / " + Format.exact(offer.totalQuantity);
		String committed = Format.gp(offer.committedValue());
		pair(g, x, y + 66, qty, BankScreenshot.PARCHMENT, committed, accent);

		String unit = Format.exact(offer.pricePerItem) + " gp ea";
		Double gap = offer.priceVsMarket();
		String badge = showMarketGap && gap != null ? marketGapLabel(offer) : "";
		pair(g, x, y + 80, unit, WHITE, badge,
			offer.priceGapFavourable() ? GOOD : BAD);
	}

	/**
	 * Draws one line with text at each end.
	 *
	 * <p>When the two would collide the right-hand figure is dropped rather
	 * than overlapped: a number sitting on top of another number is worse than
	 * a number that is not there, and the hover text still carries it.
	 */
	private static void pair(Graphics2D g, int x, int y,
		String left, Color leftColour, String right, Color rightColour)
	{
		BankScreenshot.shadowed(g, left, x + 5, y, leftColour);
		if (right == null || right.isEmpty())
		{
			return;
		}
		int lw = g.getFontMetrics().stringWidth(left);
		int rw = g.getFontMetrics().stringWidth(right);
		int rx = x + BOX_W - 5 - rw;
		if (rx < x + 5 + lw + 6)
		{
			return;
		}
		BankScreenshot.shadowed(g, right, rx, y, rightColour);
	}

	/**
	 * The offer as a bank item, so the hover map can reuse the bank export's
	 * slot type rather than introducing a parallel one.
	 */
	private static BankItem asItem(GrandExchangeRecord offer)
	{
		return new BankItem(offer.itemId, Math.max(1, offer.totalQuantity),
			offer.itemName, offer.pricePerItem, 0);
	}

	/** Shortens a name to fit, with an ellipsis when it has to cut. */
	private static String trim(Graphics2D g, String text, int maxWidth)
	{
		if (text == null)
		{
			return "";
		}
		if (g.getFontMetrics().stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String cut = text;
		while (cut.length() > 1 && g.getFontMetrics().stringWidth(cut + "..") > maxWidth)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut + "..";
	}
}

package com.accountalmanac;

/**
 * How account names are shown in the UI.
 *
 * <p>Display only. Nothing here is ever written back to disk - the stored
 * roster, the Grand Exchange event log and every backup keep the real names,
 * so switching back to {@link #REAL} restores them immediately and no data is
 * lost by turning masking on.
 *
 * <p>Public because it is a return type on the public
 * {@link AccountAlmanacConfig} interface. RuneLite implements that interface
 * with a JDK dynamic proxy, which lives in a different runtime package - a
 * package-private return type is unreachable from it and throws
 * {@code IllegalAccessError} as the plugin starts, taking the whole plugin
 * down with it.
 */
public enum NamePrivacy
{
	REAL("Real names"),

	/**
	 * Masks the login name and label but leaves the character's display name
	 * alone. The display name is public in game - anyone standing next to you
	 * sees it - whereas the login name identifies the person behind the
	 * account. This hides the half that actually matters.
	 */
	LOGIN_ONLY("Hide login names"),

	/** Every name replaced with asterisks. */
	ASTERISKS("Asterisks"),

	/**
	 * A stable stand-in name per account. Stable matters: a name that changed
	 * between renders would make charts and tables impossible to follow, which
	 * would defeat the purpose rather than just hiding.
	 */
	RANDOM("Stand-in names"),

	/** No name at all, just a short id derived from the account hash. */
	HIDDEN("Hidden");

	private final String label;

	NamePrivacy(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}

	boolean isMasked()
	{
		return this != REAL;
	}

	/**
	 * Whether the character's display name is masked as well as the login
	 * fields. {@link #LOGIN_ONLY} deliberately leaves it visible.
	 */
	boolean masksDisplayName()
	{
		return this != REAL && this != LOGIN_ONLY;
	}
}

package com.accountalmanac;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTable;
import javax.swing.JTabbedPane;
import javax.swing.SwingConstants;
import javax.swing.table.AbstractTableModel;
import javax.swing.table.DefaultTableCellRenderer;
import net.runelite.client.ui.ColorScheme;

/**
 * The Grand Exchange log: everything that happened to an offer, plus the
 * purchase and sale histories derived from it.
 *
 * <p>All three views read the same {@link GeEventStore}. Purchases and sales
 * are not separately recorded - they are the buy-side and sell-side outcome
 * events filtered out of the one log, which keeps a single source of truth and
 * means a trade cannot appear in history without its matching log entry.
 *
 * <p>Cancelled offers that partially filled appear in history too. A buy that
 * filled 400 of 1000 before being cancelled really did purchase 400 items, and
 * omitting it would leave a gap in the record of what was actually paid.
 */
class GeLogPanel extends JPanel
{
	private static final String ALL_ACCOUNTS = "All accounts";

	private final GeEventStore geEventStore;
	private final AccountAlmanacConfig config;

	/**
	 * Item sprites for the log's item column.
	 *
	 * <p>Created by the caller, which holds the ItemManager needed to fetch
	 * them. Null-safe: without one the column falls back to names alone.
	 */
	private ItemIconCache itemIcons;

	/**
	 * Resolves the name to show for an event's account.
	 *
	 * <p>Events store the account label as text captured when they were logged,
	 * so masking cannot be applied from the event alone - the owning account has
	 * to be looked up. Injected by the frame, which is what holds the roster and
	 * the privacy setting. Defaults to the stored label so the panel still works
	 * standalone.
	 */
	private java.util.function.Function<GeEvent, String> labelResolver = e -> e.accountLabel;

	/**
	 * Item id to current market price.
	 *
	 * <p>Supplied as a finished map rather than looked up on demand. A price
	 * lookup needs the client thread, and this renders on the Swing thread -
	 * so the caller resolves them once, from data already priced, and hands
	 * the result over. An item missing from the map simply shows no comparison.
	 */
	private Map<Integer, Integer> marketPrices = java.util.Collections.emptyMap();

	private final EventTableModel allModel = new EventTableModel();
	private final TradeTableModel purchaseModel = new TradeTableModel(false);
	private final TradeTableModel saleModel = new TradeTableModel(true);
	private final CostBasisTableModel costBasisModel = new CostBasisTableModel();

	private final JComboBox<String> accountBox = new JComboBox<>();
	private final JCheckBox hideCollections = new JCheckBox("Hide collections");
	private final JLabel summaryLabel = new JLabel();

	private boolean populating;
	private List<GeEvent> events = new ArrayList<>();

	/** Revision the cached list was read at; -1 forces the first read. */
	private long loadedRevision = -1L;

	GeLogPanel(GeEventStore geEventStore, AccountAlmanacConfig config)
	{
		this.geEventStore = geEventStore;
		this.config = config;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		accountBox.addActionListener(e ->
		{
			if (!populating)
			{
				applyFilters();
			}
		});
		hideCollections.setToolTipText(
			"Leave out the 'collected items' and 'collected coins' rows, so only "
				+ "offers starting, finishing and being cancelled are listed");
		hideCollections.addActionListener(e -> applyFilters());

		summaryLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel controls = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
		controls.add(new JLabel("Account:"));
		controls.add(accountBox);
		controls.add(hideCollections);
		controls.add(summaryLabel);

		JTabbedPane views = new JTabbedPane();
		// Column 0 is the timestamp on the three log views, so newest first;
		// on the rollup it is the item name, where the useful default is
		// instead the largest total spend (column 3).
		views.addTab("All events", new JScrollPane(buildTable(allModel, 0)));
		views.addTab("Purchases", new JScrollPane(buildTable(purchaseModel, 0)));
		views.addTab("Sales", new JScrollPane(buildTable(saleModel, 0)));
		views.addTab("By item", new JScrollPane(buildTable(costBasisModel, 3)));

		add(controls, BorderLayout.NORTH);
		add(views, BorderLayout.CENTER);
	}

	private JTable buildTable(AbstractTableModel model, int defaultSortColumn)
	{
		JTable table = new JTable(model);
		table.setAutoCreateRowSorter(true);
		table.setRowHeight(22);
		table.setFillsViewportHeight(true);
		table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);

		// Descending on the column that matters for this view: newest first for
		// the logs, biggest spend first for the rollup. Sorted explicitly rather
		// than relying on insertion order, so it survives the user sorting on
		// another column and clicking back.
		table.getRowSorter().toggleSortOrder(defaultSortColumn);
		table.getRowSorter().toggleSortOrder(defaultSortColumn);

		for (int column = 0; column < model.getColumnCount(); column++)
		{
			Class<?> type = model.getColumnClass(column);
			if (type == Long.class)
			{
				table.getColumnModel().getColumn(column).setCellRenderer(gpRenderer());
			}
			else if (type == Double.class)
			{
				table.getColumnModel().getColumn(column).setCellRenderer(percentRenderer());
			}
		}
		table.getColumnModel().getColumn(0).setPreferredWidth(130);
		return table;
	}

	/** Supplies the sprite cache used by the item column. */
	void setItemIcons(ItemIconCache icons)
	{
		this.itemIcons = icons;
	}

	/** Supplies current market prices, for the gain-potential column. */
	void setMarketPrices(Map<Integer, Integer> prices)
	{
		this.marketPrices = prices == null ? java.util.Collections.emptyMap() : prices;
	}

	/** Points the panel at a name resolver, for the privacy setting. */
	void setLabelResolver(java.util.function.Function<GeEvent, String> resolver)
	{
		this.labelResolver = resolver == null ? (e -> e.accountLabel) : resolver;
	}

	private String labelFor(GeEvent event)
	{
		String resolved = labelResolver.apply(event);
		return resolved == null || resolved.isEmpty() ? "-" : resolved;
	}

	/**
	 * Repopulates every view, re-reading the log only when it has changed.
	 *
	 * <p>This is called on the Swing thread every five seconds while the viewer
	 * is open. Re-reading means copying and sorting the entire event list -
	 * fine at a few hundred events, not at a hundred thousand - so the store's
	 * revision is checked first and the cached copy reused when nothing has
	 * been logged since.
	 */
	void reload()
	{
		long current = geEventStore.revision();
		if (current != loadedRevision)
		{
			events = geEventStore.getEventsNewestFirst();
			loadedRevision = current;
			refreshAccountOptions();
		}
		applyFilters();
	}

	private void refreshAccountOptions()
	{
		Set<String> labels = new LinkedHashSet<>();
		labels.add(ALL_ACCOUNTS);
		for (GeEvent event : events)
		{
			String label = labelFor(event);
			if (!"-".equals(label))
			{
				labels.add(label);
			}
		}

		String selected = (String) accountBox.getSelectedItem();
		populating = true;
		try
		{
			accountBox.setModel(new DefaultComboBoxModel<>(labels.toArray(new String[0])));
			accountBox.setSelectedItem(labels.contains(selected) ? selected : ALL_ACCOUNTS);
		}
		finally
		{
			populating = false;
		}
	}

	private void applyFilters()
	{
		String account = (String) accountBox.getSelectedItem();
		boolean allAccounts = account == null || ALL_ACCOUNTS.equals(account);

		List<GeEvent> all = new ArrayList<>();
		List<GeEvent> purchases = new ArrayList<>();
		List<GeEvent> sales = new ArrayList<>();

		for (GeEvent event : events)
		{
			if (!allAccounts && !account.equals(labelFor(event)))
			{
				continue;
			}

			GeEventType type = event.typeOrNull();
			if (type == null)
			{
				// An event type written by a newer version. Keep it in the raw
				// log rather than dropping it, but it cannot be classified.
				all.add(event);
				continue;
			}

			boolean isCollection = type == GeEventType.COLLECTED_ITEMS
				|| type == GeEventType.COLLECTED_COINS;
			if (!(hideCollections.isSelected() && isCollection))
			{
				all.add(event);
			}

			if (type.isTradeOutcome() && event.quantity > 0)
			{
				if (type.isSellSide())
				{
					sales.add(event);
				}
				else
				{
					purchases.add(event);
				}
			}
		}

		allModel.setEvents(all, this::labelFor);
		purchaseModel.setEvents(purchases, this::labelFor);
		purchaseModel.setMarketPrices(marketPrices);
		saleModel.setEvents(sales, this::labelFor);
		saleModel.setMarketPrices(marketPrices);
		costBasisModel.setTrades(purchases, sales);

		long spent = 0L;
		for (GeEvent event : purchases)
		{
			spent += event.totalValue;
		}
		long earned = 0L;
		for (GeEvent event : sales)
		{
			earned += event.totalValue;
		}

		summaryLabel.setText(String.format(Locale.ROOT,
			"   %d events  -  %d purchases (%s spent)  -  %d sales (%s received)",
			all.size(), purchases.size(), Format.gp(spent), sales.size(), Format.gp(earned)));
	}

	/**
	 * A signed percentage, or a dash when there is nothing to compare against.
	 *
	 * <p>Green and red here mean "the market moved in your favour" and "against
	 * it", which is why they are not the game's stack colours - this is a
	 * judgement about a trade, not a magnitude.
	 */
	private static DefaultTableCellRenderer percentRenderer()
	{
		return new DefaultTableCellRenderer()
		{
			@Override
			public Component getTableCellRendererComponent(JTable t, Object value,
				boolean selected, boolean focused, int row, int column)
			{
				super.getTableCellRendererComponent(t, value, selected, focused, row, column);
				double pct = value instanceof Number ? ((Number) value).doubleValue() : Double.NaN;

				if (Double.isNaN(pct))
				{
					setText("-");
					setToolTipText("No current price known for this item");
				}
				else
				{
					setText(String.format(Locale.ROOT, "%+.0f%%", pct));
					setToolTipText(pct >= 0
						? "Worth more now than it was traded at"
						: "Worth less now than it was traded at");
					if (!selected)
					{
						setForeground(pct >= 0 ? new Color(106, 176, 106) : new Color(198, 91, 91));
					}
				}
				setHorizontalAlignment(SwingConstants.RIGHT);
				return this;
			}
		};
	}

	private static DefaultTableCellRenderer gpRenderer()
	{
		return new DefaultTableCellRenderer()
		{
			@Override
			public Component getTableCellRendererComponent(JTable t, Object value,
				boolean selected, boolean focused, int row, int column)
			{
				super.getTableCellRendererComponent(t, value, selected, focused, row, column);
				if (value instanceof Number)
				{
					long amount = ((Number) value).longValue();
					setText(Format.gpBare(amount));
					setToolTipText(Format.exact(amount));
				}
				setHorizontalAlignment(SwingConstants.RIGHT);
				return this;
			}
		};
	}

	/**
	 * Per-item cost basis, rolled up from the trade outcomes in the log.
	 *
	 * <p>Answers "what have I actually paid for this item, and what have I sold
	 * it for" - which the chronological log cannot, once an item has been
	 * traded across several offers and several accounts.
	 *
	 * <p>Averages are weighted by quantity rather than taken as a mean of the
	 * per-offer prices. Ten bought at 100 and two thousand bought at 50 average
	 * to 50.2, not to 75.
	 */
	private static class CostBasisTableModel extends AbstractTableModel
	{
		private static final String[] COLUMNS = {
			"Item", "Bought", "Avg paid", "Total spent",
			"Sold", "Avg sold", "Total received", "Realised P/L"
		};

		private static class Row
		{
			String name = "";
			long boughtQty;
			long spent;
			long soldQty;
			long received;

			long avgPaid()
			{
				return boughtQty > 0 ? spent / boughtQty : 0L;
			}

			long avgSold()
			{
				return soldQty > 0 ? received / soldQty : 0L;
			}

			/**
			 * Profit on the quantity both bought and sold, at average prices.
			 *
			 * <p>Deliberately limited to the matched quantity. Stock sold that
			 * was acquired before logging began has no recorded cost, and
			 * counting it would report the entire sale price as profit.
			 */
			long realised()
			{
				long matched = Math.min(boughtQty, soldQty);
				return matched > 0 ? matched * (avgSold() - avgPaid()) : 0L;
			}
		}

		private List<Row> rows = new ArrayList<>();

		void setTrades(List<GeEvent> purchases, List<GeEvent> sales)
		{
			Map<Integer, Row> byId = new LinkedHashMap<>();

			for (GeEvent event : purchases)
			{
				Row row = byId.computeIfAbsent(event.itemId, id -> new Row());
				row.name = event.itemName.isEmpty() ? ("Item " + event.itemId) : event.itemName;
				row.boughtQty += event.quantity;
				row.spent += event.totalValue;
			}
			for (GeEvent event : sales)
			{
				Row row = byId.computeIfAbsent(event.itemId, id -> new Row());
				if (row.name.isEmpty())
				{
					row.name = event.itemName.isEmpty() ? ("Item " + event.itemId) : event.itemName;
				}
				row.soldQty += event.quantity;
				row.received += event.totalValue;
			}

			this.rows = new ArrayList<>(byId.values());
			fireTableDataChanged();
		}

		@Override
		public int getRowCount()
		{
			return rows.size();
		}

		@Override
		public int getColumnCount()
		{
			return COLUMNS.length;
		}

		@Override
		public String getColumnName(int column)
		{
			return COLUMNS[column];
		}

		@Override
		public Class<?> getColumnClass(int column)
		{
			return column == 0 ? String.class : Long.class;
		}

		@Override
		public Object getValueAt(int row, int column)
		{
			Row entry = rows.get(row);
			switch (column)
			{
				case 0:
					return entry.name;
				case 1:
					return entry.boughtQty;
				case 2:
					return entry.avgPaid();
				case 3:
					return entry.spent;
				case 4:
					return entry.soldQty;
				case 5:
					return entry.avgSold();
				case 6:
					return entry.received;
				case 7:
					return entry.realised();
				default:
					return "";
			}
		}
	}

	/**
	 * Base model holding the filtered event list. Timestamps are exposed as a
	 * formatted string that sorts correctly as text, because the format is
	 * {@code yyyy-MM-dd HH:mm} - lexical order and chronological order agree.
	 */
	private abstract static class BaseModel extends AbstractTableModel
	{
		List<GeEvent> rows = new ArrayList<>();
		java.util.function.Function<GeEvent, String> labels = e -> e.accountLabel;

		void setEvents(List<GeEvent> events, java.util.function.Function<GeEvent, String> labels)
		{
			this.rows = events;
			this.labels = labels;
			fireTableDataChanged();
		}

		@Override
		public int getRowCount()
		{
			return rows.size();
		}
	}

	/** The raw log: one row per event, whatever kind it is. */
	private static class EventTableModel extends BaseModel
	{
		private static final String[] COLUMNS = {
			"When", "Account", "Event", "Item", "Quantity", "Unit price", "Value", "Slot"
		};

		@Override
		public int getColumnCount()
		{
			return COLUMNS.length;
		}

		@Override
		public String getColumnName(int column)
		{
			return COLUMNS[column];
		}

		@Override
		public Class<?> getColumnClass(int column)
		{
			switch (column)
			{
				case 4:
					return Integer.class;
				case 5:
				case 6:
					return Long.class;
				case 7:
					return Integer.class;
				default:
					return String.class;
			}
		}

		@Override
		public Object getValueAt(int row, int column)
		{
			GeEvent event = rows.get(row);
			switch (column)
			{
				case 0:
					// An approximate timestamp is marked, because it is when the
					// change was noticed rather than when it happened.
					return LoginAge.exact(event.at) + (event.approximate ? " ~" : "");
				case 1:
					return labels.apply(event);
				case 2:
					return event.typeLabel();
				case 3:
					return event.itemName.isEmpty() ? "-" : event.itemName;
				case 4:
					return event.quantity;
				case 5:
					return (long) event.pricePerItem;
				case 6:
					return event.totalValue;
				case 7:
					return event.slot < 0 ? 0 : event.slot + 1;
				default:
					return "";
			}
		}
	}

	/**
	 * Purchase or sale history: what was traded, how much of it, at what price
	 * and when.
	 *
	 * <p>Both the listed price and the price actually transacted are shown.
	 * They differ often and meaningfully - a buy offer fills at or below the
	 * price you set, so the listed price is what you were willing to pay while
	 * the actual is what you paid.
	 */
	private static class TradeTableModel extends BaseModel
	{
		private final String[] columns;

		private Map<Integer, Integer> marketPrices = java.util.Collections.emptyMap();

		TradeTableModel(boolean sellSide)
		{
			this.columns = new String[]{
				"When", "Account", "Item", "Quantity",
				"Listed price", sellSide ? "Received per item" : "Paid per item",
				sellSide ? "Total received" : "Total paid",
				"Market now", "vs market", "Outcome"
			};
		}

		void setMarketPrices(Map<Integer, Integer> prices)
		{
			this.marketPrices = prices == null ? java.util.Collections.emptyMap() : prices;
			fireTableDataChanged();
		}

		@Override
		public int getColumnCount()
		{
			return columns.length;
		}

		@Override
		public String getColumnName(int column)
		{
			return columns[column];
		}

		@Override
		public Class<?> getColumnClass(int column)
		{
			switch (column)
			{
				case 3:
					return Integer.class;
				case 4:
				case 5:
				case 6:
				case 7:
					return Long.class;
				case 8:
					return Double.class;
				default:
					return String.class;
			}
		}

		/**
		 * How far the price transacted sits from what the item is worth now.
		 *
		 * <p>On a purchase this is the gain still on the table: buying at 1 gp
		 * something now worth 9,000 is not visible from the paid price alone.
		 * On a sale it reads the other way - positive means the market has
		 * risen since, so it went too cheap.
		 */
		private double versusMarket(GeEvent event)
		{
			Integer market = marketPrices.get(event.itemId);
			long paid = event.actualUnitPrice();
			if (market == null || market <= 0 || paid <= 0)
			{
				return Double.NaN;
			}
			return 100.0 * (market - paid) / (double) paid;
		}

		@Override
		public Object getValueAt(int row, int column)
		{
			GeEvent event = rows.get(row);
			switch (column)
			{
				case 0:
					return LoginAge.exact(event.at) + (event.approximate ? " ~" : "");
				case 1:
					return labels.apply(event);
				case 2:
					return event.itemName.isEmpty() ? "-" : event.itemName;
				case 3:
					return event.quantity;
				case 4:
					return (long) event.pricePerItem;
				case 5:
					return event.actualUnitPrice();
				case 6:
					return event.totalValue;
				case 7:
				{
					Integer market = marketPrices.get(event.itemId);
					return market == null ? 0L : (long) market;
				}
				case 8:
					return versusMarket(event);
				case 9:
				{
					GeEventType type = event.typeOrNull();
					if (type == GeEventType.BUY_CANCELLED || type == GeEventType.SELL_CANCELLED)
					{
						return "Cancelled part-filled";
					}
					return "Completed";
				}
				default:
					return "";
			}
		}
	}
}

package com.accountalmanac;

import java.io.File;
import java.io.IOException;
import java.util.List;
import java.util.Map;

/**
 * Writes the plugin's tables out as CSV.
 *
 * <p>Raw values throughout: unformatted numbers, epoch millis for times, item
 * ids alongside names. A CSV exists to be computed on, and every formatting
 * decision taken here is one the reader cannot undo - a spreadsheet can render
 * 1200000 however it likes, but it cannot recover the number from "1.2M".
 *
 * <p>Each export is one streaming pass over records already in memory. Nothing
 * is collected into an intermediate list first, so the cost is the file write.
 */
final class CsvExport
{
	private CsvExport()
	{
	}

	/**
	 * Every distinct item held across the supplied accounts.
	 *
	 * @return how many rows were written
	 */
	static int items(File file, List<AccountRecord> accounts) throws IOException
	{
		List<ItemAggregator.ItemTotal> totals = ItemAggregator.aggregate(accounts);
		try (Csv csv = Csv.open(file,
			"item_id", "item", "members", "quantity", "unit_price",
			"total_value", "accounts_holding"))
		{
			for (ItemAggregator.ItemTotal total : totals)
			{
				csv.row(total.itemId, total.name, total.members,
					total.totalQuantity, total.unitPrice, total.totalValue,
					total.accountCount());
			}
			return totals.size();
		}
	}

	/** One row per account: identity, levels and wealth. */
	static int accounts(File file, List<AccountRecord> accounts, NamePrivacy privacy)
		throws IOException
	{
		try (Csv csv = Csv.open(file,
			"account", "login_name", "label", "group", "type", "hidden", "banned",
			"combat", "total_level", "total_xp", "quest_points", "quest_points_max",
			"playtime_minutes", "bank_value", "ge_value", "total_wealth",
			"bank_items", "last_login_millis", "bank_seen_millis"))
		{
			for (AccountRecord a : accounts)
			{
				csv.row(
					NameMasker.display(a, privacy),
					NameMasker.displayField(a.loginName, a.accountHash, privacy),
					NameMasker.displayField(a.loginLabel, a.accountHash, privacy),
					a.categoryLabel(),
					AccountTypeBadge.fullLabel(a.accountType),
					a.hidden, a.banned,
					a.combatLevel, a.totalLevel(), a.totalXp(),
					// Blank rather than zero when never captured: an account
					// with no quest points and one never read are different.
					a.hasQuestPoints() ? a.questPoints : null,
					a.hasQuestPoints() ? a.questPointsMax : null,
					a.playtimeMinutes > 0 ? a.playtimeMinutes : null,
					a.bankValue, a.geValue(), a.totalWealth(),
					a.bankItems.size(),
					a.lastLoginAt > 0 ? a.lastLoginAt : null,
					a.hasBankSnapshot() ? a.lastSnapshotAt : null);
			}
			return accounts.size();
		}
	}

	/** Every account's bank, one row per stack, so it can be pivoted. */
	static int banks(File file, List<AccountRecord> accounts, NamePrivacy privacy)
		throws IOException
	{
		int rows = 0;
		try (Csv csv = Csv.open(file,
			"account", "item_id", "item", "members", "quantity",
			"unit_price", "total_value", "alch_price", "bank_seen_millis"))
		{
			for (AccountRecord a : accounts)
			{
				String name = NameMasker.display(a, privacy);
				for (BankItem item : a.bankItems)
				{
					if (item.quantity <= 0)
					{
						// Bank placeholder, not a held stack.
						continue;
					}
					csv.row(name, item.id, item.name, item.members, item.quantity,
						item.unitPrice, item.totalValue(), item.haPrice,
						a.hasBankSnapshot() ? a.lastSnapshotAt : null);
					rows++;
				}
			}
		}
		return rows;
	}

	/** Open Grand Exchange slots, with how far each sits from market price. */
	static int offers(File file, List<AccountRecord> accounts, NamePrivacy privacy)
		throws IOException
	{
		int rows = 0;
		try (Csv csv = Csv.open(file,
			"account", "slot", "type", "state", "item_id", "item",
			"quantity_traded", "quantity_total", "progress", "unit_price",
			"market_price", "vs_market", "spent", "committed"))
		{
			for (AccountRecord a : accounts)
			{
				String name = NameMasker.display(a, privacy);
				for (GrandExchangeRecord o : a.geOffers)
				{
					if (!o.isActive())
					{
						continue;
					}
					csv.row(name, o.slot + 1, o.typeLabel(), o.state, o.itemId, o.itemName,
						o.quantitySold, o.totalQuantity,
						// A fraction, not a percentage string, so it can be
						// charted or averaged without being parsed back.
						round(o.progress()),
						o.pricePerItem,
						o.marketPrice > 0 ? o.marketPrice : null,
						o.priceVsMarket() == null ? null : round(o.priceVsMarket()),
						o.spent, o.committedValue());
					rows++;
				}
			}
		}
		return rows;
	}

	/**
	 * Wealth and experience over time, one row per snapshot.
	 *
	 * <p>This is the export that makes the history chartable outside the
	 * plugin, which is the whole reason it is worth having.
	 */
	static int history(File file, List<AccountRecord> accounts, HistoryStore store,
		NamePrivacy privacy) throws IOException
	{
		int rows = 0;
		try (Csv csv = Csv.open(file,
			"account", "at_millis", "bank_value", "ge_value", "total_wealth",
			"total_xp", "total_level", "combat_level"))
		{
			for (AccountRecord a : accounts)
			{
				AccountHistory history = store.historyFor(a.accountHash);
				if (history == null)
				{
					continue;
				}
				String name = NameMasker.display(a, privacy);
				for (HistorySnapshot s : history.snapshots)
				{
					csv.row(name, s.at, s.bankValue, s.geValue, s.totalWealth(),
						s.totalXp, s.totalLevel, s.combatLevel);
					rows++;
				}
			}
		}
		return rows;
	}

	/** Per-skill experience for every account, long form for pivoting. */
	static int skills(File file, List<AccountRecord> accounts, NamePrivacy privacy)
		throws IOException
	{
		int rows = 0;
		try (Csv csv = Csv.open(file, "account", "skill", "level", "xp"))
		{
			for (AccountRecord a : accounts)
			{
				String name = NameMasker.display(a, privacy);
				for (Map.Entry<String, Integer> entry : a.skillXp.entrySet())
				{
					Integer level = a.skillLevels.get(entry.getKey());
					csv.row(name, entry.getKey(), level, entry.getValue());
					rows++;
				}
			}
		}
		return rows;
	}

	/** Four decimals is past anything the source data justifies. */
	private static double round(double v)
	{
		return Math.round(v * 10000.0) / 10000.0;
	}
}

package com.accountalmanac;

import java.text.NumberFormat;
import java.util.Locale;

/**
 * How a number is rendered. Selectable per value category (wealth, gp change,
 * stat gain, plain counts) so the same amount can read as {@code "237.7K"} in
 * a cramped chart legend and {@code "237,700"} in a table the user is
 * actually reconciling against the game.
 *
 * <p>{@link #ABBREVIATED} deliberately keeps one decimal place below the
 * billion mark. Rounding 237,700 to a bare {@code "237K"} loses the digit the
 * user is usually looking at, which is exactly the complaint that drove the
 * switch away from RuneLite's {@code quantityToStackSize} formatting.
 *
 * <p>Public because it is a return type on the public
 * {@link AccountAlmanacConfig} interface. RuneLite implements that interface
 * with a JDK dynamic proxy, which lives in a different runtime package - a
 * package-private return type is unreachable from it and throws
 * {@code IllegalAccessError} as the plugin starts, taking the whole plugin
 * down with it.
 */
public enum NumberFormatMode
{
	/** {@code 237.7K} - short, for legends and narrow columns. */
	ABBREVIATED("Abbreviated"),

	/** {@code 237,700} - full precision, thousands separated. */
	FULL_WITH_COMMAS("With commas"),

	/** {@code 237700} - full precision, no separators, easy to copy out. */
	FULL_PLAIN("Plain digits");

	private final String label;

	NumberFormatMode(String label)
	{
		this.label = label;
	}

	String label()
	{
		return label;
	}

	@Override
	public String toString()
	{
		// Drives the text shown in RuneLite's config dropdown and the
		// viewer's own combo boxes, so both read the same.
		return label;
	}

	String format(long amount)
	{
		switch (this)
		{
			case FULL_WITH_COMMAS:
				return NumberFormat.getIntegerInstance(Locale.ROOT).format(amount);
			case FULL_PLAIN:
				return Long.toString(amount);
			case ABBREVIATED:
			default:
				return abbreviate(amount);
		}
	}

	/**
	 * Two decimals at billions, one below. Negatives are handled by sign
	 * rather than by {@code Math.abs}, because {@code Long.MIN_VALUE} has no
	 * positive counterpart and would silently stay negative.
	 */
	private static String abbreviate(long amount)
	{
		if (amount >= 1_000_000_000L || amount <= -1_000_000_000L)
		{
			return String.format(Locale.ROOT, "%.2fB", amount / 1_000_000_000.0);
		}
		if (amount >= 1_000_000L || amount <= -1_000_000L)
		{
			return String.format(Locale.ROOT, "%.1fM", amount / 1_000_000.0);
		}
		if (amount >= 1_000L || amount <= -1_000L)
		{
			return String.format(Locale.ROOT, "%.1fK", amount / 1_000.0);
		}
		return Long.toString(amount);
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Root object persisted to {@code history.json}.
 *
 * <p>Kept in its own file rather than inside {@code accounts.json} on purpose.
 * History is append-mostly and grows without bound until pruned, while the
 * account file is the irreplaceable one - forty accounts of identities, banks
 * and labels. Separate files mean a corrupt or oversized history can be
 * discarded on its own without risking the data that actually matters.
 */
class HistoryData
{
	int schemaVersion = 1;

	List<AccountHistory> histories = new ArrayList<>();

	/**
	 * Item id to the price it was last compared against, keyed as a string
	 * because that is how Gson writes map keys anyway.
	 *
	 * <p>This is the baseline price movement is measured from. It rolls
	 * forward once it is older than the comparison window, so it always
	 * represents roughly one window ago rather than drifting to whenever the
	 * plugin first ran.
	 */
	Map<String, PricePoint> priceBaselines = new HashMap<>();

	void normalise()
	{
		if (priceBaselines == null)
		{
			priceBaselines = new HashMap<>();
		}
		if (histories == null)
		{
			histories = new ArrayList<>();
			return;
		}
		for (AccountHistory history : histories)
		{
			history.normalise();
		}
	}
}

package com.accountalmanac;

import java.io.BufferedWriter;
import java.io.File;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Writes everything the plugin knows into one self-contained HTML page.
 *
 * <p>One file, not a folder: it opens in a browser with no unpacking, and it
 * can be sent to somebody who has neither the plugin nor a spreadsheet. The
 * CSV exports remain the right answer for computing on the data; this is the
 * right answer for reading and sharing it.
 *
 * <p>Nothing is loaded from the network - no fonts, no scripts, no styles - so
 * the page renders identically offline and years from now. The sorting and
 * filtering are a few dozen lines of inline script rather than a library, for
 * the same reason.
 *
 * <p>Streamed a row at a time through a buffered writer, so a roster-wide
 * report of twelve thousand bank rows never exists as a string in memory.
 */
final class HtmlReport
{
	private HtmlReport()
	{
	}

	/**
	 * @return how many table rows were written in total
	 */
	static int write(File file, List<AccountRecord> accounts, HistoryStore historyStore,
		NamePrivacy privacy) throws IOException
	{
		int rows = 0;
		try (Writer w = new BufferedWriter(new OutputStreamWriter(
			Files.newOutputStream(file.toPath()), StandardCharsets.UTF_8), 1 << 16))
		{
			head(w, accounts);
			rows += accountsSection(w, accounts, privacy);
			rows += itemsSection(w, accounts);
			rows += offersSection(w, accounts, privacy);
			rows += historySection(w, accounts, historyStore, privacy);
			rows += skillsSection(w, accounts, privacy);
			rows += banksSection(w, accounts, privacy);
			tail(w);
		}
		return rows;
	}

	// ---- sections ----------------------------------------------------------

	private static int accountsSection(Writer w, List<AccountRecord> accounts,
		NamePrivacy privacy) throws IOException
	{
		open(w, "accounts", "Accounts", accounts.size(),
			"Account", "Group", "Type", "Combat", "Total level", "Quests",
			"Bank", "GE", "Total wealth", "Last login");
		for (AccountRecord a : accounts)
		{
			w.write("<tr>");
			td(w, NameMasker.display(a, privacy));
			td(w, a.categoryLabel());
			td(w, AccountTypeBadge.fullLabel(a.accountType));
			num(w, a.combatLevel);
			num(w, a.totalLevel());
			tdRaw(w, a.hasQuestPoints() ? a.questPointsLabel() : "-", a.questPoints, true);
			gp(w, a.bankValue);
			gp(w, a.geValue());
			gp(w, a.totalWealth());
			tdRaw(w, a.lastLoginAt > 0 ? LoginAge.friendly(a.lastLoginAt) : "never",
				a.lastLoginAt, false);
			w.write("</tr>\n");
		}
		close(w);
		return accounts.size();
	}

	private static int itemsSection(Writer w, List<AccountRecord> accounts) throws IOException
	{
		List<ItemAggregator.ItemTotal> totals = ItemAggregator.aggregate(accounts);
		open(w, "items", "Items across all accounts", totals.size(),
			"Item", "Id", "Members", "Quantity", "Unit price", "Total value", "Accounts");
		for (ItemAggregator.ItemTotal t : totals)
		{
			w.write("<tr>");
			td(w, t.name);
			num(w, t.itemId);
			td(w, t.members == null ? "-" : (t.members ? "members" : "f2p"));
			num(w, t.totalQuantity);
			gp(w, t.unitPrice);
			gp(w, t.totalValue);
			num(w, t.accountCount());
			w.write("</tr>\n");
		}
		close(w);
		return totals.size();
	}

	private static int offersSection(Writer w, List<AccountRecord> accounts,
		NamePrivacy privacy) throws IOException
	{
		int n = 0;
		open(w, "offers", "Grand Exchange offers", countOffers(accounts),
			"Account", "Slot", "Type", "Item", "Progress", "Unit price",
			"vs market", "Committed");
		for (AccountRecord a : accounts)
		{
			String name = NameMasker.display(a, privacy);
			for (GrandExchangeRecord o : a.geOffers)
			{
				if (!o.isActive())
				{
					continue;
				}
				w.write("<tr>");
				td(w, name);
				num(w, o.slot + 1);
				td(w, o.typeLabel());
				td(w, o.itemName);
				bar(w, o.progress());
				gp(w, o.pricePerItem);
				Double gap = o.priceVsMarket();
				if (gap == null)
				{
					tdRaw(w, "-", Long.MIN_VALUE, true);
				}
				else
				{
					w.write("<td class=\"n ");
					w.write(o.priceGapFavourable() ? "good" : "bad");
					w.write("\" data-s=\"");
					w.write(Long.toString(Math.round(gap * 10000)));
					w.write("\">");
					esc(w, GeScreenshot.marketGapLabel(o));
					w.write("</td>");
				}
				gp(w, o.committedValue());
				w.write("</tr>\n");
				n++;
			}
		}
		close(w);
		return n;
	}

	private static int historySection(Writer w, List<AccountRecord> accounts,
		HistoryStore store, NamePrivacy privacy) throws IOException
	{
		int n = 0;
		open(w, "history", "Wealth and experience over time", -1,
			"Account", "When", "Bank", "GE", "Total wealth", "Total XP", "Total level");
		for (AccountRecord a : accounts)
		{
			AccountHistory h = store.historyFor(a.accountHash);
			if (h == null)
			{
				continue;
			}
			String name = NameMasker.display(a, privacy);
			for (HistorySnapshot s : h.snapshots)
			{
				w.write("<tr>");
				td(w, name);
				tdRaw(w, LoginAge.exact(s.at), s.at, false);
				gp(w, s.bankValue);
				gp(w, s.geValue);
				gp(w, s.totalWealth());
				num(w, s.totalXp);
				num(w, s.totalLevel);
				w.write("</tr>\n");
				n++;
			}
		}
		close(w);
		return n;
	}

	private static int skillsSection(Writer w, List<AccountRecord> accounts,
		NamePrivacy privacy) throws IOException
	{
		int n = 0;
		open(w, "skills", "Skills", -1, "Account", "Skill", "Level", "XP");
		for (AccountRecord a : accounts)
		{
			String name = NameMasker.display(a, privacy);
			for (Map.Entry<String, Integer> e : a.skillXp.entrySet())
			{
				Integer level = a.skillLevels.get(e.getKey());
				w.write("<tr>");
				td(w, name);
				td(w, e.getKey());
				num(w, level == null ? 0 : level);
				num(w, e.getValue() == null ? 0 : e.getValue());
				w.write("</tr>\n");
				n++;
			}
		}
		close(w);
		return n;
	}

	private static int banksSection(Writer w, List<AccountRecord> accounts,
		NamePrivacy privacy) throws IOException
	{
		int n = 0;
		open(w, "banks", "Every bank, one row per stack", -1,
			"Account", "Item", "Id", "Members", "Quantity", "Unit price", "Total value");
		for (AccountRecord a : accounts)
		{
			String name = NameMasker.display(a, privacy);
			for (BankItem i : a.bankItems)
			{
				if (i.quantity <= 0)
				{
					// Bank placeholder, not a held stack.
					continue;
				}
				w.write("<tr>");
				td(w, name);
				td(w, i.name);
				num(w, i.id);
				td(w, i.members == null ? "-" : (i.members ? "members" : "f2p"));
				num(w, i.quantity);
				gp(w, i.unitPrice);
				gp(w, i.totalValue());
				w.write("</tr>\n");
				n++;
			}
		}
		close(w);
		return n;
	}

	private static int countOffers(List<AccountRecord> accounts)
	{
		int n = 0;
		for (AccountRecord a : accounts)
		{
			for (GrandExchangeRecord o : a.geOffers)
			{
				if (o.isActive())
				{
					n++;
				}
			}
		}
		return n;
	}

	// ---- cells -------------------------------------------------------------

	private static void td(Writer w, String text) throws IOException
	{
		w.write("<td>");
		esc(w, text);
		w.write("</td>");
	}

	/** Number cell: right aligned, and sorted on its own value not its text. */
	private static void num(Writer w, long value) throws IOException
	{
		w.write("<td class=\"n\" data-s=\"");
		w.write(Long.toString(value));
		w.write("\">");
		esc(w, Format.exact(value));
		w.write("</td>");
	}

	private static void gp(Writer w, long value) throws IOException
	{
		w.write("<td class=\"n gp\" data-s=\"");
		w.write(Long.toString(value));
		w.write("\">");
		esc(w, Format.exact(value));
		w.write("</td>");
	}

	/** Text cell that sorts on a supplied key rather than the displayed text. */
	private static void tdRaw(Writer w, String text, long sortKey, boolean numeric)
		throws IOException
	{
		w.write(numeric ? "<td class=\"n\" data-s=\"" : "<td data-s=\"");
		w.write(Long.toString(sortKey));
		w.write("\">");
		esc(w, text);
		w.write("</td>");
	}

	/** Progress as a bar, coloured by the same bands the plugin uses. */
	private static void bar(Writer w, double fraction) throws IOException
	{
		int pct = (int) Math.round(fraction * 100);
		w.write("<td class=\"n\" data-s=\"");
		w.write(Integer.toString(pct));
		w.write("\"><span class=\"bar\"><i style=\"width:");
		w.write(Integer.toString(Math.max(0, Math.min(100, pct))));
		w.write("%;background:");
		w.write(hex(ProgressColours.forFraction(fraction)));
		w.write("\"></i></span> ");
		w.write(Integer.toString(pct));
		w.write("%</td>");
	}

	private static String hex(java.awt.Color c)
	{
		return String.format(Locale.ROOT, "#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}

	// ---- page ---------------------------------------------------------------

	private static void open(Writer w, String id, String title, int count, String... headers)
		throws IOException
	{
		w.write("<section id=\"");
		w.write(id);
		w.write("\"><h2>");
		esc(w, title);
		if (count >= 0)
		{
			w.write(" <span class=\"c\">");
			w.write(Format.exact(count));
			w.write("</span>");
		}
		w.write("</h2><input class=\"f\" placeholder=\"Filter these rows...\"><table><thead><tr>");
		for (String h : headers)
		{
			w.write("<th>");
			esc(w, h);
			w.write("</th>");
		}
		w.write("</tr></thead><tbody>\n");
	}

	private static void close(Writer w) throws IOException
	{
		w.write("</tbody></table></section>\n");
	}

	private static void head(Writer w, List<AccountRecord> accounts) throws IOException
	{
		long wealth = 0L;
		long xp = 0L;
		for (AccountRecord a : accounts)
		{
			wealth += a.totalWealth();
			xp += a.totalXp();
		}
		String when = new SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.ROOT).format(new Date());

		w.write("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">"
			+ "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
			+ "<title>Account Almanac report</title><style>"
			+ ":root{--bg:#241f18;--panel:#2e2820;--line:#413a2e;--text:#ddd3bd;"
			+ "--dim:#9a8f79;--accent:#ff981f}"
			+ "*{box-sizing:border-box}"
			+ "body{margin:0;padding:24px 16px;background:var(--bg);color:var(--text);"
			+ "font:13px/1.5 system-ui,Segoe UI,Roboto,sans-serif}"
			+ ".wrap{max-width:1200px;margin:0 auto}"
			+ "h1{color:var(--accent);font-size:20px;margin:0 0 4px}"
			+ ".sub{color:var(--dim);margin:0 0 20px}"
			+ ".tot{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 24px}"
			+ ".tot div{background:var(--panel);border:1px solid var(--line);"
			+ "border-radius:6px;padding:10px 14px;min-width:150px}"
			+ ".tot b{display:block;color:var(--accent);font-size:17px}"
			+ ".tot span{color:var(--dim)}"
			+ "nav{margin:0 0 20px}nav a{color:var(--accent);margin-right:14px}"
			+ "section{margin:0 0 30px}"
			+ "h2{font-size:15px;border-bottom:1px solid var(--line);padding-bottom:6px}"
			+ "h2 .c{color:var(--dim);font-weight:400;font-size:12px}"
			+ ".f{width:240px;max-width:100%;margin:0 0 8px;padding:5px 8px;"
			+ "background:var(--bg);border:1px solid var(--line);border-radius:4px;color:var(--text)}"
			+ ".tw{overflow-x:auto}"
			+ "table{border-collapse:collapse;width:100%;font-size:12px}"
			+ "th,td{padding:4px 8px;border-bottom:1px solid var(--line);text-align:left;"
			+ "white-space:nowrap}"
			+ "th{position:sticky;top:0;background:var(--panel);cursor:pointer;user-select:none}"
			+ "th:hover{color:var(--accent)}"
			+ "td.n{text-align:right;font-variant-numeric:tabular-nums}"
			+ "td.gp{color:#e0c46a}.good{color:#5ac85a}.bad{color:#d05040}"
			+ "tbody tr:nth-child(even){background:rgba(255,255,255,.02)}"
			+ ".bar{display:inline-block;width:60px;height:8px;background:#1d1913;"
			+ "border-radius:2px;overflow:hidden;vertical-align:middle;margin-right:6px}"
			+ ".bar i{display:block;height:100%}"
			+ "@media print{body{background:#fff;color:#000}th{background:#eee}}"
			+ "</style></head><body><div class=\"wrap\">");

		w.write("<h1>Account Almanac</h1><p class=\"sub\">");
		esc(w, accounts.size() + (accounts.size() == 1 ? " account" : " accounts")
			+ "  -  generated " + when);
		w.write("</p><div class=\"tot\"><div><b>");
		esc(w, Format.gp(wealth));
		w.write("</b><span>total wealth</span></div><div><b>");
		esc(w, Format.exact(xp));
		w.write("</b><span>total experience</span></div><div><b>");
		esc(w, Format.exact(countOffers(accounts)));
		w.write("</b><span>open offers</span></div></div>");

		w.write("<nav><a href=\"#accounts\">Accounts</a><a href=\"#items\">Items</a>"
			+ "<a href=\"#offers\">Offers</a><a href=\"#history\">History</a>"
			+ "<a href=\"#skills\">Skills</a><a href=\"#banks\">Banks</a></nav>");
	}

	private static void tail(Writer w) throws IOException
	{
		// Sorting reads data-s where a cell has one, so numbers and dates order
		// by value rather than by how they happen to be written.
		w.write("</div><script>\n"
			+ "document.querySelectorAll('table').forEach(function(t){\n"
			+ " t.parentNode.insertBefore(document.createElement('div'),t)"
			+ ".className='tw',t.previousSibling.appendChild(t);\n"
			+ " t.querySelectorAll('th').forEach(function(th,i){\n"
			+ "  th.addEventListener('click',function(){\n"
			+ "   var b=t.tBodies[0],r=[].slice.call(b.rows),"
			+ "asc=th.dataset.a!=='1';\n"
			+ "   t.querySelectorAll('th').forEach(function(o){o.dataset.a=''});\n"
			+ "   th.dataset.a=asc?'1':'';\n"
			+ "   r.sort(function(x,y){\n"
			+ "    var a=x.cells[i],c=y.cells[i];\n"
			+ "    if(a.dataset.s!==undefined&&c.dataset.s!==undefined)"
			+ "return (asc?1:-1)*(Number(a.dataset.s)-Number(c.dataset.s));\n"
			+ "    return (asc?1:-1)*a.textContent.localeCompare(c.textContent);\n"
			+ "   });\n"
			+ "   r.forEach(function(x){b.appendChild(x)});\n"
			+ "  });\n"
			+ " });\n"
			+ "});\n"
			+ "document.querySelectorAll('.f').forEach(function(inp){\n"
			+ " inp.addEventListener('input',function(){\n"
			+ "  var q=inp.value.toLowerCase(),"
			+ "b=inp.parentNode.querySelector('tbody');\n"
			+ "  [].forEach.call(b.rows,function(r){\n"
			+ "   r.style.display=!q||r.textContent.toLowerCase().indexOf(q)>-1?'':'none';\n"
			+ "  });\n"
			+ " });\n"
			+ "});\n"
			+ "</script></body></html>\n");
	}

	/** Minimal, correct HTML escaping. */
	private static void esc(Writer w, String text) throws IOException
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			switch (c)
			{
				case '&':
					w.write("&amp;");
					break;
				case '<':
					w.write("&lt;");
					break;
				case '>':
					w.write("&gt;");
					break;
				case '"':
					w.write("&quot;");
					break;
				default:
					w.write(c);
			}
		}
	}
}

package com.accountalmanac;

import com.google.gson.Gson;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Persists per-account snapshot history to {@code history.json}.
 *
 * <p>Follows the same discipline as {@link AccountStore}: all mutation is
 * synchronized, disk IO happens on the injected executor rather than the
 * client thread, and high-frequency updates only mark dirty so a periodic
 * flush picks them up.
 *
 * <p>Snapshots are throttled by {@code minIntervalHours} - the default of one
 * per day gives the 7 day window a week of distinct points to compare, while
 * keeping a year of history for forty accounts to a few thousand records
 * rather than hundreds of thousands.
 */
@Slf4j
@Singleton
class HistoryStore
{
	private static final String FILE_NAME = "history.json";

	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final File dataFile;

	private HistoryData data = new HistoryData();
	private volatile boolean dirty;

	@Inject
	HistoryStore(Gson gson, ScheduledExecutorService executor)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.executor = executor;
		this.dataFile = new File(new File(RuneLite.RUNELITE_DIR, "accountalmanac"), FILE_NAME);
	}

	void loadAsync(Runnable onLoaded)
	{
		executor.execute(() ->
		{
			synchronized (this)
			{
				data = JsonFile.read(dataFile, gson, HistoryData.class, HistoryData::new);
				data.normalise();
			}
			if (onLoaded != null)
			{
				onLoaded.run();
			}
		});
	}

	File file()
	{
		return dataFile;
	}

	/**
	 * Records the account's current figures as a snapshot, subject to the
	 * throttle interval.
	 *
	 * @param minIntervalHours smallest gap between retained snapshots
	 * @return {@code true} if history changed and a flush is warranted
	 */
	synchronized boolean recordSnapshot(AccountRecord record, long now, int minIntervalHours)
	{
		if (record == null)
		{
			return false;
		}

		HistorySnapshot snapshot = HistorySnapshot.of(record, now);
		if (snapshot.isEmpty())
		{
			// Nothing observed for this account yet - an empty baseline would
			// make the first real snapshot look like an enormous gain.
			return false;
		}

		long interval = TimeUnit.HOURS.toMillis(Math.max(1, minIntervalHours));
		AccountHistory history = findOrCreate(record.accountHash);
		if (history.record(snapshot, interval))
		{
			dirty = true;
			return true;
		}
		return false;
	}

	synchronized AccountHistory historyFor(long accountHash)
	{
		for (AccountHistory history : data.histories)
		{
			if (history.accountHash == accountHash)
			{
				return history;
			}
		}
		return null;
	}

	/** Defensive copy, safe to read from the Swing thread. */
	synchronized List<AccountHistory> getHistories()
	{
		return new ArrayList<>(data.histories);
	}

	synchronized int totalSnapshotCount()
	{
		int count = 0;
		for (AccountHistory history : data.histories)
		{
			count += history.snapshots.size();
		}
		return count;
	}

	/**
	 * Oldest snapshot timestamp across every account, or 0 if there is none.
	 * Used to tell the user how far their history actually reaches, so a
	 * "past year" window can say when it is really showing less.
	 */
	synchronized long earliestSnapshotAt()
	{
		long earliest = 0L;
		for (AccountHistory history : data.histories)
		{
			HistorySnapshot first = history.earliest();
			if (first != null && (earliest == 0L || first.at < earliest))
			{
				earliest = first.at;
			}
		}
		return earliest;
	}

	/**
	 * Updates the price baselines from a fresh set of prices.
	 *
	 * <p>An item with no baseline yet records one and reports no movement -
	 * "up 100%" on the first sighting would be nonsense. An existing baseline
	 * older than {@code windowMillis} rolls forward to the current price, so
	 * the comparison stays roughly one window wide instead of drifting back to
	 * whenever the plugin first ran.
	 *
	 * @return {@code true} if anything changed and a flush is warranted
	 */
	synchronized boolean updatePriceBaselines(Map<Integer, Integer> current, long now, long windowMillis)
	{
		boolean changed = false;
		for (Map.Entry<Integer, Integer> entry : current.entrySet())
		{
			if (entry.getValue() == null || entry.getValue() <= 0)
			{
				continue;
			}
			String key = Integer.toString(entry.getKey());
			PricePoint existing = data.priceBaselines.get(key);
			if (existing == null || now - existing.at >= windowMillis)
			{
				data.priceBaselines.put(key, new PricePoint(entry.getValue(), now));
				changed = true;
			}
		}
		if (changed)
		{
			dirty = true;
		}
		return changed;
	}

	/** The baseline for an item, or {@code null} if it has never been priced. */
	synchronized PricePoint priceBaseline(int itemId)
	{
		return data.priceBaselines.get(Integer.toString(itemId));
	}

	synchronized void removeAccount(long accountHash)
	{
		if (data.histories.removeIf(h -> h.accountHash == accountHash))
		{
			dirty = true;
			saveAsync();
		}
	}

	private void saveAsync()
	{
		executor.execute(this::flushIfDirty);
	}

	/**
	 * @return {@code true} if there was unsaved history and it was written
	 */
	boolean flushIfDirty()
	{
		String json;
		synchronized (this)
		{
			if (!dirty)
			{
				return false;
			}
			json = serialiseLocked();
		}

		if (JsonFile.writeText(dataFile, json))
		{
			return true;
		}
		synchronized (this)
		{
			// Put it back so the next flush retries rather than dropping data.
			dirty = true;
		}
		return false;
	}

	/** Serialises the current state. Caller must hold the monitor. */
	private String serialiseLocked()
	{
		dirty = false;
		return gson.toJson(data);
	}


	private AccountHistory findOrCreate(long accountHash)
	{
		AccountHistory existing = historyFor(accountHash);
		if (existing != null)
		{
			return existing;
		}
		AccountHistory created = new AccountHistory(accountHash);
		data.histories.add(created);
		return created;
	}
}

package com.accountalmanac;

import java.awt.Color;
import net.runelite.client.ui.ColorScheme;

/**
 * Colour scheme for the standalone viewer window.
 *
 * <p>Applies to both the sidebar panel and the viewer window.
 *
 * <p>{@link #OSRS} is the default. {@link #RUNELITE} is kept first in the list
 * as the option that matches the client's other plugin panels exactly, for
 * anyone who wants the panel to disappear into its surroundings.
 *
 * <p>Public because it is a return type on the public
 * {@link AccountAlmanacConfig} interface, which RuneLite implements with a
 * dynamic proxy that cannot reach package-private types.
 */
public enum ViewerTheme
{
	/** The client's own palette - matches the sidebar and the rest of RuneLite. */
	RUNELITE("RuneLite dark",
		ColorScheme.DARK_GRAY_COLOR,
		ColorScheme.DARKER_GRAY_COLOR,
		ColorScheme.LIGHT_GRAY_COLOR,
		ColorScheme.MEDIUM_GRAY_COLOR,
		ColorScheme.BRAND_ORANGE),

	/** A warm off-white. Paper, not a lightbulb - a near-white background
	 *  glares under a dark table and washes out anything drawn pale. */
	LIGHT("Light",
		new Color(228, 225, 219),
		new Color(212, 208, 200),
		new Color(32, 30, 27),
		new Color(92, 87, 79),
		new Color(140, 94, 16)),

	MIDNIGHT("Midnight blue",
		new Color(14, 20, 32),
		new Color(22, 32, 48),
		new Color(219, 228, 240),
		new Color(129, 148, 173),
		new Color(90, 169, 230)),

	/** Parchment and dark wood, the palette the game's own interfaces use. */
	OSRS("Old School browns",
		new Color(62, 53, 41),
		new Color(42, 36, 28),
		new Color(240, 230, 210),
		new Color(184, 168, 135),
		new Color(255, 255, 0)),

	/** Near-black with crimson - the colour Zamorak's kit is trimmed in. */
	ZAMORAK("Zamorak red",
		new Color(24, 14, 14),
		new Color(38, 20, 20),
		new Color(238, 222, 222),
		new Color(163, 128, 128),
		new Color(214, 64, 64)),

	/** Deep forest and moss, for Guthix. */
	GUTHIX("Guthix green",
		new Color(20, 30, 22),
		new Color(28, 42, 31),
		new Color(226, 238, 226),
		new Color(134, 163, 138),
		new Color(106, 194, 112)),

	/**
	 * Saradomin's cape: a deep royal blue field with a silver star and trim.
	 * Blue-dominant, not white-dominant - an earlier version had it the wrong
	 * way round, and the one before that used gold, which is Armadyl's.
	 *
	 * <p>Headings take the star's pure white so they separate from body text,
	 * which sits a shade below it in blue-white.
	 */
	SARADOMIN("Saradomin blue",
		new Color(26, 44, 122),
		new Color(19, 33, 94),
		new Color(215, 222, 236),
		new Color(141, 158, 198),
		new Color(255, 255, 255));

	private final String label;
	private final Color background;
	private final Color altBackground;
	private final Color text;
	private final Color dimText;
	private final Color accent;

	ViewerTheme(String label, Color background, Color altBackground,
		Color text, Color dimText, Color accent)
	{
		this.label = label;
		this.background = background;
		this.altBackground = altBackground;
		this.text = text;
		this.dimText = dimText;
		this.accent = accent;
	}

	@Override
	public String toString()
	{
		return label;
	}

	Color background()
	{
		return background;
	}

	/** Table headers and secondary surfaces. */
	Color altBackground()
	{
		return altBackground;
	}

	Color text()
	{
		return text;
	}

	Color dimText()
	{
		return dimText;
	}

	Color accent()
	{
		return accent;
	}

	/**
	 * Row highlight. Derived from the background rather than hardcoded, so it
	 * stays a subtle shift on a light theme instead of the near-black that a
	 * fixed dark selection colour would give.
	 */
	Color selection()
	{
		boolean dark = luminance(background) < 0.5;
		return dark ? lighten(background, 0.18f) : darken(background, 0.10f);
	}

	/** Whether this theme is dark enough for the game's own stack colours. */
	boolean isDark()
	{
		return luminance(background) < 0.5;
	}

	/** Grid lines: just off the background, in whichever direction has room. */
	Color grid()
	{
		boolean dark = luminance(background) < 0.5;
		return dark ? lighten(background, 0.08f) : darken(background, 0.08f);
	}

	private static double luminance(Color c)
	{
		return (0.2126 * c.getRed() + 0.7152 * c.getGreen() + 0.0722 * c.getBlue()) / 255.0;
	}

	private static Color lighten(Color c, float amount)
	{
		return new Color(
			Math.min(255, Math.round(c.getRed() + 255 * amount)),
			Math.min(255, Math.round(c.getGreen() + 255 * amount)),
			Math.min(255, Math.round(c.getBlue() + 255 * amount)));
	}

	private static Color darken(Color c, float amount)
	{
		return new Color(
			Math.max(0, Math.round(c.getRed() - 255 * amount)),
			Math.max(0, Math.round(c.getGreen() - 255 * amount)),
			Math.max(0, Math.round(c.getBlue() - 255 * amount)));
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.List;

/**
 * Suggested values for {@link AccountRecord#category}, the user-assigned
 * grouping for an account.
 *
 * <p>The category is stored on the record as a plain string rather than as
 * this enum, for two reasons: a custom grouping the user types in has to work
 * without a code change, and an unrecognised value read back from an older or
 * hand-edited file has to survive rather than throw. This enum only supplies
 * the presets offered in the dropdown.
 *
 * <p><b>Banned and hidden are deliberately not categories here</b>, even
 * though both were listed alongside these. They are independent flags on the
 * record ({@link AccountRecord#banned}, {@link AccountRecord#hidden}) because
 * they describe state rather than kind: a pure can also be banned, and a main
 * can be hidden from totals while staying a main. Folding them into a
 * single-value category field would force a choice between those and lose
 * information. Both are still offered as groupings in the filter dropdown, so
 * "show me the banned ones" works exactly as expected - see
 * {@link AccountFilter}.
 */
enum AccountCategory
{
	UNSET(""),
	MAIN("Main"),
	IRONMAN("Ironman"),
	PURE("Pure"),
	ZERKER("Zerker"),
	LEVEL_3("Level 3"),
	SKILLER("Skiller"),
	MULE("Mule"),
	OTHER("Other");

	private final String label;

	AccountCategory(String label)
	{
		this.label = label;
	}

	String label()
	{
		return label;
	}

	@Override
	public String toString()
	{
		return label.isEmpty() ? "(none)" : label;
	}

	/** Preset labels for a dropdown, blank first so "no category" is selectable. */
	static List<String> presetLabels()
	{
		List<String> labels = new ArrayList<>();
		for (AccountCategory category : values())
		{
			labels.add(category.label);
		}
		return labels;
	}

	/**
	 * A sensible starting category for an account the user has not classified
	 * yet, inferred from the account type the client reported.
	 *
	 * <p>Only ironman variants are inferred. Whether an account is a pure, a
	 * zerker or a level 3 is a matter of build intent that no API reports -
	 * a level 3 skiller and a fresh account look identical - so those are
	 * left for the user rather than guessed wrongly.
	 */
	static String suggestFor(String accountType)
	{
		if (accountType == null || accountType.isEmpty())
		{
			return UNSET.label;
		}
		String upper = accountType.toUpperCase();
		if (upper.contains("IRONMAN"))
		{
			return IRONMAN.label;
		}
		return UNSET.label;
	}

	/** Trims and collapses a user-entered category, never returning null. */
	static String normalise(String raw)
	{
		return raw == null ? "" : raw.trim();
	}
}

package com.accountalmanac;

/**
 * An item's price at a moment, kept so price movement can be reported without
 * asking anything over the network.
 *
 * <p>{@code ItemManager} only ever exposes the current price - there is no
 * historical lookup - and the web viewer gets its 24 hour comparison from the
 * wiki's API. The plugin deliberately makes no network requests at all, so it
 * earns the same answer by remembering what it saw last time instead.
 */
class PricePoint
{
	int price;

	/** Local PC time this price was recorded, epoch millis. */
	long at;

	PricePoint()
	{
	}

	PricePoint(int price, long at)
	{
		this.price = price;
		this.at = at;
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.List;

/**
 * Root object persisted to {@code ge-events.json}, oldest event first.
 *
 * <p>Separate from both {@code accounts.json} and {@code history.json} for the
 * same reason those are separate from each other: this is the fastest-growing
 * of the three and the least costly to lose.
 */
class GeEventData
{
	int schemaVersion = 1;

	List<GeEvent> events = new ArrayList<>();

	void normalise()
	{
		if (events == null)
		{
			events = new ArrayList<>();
			return;
		}
		for (GeEvent event : events)
		{
			event.normalise();
		}
	}
}

package com.accountalmanac;

import java.util.HashMap;
import java.util.Map;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Lazily resolves item sprites for table cells.
 *
 * <p>{@link ItemManager#getImage} hands back an {@link AsyncBufferedImage}
 * that is blank until the sprite has been fetched and then fills itself in
 * place, so an {@link ImageIcon} wrapping one can be handed to a renderer
 * immediately - it simply starts empty and becomes correct.
 *
 * <p>The catch is that nothing repaints on its own. Each image gets an
 * {@code onLoaded} callback, and rather than repainting the table once per
 * sprite - hundreds of repaints for a large bank - the callbacks set a flag
 * that a single coalesced {@code repaint()} picks up.
 */
class ItemIconCache
{
	private final ItemManager itemManager;
	private final JComponent repaintTarget;
	/** Keyed by item id and stack size: the sprite changes with the amount. */
	private final Map<Long, ImageIcon> icons = new HashMap<>();

	private boolean repaintPending;

	/**
	 * @param itemManager   may be null, in which case every lookup misses and
	 *                      the tables simply render without sprites
	 * @param repaintTarget component repainted as sprites arrive
	 */
	ItemIconCache(ItemManager itemManager, JComponent repaintTarget)
	{
		this.itemManager = itemManager;
		this.repaintTarget = repaintTarget;
	}

	/**
	 * @return an icon for a single one of the item, possibly still blank, or
	 *         {@code null} if sprites are unavailable
	 */
	Icon get(int itemId)
	{
		return get(itemId, 1L);
	}

	/**
	 * @param quantity how many the row holds, which picks the stack sprite -
	 *                 a pile of coins rather than one coin, a bundle of arrows
	 *                 rather than one arrow
	 * @return an icon for the item, possibly still blank, or {@code null}
	 *         if sprites are unavailable
	 */
	Icon get(int itemId, long quantity)
	{
		if (itemManager == null || itemId <= 0)
		{
			return null;
		}

		// The client takes an int, and the sprite only changes at the game's
		// own stack thresholds, so clamping loses nothing.
		int stack = (int) Math.max(1L, Math.min(Integer.MAX_VALUE, quantity));
		long key = ((long) itemId << 32) | stack;

		ImageIcon cached = icons.get(key);
		if (cached != null)
		{
			return cached;
		}

		// stackable=false: every table carries its own quantity column, so
		// RuneLite must not draw its number over the sprite as well.
		AsyncBufferedImage image = itemManager.getImage(itemId, stack, false);
		ImageIcon icon = new ImageIcon(image);
		icons.put(key, icon);
		image.onLoaded(this::scheduleRepaint);
		return icon;
	}

	/**
	 * Collapses a burst of sprite loads into one repaint. onLoaded fires on
	 * the client thread, so the repaint itself is left to Swing.
	 */
	private synchronized void scheduleRepaint()
	{
		if (repaintPending)
		{
			return;
		}
		repaintPending = true;
		javax.swing.SwingUtilities.invokeLater(() ->
		{
			synchronized (this)
			{
				repaintPending = false;
			}
			repaintTarget.repaint();
		});
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * One tracked account, keyed by the client's account hash.
 *
 * <p>Everything here is plain text. An earlier revision kept AES-GCM
 * encrypted login credentials; that was removed in favour of
 * {@link #loginLabel}, a user-supplied nickname for identifying which
 * login an account belongs to. Credential-storing plugins are barred from
 * the plugin hub, and a label is all the tracker actually needs.
 */
class AccountRecord
{
	long accountHash;

	/** In-game display name, captured automatically on login. */
	String displayName = "";

	/**
	 * Account name as reported by the Jagex launcher, captured automatically.
	 *
	 * <p>Only ever the launcher's name. The client's own login-screen field is
	 * deliberately not read, because on the classic login flow it holds
	 * whatever was typed to log in - often an email address. Blank on a
	 * non-launcher login, and never guessed from the display name.
	 *
	 * <p>Files written before that change can still hold a value captured the
	 * old way. Nothing rewrites them, so an existing entry stays as it was
	 * until the account next logs in through the launcher.
	 */
	String loginName = "";

	/**
	 * User-editable label identifying the login this account sits under -
	 * an email alias, "main", "iron 3", whatever. Never a password.
	 */
	String loginLabel = "";

	/**
	 * {@code AccountType.name()} as reported by the client on login, e.g.
	 * {@code "IRONMAN"}. Empty until the account has logged in at least once
	 * under this feature. See {@link AccountTypeBadge} for display.
	 */
	String accountType = "";

	String note = "";

	/**
	 * User-assigned grouping - "Main", "Pure", "Zerker", or anything the user
	 * types. Stored as free text rather than an enum so a custom grouping
	 * needs no code change; see {@link AccountCategory} for the presets.
	 */
	String category = "";

	/**
	 * Excludes this account from wealth totals, item aggregates and stat
	 * rollups without deleting anything it has recorded.
	 *
	 * <p>The account stays fully visible in its own right and keeps updating
	 * on login - this only removes it from the cross-account numbers, which is
	 * the point: a mule counted twice, or a friend's account tracked for
	 * reference, distorts every total it appears in.
	 */
	boolean hidden;

	/**
	 * Marked as banned by the user.
	 *
	 * <p>Set manually. The client exposes no login-failure reason, and a
	 * rejected login never reaches a logged-in state, so there is nothing to
	 * detect it from automatically.
	 */
	boolean banned;

	/** When {@link #banned} was set, for the "recheck this" prompt. */
	long bannedAt;

	/**
	 * Time played, as reported by the game's own account summary.
	 *
	 * <p>Read from {@code VarbitID.ACCOUNT_SUMMARY_DISPLAY_PLAYTIME}, which
	 * is what the in-game Account Summary screen displays. The game does not
	 * document its unit; it is treated as minutes, which is what the displayed
	 * figure is consistent with. 0 means never captured - the varp is only
	 * populated once the account has loaded.
	 *
	 * <p>Not derived from session timing on purpose. Counting ticks would only
	 * ever measure time spent in this client, which is a different and much
	 * less interesting number than the account's actual lifetime.
	 */
	int playtimeMinutes;

	/**
	 * Quest points earned, as reported by the game.
	 *
	 * <p>Read from {@code VarPlayerID.QP}. 0 means either a genuinely
	 * questless account or one that has not logged in since this started
	 * being captured; {@link #questPointsMax} tells them apart, since it is
	 * only ever non-zero once a capture has happened.
	 */
	int questPoints;

	/**
	 * Quest points available in the game at the time of capture, from
	 * {@code VarbitID.QP_MAX}.
	 *
	 * <p>Stored per account rather than as one global constant because it
	 * rises with every quest release, and accounts are captured at different
	 * times. Showing a stale total beside a fresh one would be wrong in a way
	 * the user cannot see; keeping each account's own denominator means the
	 * fraction always reflects what the game said when that account was read.
	 */
	int questPointsMax;

	/**
	 * The counters the game's own Account Summary screen shows, each as
	 * done-out-of-total. Zero totals mean never captured, which is why every
	 * label below shows a dash rather than "0/0".
	 *
	 * <p>Quests and the collection log come from vars and so update on every
	 * login. Achievement diaries and combat tasks have no whole-account var -
	 * the game keeps them per region and per boss - so those two are read from
	 * the Account Summary screen when it is opened.
	 */
	int questsCompleted;
	int questsTotal;
	int achievementsCompleted;
	int achievementsTotal;
	int combatTasksCompleted;
	int combatTasksTotal;
	int collectionsLogged;
	int collectionsTotal;

	/** Total value of {@link #bankItems} as of {@link #lastUpdated}. */
	long bankValue;
	long lastUpdated;

	/**
	 * When this account was last logged into, set on every login regardless
	 * of whether the bank was ever opened. Kept separate from
	 * {@link #lastUpdated}, which only advances when a bank snapshot is
	 * taken - an account you log into but don't bank on would otherwise
	 * never move in a "most recent" sort, even though you were just on it.
	 */
	long lastLoginAt;

	// Skill.name() -> real (unboosted) level, e.g. "ATTACK" -> 75.
	Map<String, Integer> skillLevels = new HashMap<>();

	/**
	 * Skill.name() -> experience. Max XP is 200,000,000, which fits an int
	 * comfortably; the totals below still widen to long because 24 skills at
	 * the cap would overflow one.
	 */
	Map<String, Integer> skillXp = new HashMap<>();
	int combatLevel;
	long lastSnapshotAt;

	/**
	 * Last-seen bank contents. Only populated when the bank has actually
	 * been opened on this account - the client cannot read a closed bank.
	 * Empty means "never seen", which is distinct from a genuinely empty
	 * bank; check {@link #lastSnapshotAt} to tell them apart.
	 */
	List<BankItem> bankItems = new ArrayList<>();

	/** GE slots 0-7 as last reported. Includes empty slots. */
	List<GrandExchangeRecord> geOffers = new ArrayList<>();

	/** Gson leaves final/absent collections null on older files. */
	void normalise()
	{
		if (skillLevels == null)
		{
			skillLevels = new HashMap<>();
		}
		if (skillXp == null)
		{
			skillXp = new HashMap<>();
		}
		if (bankItems == null)
		{
			bankItems = new ArrayList<>();
		}
		else
		{
			// The game stores a bank placeholder as the item with a quantity
			// of zero. Nothing is actually held, so it is dropped here rather
			// than left for every view, export and count to remember.
			bankItems.removeIf(item -> item == null || item.quantity <= 0);
		}
		if (geOffers == null)
		{
			geOffers = new ArrayList<>();
		}
		if (displayName == null)
		{
			displayName = "";
		}
		if (loginLabel == null)
		{
			loginLabel = "";
		}
		if (loginName == null)
		{
			loginName = "";
		}
		if (accountType == null)
		{
			accountType = "";
		}
		if (note == null)
		{
			note = "";
		}
		if (category == null)
		{
			category = "";
		}
	}

	/**
	 * Whether this account contributes to cross-account totals.
	 *
	 * <p>Banned accounts still count by default - a banned account's bank is
	 * gone in practice, but the user marked it banned for their own
	 * bookkeeping and may still want the historical figure. Excluding it is a
	 * separate, explicit choice via {@link #hidden}.
	 */
	boolean countsTowardTotals()
	{
		return !hidden;
	}

	/**
	 * Grouping shown in the UI: the user's category, falling back to the
	 * ironman type the client reported, then to nothing.
	 */
	String categoryLabel()
	{
		if (category != null && !category.isEmpty())
		{
			return category;
		}
		String suggested = AccountCategory.suggestFor(accountType);
		return suggested.isEmpty() ? "" : suggested;
	}

	/** Coins tied up in outstanding GE offers. */
	long geValue()
	{
		long total = 0L;
		for (GrandExchangeRecord offer : geOffers)
		{
			total += offer.committedValue();
		}
		return total;
	}

	/** Bank value plus GE escrow - what the account is actually worth. */
	long totalWealth()
	{
		return bankValue + geValue();
	}

	/**
	 * Whether quest points have ever been read for this account.
	 *
	 * <p>Keyed on the maximum rather than the score, because a real account
	 * can sit on zero quest points indefinitely, while the maximum is never
	 * zero once the game has reported it.
	 */
	boolean hasQuestPoints()
	{
		return questPointsMax > 0;
	}

	/** Quest points as {@code earned/available}, or a dash when never captured. */
	String questPointsLabel()
	{
		return hasQuestPoints() ? questPoints + "/" + questPointsMax : "-";
	}

	/** {@code done/total}, or a dash when the total has never been read. */
	private static String fraction(int done, int total)
	{
		return total > 0 ? done + "/" + total : "-";
	}

	String questsLabel()
	{
		return fraction(questsCompleted, questsTotal);
	}

	String achievementsLabel()
	{
		return fraction(achievementsCompleted, achievementsTotal);
	}

	String combatTasksLabel()
	{
		return fraction(combatTasksCompleted, combatTasksTotal);
	}

	String collectionsLabel()
	{
		return fraction(collectionsLogged, collectionsTotal);
	}

	boolean hasBankSnapshot()
	{
		return lastSnapshotAt > 0L;
	}

	/** Stacks actually held. Placeholders sit at zero and do not count. */
	int bankStackCount()
	{
		int stacks = 0;
		for (BankItem item : bankItems)
		{
			if (item != null && item.quantity > 0)
			{
				stacks++;
			}
		}
		return stacks;
	}

	/** Most recent thing that happened to this account - a login or a bank snapshot, whichever is later. */
	long lastActivityAt()
	{
		return Math.max(lastLoginAt, lastUpdated);
	}

	/** Sum of every real skill level, the in-game "total level". */
	int totalLevel()
	{
		int total = 0;
		for (Integer level : skillLevels.values())
		{
			if (level != null)
			{
				total += level;
			}
		}
		return total;
	}

	/** Real level for a Skill.name(), or 0 if never seen. */
	int skillLevel(String skillName)
	{
		Integer level = skillLevels.get(skillName);
		return level == null ? 0 : level;
	}

	/** Experience for a Skill.name(), or 0 if never seen. */
	int skillXpFor(String skillName)
	{
		Integer xp = skillXp.get(skillName);
		return xp == null ? 0 : xp;
	}

	/** Sum of experience across every skill. */
	long totalXp()
	{
		long total = 0L;
		for (Integer xp : skillXp.values())
		{
			if (xp != null)
			{
				total += xp;
			}
		}
		return total;
	}

	/**
	 * The real name, always. This is the persistence-safe accessor: it is what
	 * gets written into logged Grand Exchange events, so it must never be
	 * masked or the user's own records would be corrupted by a display
	 * setting. UI code wants {@code NameMasker.display} instead.
	 */
	String label()
	{
		if (displayName != null && !displayName.isEmpty())
		{
			return displayName;
		}
		if (loginLabel != null && !loginLabel.isEmpty())
		{
			return loginLabel;
		}
		return "Account " + Long.toHexString(accountHash);
	}
}

package com.accountalmanac;

import java.awt.Color;

/**
 * Colours a Grand Exchange offer's progress bar by how far along it is.
 *
 * <p>Banded rather than a smooth gradient. A gradient looks better in
 * isolation but reads worse in a list: two offers eight percent apart get
 * near-identical colours, so the eye has to fall back to the number and the
 * colour earns nothing. Bands turn the bar into a status at a glance - barely
 * started, halfway, nearly there, done - which is the question being asked of
 * a screen full of offers.
 *
 * <p>The ramp runs red through amber to green, which is the convention every
 * progress bar already trains people on, and it ends on the game's own green
 * so a finished offer looks finished.
 *
 * <pre>
 *   0%          dull red      nothing has traded yet
 *   1 - 24%     burnt orange  just started
 *   25 - 49%    amber         moving
 *   50 - 89%    gold          past halfway
 *   90 - 99%    yellow-green  nearly there
 *   100%        green         complete, ready to collect
 * </pre>
 */
final class ProgressColours
{
	/** Nothing has traded. Distinct from "just started" on purpose. */
	private static final Color NONE = new Color(0x8E, 0x3B, 0x2E);
	private static final Color STARTED = new Color(0xB8, 0x5C, 0x2E);
	private static final Color QUARTER = new Color(0xC8, 0x91, 0x2A);
	private static final Color HALF = new Color(0xD8, 0xB2, 0x2A);
	private static final Color NEARLY = new Color(0x9B, 0xBF, 0x3A);
	/** The game's own green, so a finished offer matches the interface. */
	private static final Color DONE = new Color(0x3C, 0xA0, 0x3C);

	private ProgressColours()
	{
	}

	/**
	 * @param fraction 0.0 to 1.0; anything outside is clamped
	 * @return the band colour for that progress
	 */
	static Color forFraction(double fraction)
	{
		if (fraction >= 1.0)
		{
			return DONE;
		}
		if (fraction <= 0.0)
		{
			return NONE;
		}
		if (fraction >= 0.90)
		{
			return NEARLY;
		}
		if (fraction >= 0.50)
		{
			return HALF;
		}
		if (fraction >= 0.25)
		{
			return QUARTER;
		}
		return STARTED;
	}

	/**
	 * Text colour that stays legible on top of {@link #forFraction}.
	 *
	 * <p>The mid bands are bright enough that white text on them is hard work,
	 * so those get black instead. Picked per band rather than computed from
	 * luminance, because the bands are fixed and a formula would only be a
	 * less predictable way of reaching the same six answers.
	 */
	static Color textOn(double fraction)
	{
		if (fraction >= 1.0 || fraction <= 0.0)
		{
			return Color.WHITE;
		}
		return fraction >= 0.25 && fraction < 0.90 ? Color.BLACK : Color.WHITE;
	}
}

package com.accountalmanac;

import java.util.concurrent.TimeUnit;

/**
 * A look-back window for the Stats and Wealth split tabs.
 *
 * <p>A timeframe answers "what changed over this period", which needs a
 * baseline to subtract from the present. That baseline comes from
 * {@link AccountHistory}, so a window only produces numbers once history has
 * actually accumulated across it - a 1 year window on two days of history
 * reports the two days it has, and says so, rather than inventing a year.
 *
 * <p>Public because it is a return type on the public
 * {@link AccountAlmanacConfig} interface. RuneLite implements that interface
 * with a JDK dynamic proxy, which lives in a different runtime package - a
 * package-private return type is unreachable from it and throws
 * {@code IllegalAccessError} as the plugin starts, taking the whole plugin
 * down with it.
 */
public enum Timeframe
{
	SEVEN_DAYS("Past 7 days", 7),
	THIRTY_DAYS("Past month", 30),
	NINETY_DAYS("Past 90 days", 90),
	ONE_YEAR("Past year", 365),

	/**
	 * No window - compare against the earliest snapshot on record. Kept as the
	 * default because it is the only option that is meaningful on day one.
	 */
	ALL_TIME("All time", -1);

	private final String label;
	private final int days;

	Timeframe(String label, int days)
	{
		this.label = label;
		this.days = days;
	}

	String label()
	{
		return label;
	}

	@Override
	public String toString()
	{
		return label;
	}

	boolean isAllTime()
	{
		return days < 0;
	}

	/**
	 * Epoch millis at the start of this window, or 0 for {@link #ALL_TIME} so
	 * callers can treat "no cutoff" as "everything at or after zero" without
	 * a special case.
	 */
	long cutoffFrom(long now)
	{
		if (isAllTime())
		{
			return 0L;
		}
		return now - TimeUnit.DAYS.toMillis(days);
	}
}

