		int result = JOptionPane.showConfirmDialog(this, input,
			"Group for " + nameOf(record), JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);

		if (result == JOptionPane.OK_OPTION)
