package com.accountalmanac;

import java.awt.Color;

/**
 * Item stack quantities exactly as the game renders them.
 *
 * <pre>
 *   0 to 99,999                  yellow   precise      99999
 *   100,000 to 9,999,999         white    truncated K  100K, 9999K
 *   10,000,000 and above         green    truncated M  10M, 2147M
 * </pre>
 *
 * <p>Truncated, not rounded: 9,999,999 shows as {@code 9999K}, not
 * {@code 10000K}. That is what the game does, and rounding up across a
 * threshold would show a stack as having crossed a boundary it has not.
 *
 * <p>This is deliberately not routed through the user's number-format setting.
 * It is a reproduction of a fixed game convention - the colour is as much a
 * part of it as the digits - so it stays put while everything else follows the
 * chosen format. The exact figure is always available on the tooltip.
 */
final class StackFormat
{
	private static final long WHITE_FROM = 100_000L;
	private static final long GREEN_FROM = 10_000_000L;

	/** The game's own stack colours. */
	private static final Color YELLOW = new Color(255, 255, 0);
	private static final Color WHITE = new Color(255, 255, 255);
	private static final Color GREEN = new Color(0, 255, 0);

	// The game only ever draws these on a dark interface, so the three are
	// chosen for contrast against near-black. On a light theme yellow and
	// white are invisible - the same hues are used here, darkened until they
	// read against a pale background, so the tiers stay recognisable.
	private static final Color YELLOW_ON_LIGHT = new Color(122, 94, 0);
	private static final Color WHITE_ON_LIGHT = new Color(46, 46, 46);
	private static final Color GREEN_ON_LIGHT = new Color(11, 107, 11);

	private StackFormat()
	{
	}

	static String text(long amount)
	{
		if (amount < WHITE_FROM)
		{
			return Long.toString(amount);
		}
		if (amount < GREEN_FROM)
		{
			return (amount / 1_000L) + "K";
		}
		// The game's own range stops at int max. A cross-account total can pass
		// it, so this keeps counting in millions rather than breaking there -
		// the alternative would be a wrong number at exactly the point the
		// figure gets interesting.
		return (amount / 1_000_000L) + "M";
	}

	static Color colour(long amount)
	{
		return colour(amount, true);
	}

	/**
	 * @param onDark whether the colour will be drawn on a dark surface; false
	 *               swaps in the darkened variants so the text stays legible
	 */
	static Color colour(long amount, boolean onDark)
	{
		if (amount < WHITE_FROM)
		{
			return onDark ? YELLOW : YELLOW_ON_LIGHT;
		}
		if (amount < GREEN_FROM)
		{
			return onDark ? WHITE : WHITE_ON_LIGHT;
		}
		return onDark ? GREEN : GREEN_ON_LIGHT;
	}
}

package com.accountalmanac;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.TimeUnit;

/**
 * How long ago an account was last logged into, and how alarming that is.
 *
 * <p>Timestamps are recorded with {@code System.currentTimeMillis()} and
 * rendered through the JVM's default zone, so the date and time shown are the
 * PC's own local clock rather than UTC or a game-server time.
 */
final class LoginAge
{
	/** e.g. {@code "2026-09-03 18:49"} - sortable as text, unambiguous. */
	private static final DateTimeFormatter EXACT =
		DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");

	/** e.g. {@code "Wed 3 Sep 2026, 6:49 PM"} - for the prominent header. */
	private static final DateTimeFormatter FRIENDLY =
		DateTimeFormatter.ofPattern("EEE d MMM yyyy, h:mm a");

	private LoginAge()
	{
	}

	/**
	 * Severity of an account's login age. Thresholds are configurable; these
	 * names describe the role, not a fixed day count.
	 */
	enum Status
	{
		/** Never logged in under this tracker - no date to age against. */
		NEVER,
		/** Within the fresh window. */
		FRESH,
		/** Past the warning threshold. */
		WARNING,
		/** Past the stale threshold. */
		STALE
	}

	/**
	 * Whole days elapsed since {@code epochMillis}, or -1 if it is unset.
	 *
	 * <p>Deliberately floor division on elapsed milliseconds rather than a
	 * calendar-day difference: "6 days" here means a full 144 hours have
	 * passed, which is what a staleness threshold should mean. A calendar
	 * difference would call 11pm yesterday to 1am today "1 day".
	 */
	static long daysSince(long epochMillis, long now)
	{
		if (epochMillis <= 0L)
		{
			return -1L;
		}
		long elapsed = now - epochMillis;
		if (elapsed < 0L)
		{
			// Clock moved backwards, or a file written on a machine ahead of
			// this one. Treat as "today" rather than reporting negative days.
			return 0L;
		}
		return TimeUnit.MILLISECONDS.toDays(elapsed);
	}

	/**
	 * @param warnAfterDays  first day that counts as a warning (default 7)
	 * @param staleAfterDays first day that counts as stale (default 12)
	 */
	static Status statusOf(long epochMillis, long now, int warnAfterDays, int staleAfterDays)
	{
		long days = daysSince(epochMillis, now);
		if (days < 0L)
		{
			return Status.NEVER;
		}
		if (days >= staleAfterDays)
		{
			return Status.STALE;
		}
		if (days >= warnAfterDays)
		{
			return Status.WARNING;
		}
		return Status.FRESH;
	}

	/**
	 * The user's chosen date style, or {@code "never"} when unset.
	 *
	 * <p>Set by {@link #applyConfig}. Held statically for the same reason the
	 * number formats are - threading a formatter through every renderer and
	 * table model is a wide change in service of one setting.
	 */
	private static volatile DateFormatMode mode = DateFormatMode.ISO;

	static void applyConfig(AccountAlmanacConfig config)
	{
		if (config != null && config.dateFormat() != null)
		{
			mode = config.dateFormat();
		}
	}

	/** A timestamp in the user's chosen style, or {@code "never"} when unset. */
	static String exact(long epochMillis)
	{
		return mode.format(epochMillis);
	}

	/** Always {@code "2026-09-03 18:49"}, whatever the setting - for tooltips. */
	static String iso(long epochMillis)
	{
		if (epochMillis <= 0L)
		{
			return "never";
		}
		return EXACT.format(local(epochMillis));
	}

	/** {@code "Wed 3 Sep 2026, 6:49 PM"}, or {@code "never"} when unset. */
	static String friendly(long epochMillis)
	{
		if (epochMillis <= 0L)
		{
			return "never";
		}
		return FRIENDLY.format(local(epochMillis));
	}

	/** {@code "3 days ago"} / {@code "today"} / {@code "never"}. */
	static String describeAge(long epochMillis, long now)
	{
		long days = daysSince(epochMillis, now);
		if (days < 0L)
		{
			return "never";
		}
		if (days == 0L)
		{
			return "today";
		}
		if (days == 1L)
		{
			return "yesterday";
		}
		return days + " days ago";
	}

	private static LocalDateTime local(long epochMillis)
	{
		return LocalDateTime.ofInstant(Instant.ofEpochMilli(epochMillis), ZoneId.systemDefault());
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Computes "what changed over this window" from stored snapshots.
 *
 * <h2>Partial windows are reported, not faked</h2>
 *
 * <p>A 1 year window asked for on two weeks of history cannot be answered.
 * Two responses would be wrong: reporting zero change (implying nothing
 * happened all year), or silently measuring from the oldest snapshot and
 * labelling it "past year" (implying a year of data exists).
 *
 * <p>So a {@link Change} carries {@link Change#covered} and
 * {@link Change#baselineAt}: the numbers are measured from the oldest snapshot
 * available, and the UI is told the window is only partially covered along with
 * the date actually being measured from. History accumulates from the moment V2
 * first runs, so the longer windows fill in over time.
 */
final class TimeframeStats
{
	private TimeframeStats()
	{
	}

	/** A before-and-after comparison for one account, or a whole roster. */
	static class Change
	{
		/** Timestamp actually measured from, 0 when there is no history at all. */
		long baselineAt;

		/**
		 * {@code true} when history reaches the full requested window. When
		 * {@code false} the deltas are still real, but they cover less time
		 * than the window's label claims.
		 */
		boolean covered;

		/** {@code true} when there is no usable baseline and every delta is 0. */
		boolean empty = true;

		long baselineWealth;
		long currentWealth;

		long baselineXp;
		long currentXp;

		int baselineTotalLevel;
		int currentTotalLevel;

		long wealthDelta()
		{
			return currentWealth - baselineWealth;
		}

		/** Percentage wealth change, or 0 when there was nothing to grow from. */
		double wealthPercent()
		{
			if (baselineWealth <= 0L)
			{
				return 0.0;
			}
			return 100.0 * (currentWealth - baselineWealth) / (double) baselineWealth;
		}
	}

	/**
	 * Compares one account against its own history.
	 *
	 * @param history may be {@code null} for an account with no snapshots yet
	 */
	static Change forAccount(AccountRecord record, AccountHistory history, Timeframe timeframe, long now)
	{
		Change change = new Change();
		change.currentWealth = record.totalWealth();
		change.currentXp = record.totalXp();
		change.currentTotalLevel = record.totalLevel();

		if (history == null || history.isEmpty())
		{
			// No history: baseline is the present, so every delta is zero.
			change.baselineWealth = change.currentWealth;
			change.baselineXp = change.currentXp;
			change.baselineTotalLevel = change.currentTotalLevel;
			return change;
		}

		HistorySnapshot baseline = history.baselineFor(timeframe, now);
		boolean covered = baseline != null;
		if (baseline == null)
		{
			// History exists but does not reach back far enough. Measure from
			// the oldest point available and mark the window as partial.
			baseline = history.earliest();
		}

		if (baseline == null)
		{
			change.baselineWealth = change.currentWealth;
			change.baselineXp = change.currentXp;
			change.baselineTotalLevel = change.currentTotalLevel;
			return change;
		}

		change.empty = false;
		change.covered = covered;
		change.baselineAt = baseline.at;
		change.baselineWealth = baseline.totalWealth();
		change.baselineXp = baseline.totalXp;
		change.baselineTotalLevel = baseline.totalLevel;
		return change;
	}

	/**
	 * Sums a whole roster into one comparison. Covered is {@code true} only if
	 * every contributing account reaches the window - one short history makes
	 * the roster total partial, and saying otherwise would overstate it.
	 */
	static Change forRoster(
		List<AccountRecord> accounts,
		Map<Long, AccountHistory> histories,
		Timeframe timeframe,
		long now)
	{
		Change total = new Change();
		total.covered = true;
		boolean anyBaseline = false;
		long earliestBaseline = 0L;

		for (AccountRecord record : accounts)
		{
			Change one = forAccount(record, histories.get(record.accountHash), timeframe, now);

			total.currentWealth += one.currentWealth;
			total.currentXp += one.currentXp;
			total.currentTotalLevel += one.currentTotalLevel;
			total.baselineWealth += one.baselineWealth;
			total.baselineXp += one.baselineXp;
			total.baselineTotalLevel += one.baselineTotalLevel;

			if (!one.empty)
			{
				anyBaseline = true;
				if (!one.covered)
				{
					total.covered = false;
				}
				if (earliestBaseline == 0L || one.baselineAt < earliestBaseline)
				{
					earliestBaseline = one.baselineAt;
				}
			}
		}

		total.empty = !anyBaseline;
		total.baselineAt = earliestBaseline;
		if (!anyBaseline)
		{
			total.covered = false;
		}
		return total;
	}

	/**
	 * Experience gained per skill for one account over the window. Skills with
	 * no gain are still present with a zero value, so the caller can render a
	 * full skill list without deciding what a missing key means.
	 */
	static Map<String, Long> skillXpDeltas(
		AccountRecord record, AccountHistory history, Timeframe timeframe, long now)
	{
		Map<String, Long> deltas = new HashMap<>();
		HistorySnapshot baseline = history == null
			? null
			: firstAvailableBaseline(history, timeframe, now);

		for (String skill : SkillOrder.names())
		{
			int current = record.skillXpFor(skill);
			int before = baseline == null ? current : baseline.skillXpFor(skill);
			// A baseline that predates a skill being observed reads as 0, which
			// would report the account's entire lifetime XP as a gain. Clamp to
			// zero rather than inventing progress that was not measured.
			long delta = before <= 0 ? 0L : current - before;
			deltas.put(skill, Math.max(0L, delta));
		}
		return deltas;
	}

	private static HistorySnapshot firstAvailableBaseline(
		AccountHistory history, Timeframe timeframe, long now)
	{
		HistorySnapshot baseline = history.baselineFor(timeframe, now);
		return baseline != null ? baseline : history.earliest();
	}

	/**
	 * Per-account wealth changes over the window, biggest gain first. Drives
	 * the timeframe-aware wealth split and the movers on the Interesting tab.
	 */
	static List<AccountChange> rankByWealthChange(
		List<AccountRecord> accounts,
		Map<Long, AccountHistory> histories,
		Timeframe timeframe,
		long now)
	{
		List<AccountChange> ranked = new ArrayList<>();
		for (AccountRecord record : accounts)
		{
			Change change = forAccount(record, histories.get(record.accountHash), timeframe, now);
			ranked.add(new AccountChange(record, change));
		}
		ranked.sort((a, b) -> Long.compare(b.change.wealthDelta(), a.change.wealthDelta()));
		return ranked;
	}

	/** One account paired with its change over a window. */
	static class AccountChange
	{
		final AccountRecord record;
		final Change change;

		AccountChange(AccountRecord record, Change change)
		{
			this.record = record;
			this.change = change;
		}
	}

	/** Convenience: account hash to history, for the roster-wide calls above. */
	static Map<Long, AccountHistory> index(List<AccountHistory> histories)
	{
		Map<Long, AccountHistory> byHash = new HashMap<>();
		for (AccountHistory history : histories)
		{
			byHash.put(history.accountHash, history);
		}
		return byHash;
	}
}

package com.accountalmanac;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.TexturePaint;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.IntFunction;
import net.runelite.client.ui.FontManager;

/**
 * Renders a stored bank snapshot as an image styled after the in-game bank.
 *
 * <p>Drawn from the stored snapshot rather than captured from the live bank
 * widget. The plugin exists for the accounts you are not logged into, and a
 * widget capture can only ever photograph the one in front of you. Working
 * from stored data also lets the grid be ordered and filtered however the user
 * asks, which the game's own bank cannot do.
 *
 * <p>The frame is the game's own: the steel border corners and edges and the
 * bank tab sprites are fetched from the client's sprite cache and tiled here,
 * so the window is the real one rather than an impression of it. When a sprite
 * has not loaded - or there is no client at all - each piece falls back to a
 * drawn bevel, so the export still works and simply looks plainer.
 *
 * <p>Everything else is plain drawing with no client access and no IO, so it
 * is safe on the Swing thread.
 */
final class BankScreenshot
{
	/** Sprite ids for the pieces of the game's own window frame. */
	static final int SPRITE_CORNER_TL = 310;
	static final int SPRITE_CORNER_TR = 311;
	static final int SPRITE_CORNER_BL = 312;
	static final int SPRITE_CORNER_BR = 313;
	static final int SPRITE_EDGE_TOP = 314;
	static final int SPRITE_EDGE_SIDE = 315;
	static final int SPRITE_TAB = 1077;
	static final int SPRITE_TAB_SELECTED = 1079;
	static final int SPRITE_TAB_ICON_ALL = 1081;

	/** Every sprite this renderer asks for, so callers can prefetch them. */
	static int[] framePieces()
	{
		return new int[]{
			SPRITE_CORNER_TL, SPRITE_CORNER_TR, SPRITE_CORNER_BL, SPRITE_CORNER_BR,
			SPRITE_EDGE_TOP, SPRITE_EDGE_SIDE,
			SPRITE_TAB, SPRITE_TAB_SELECTED, SPRITE_TAB_ICON_ALL,
		};
	}

	/**
	 * One drawn slot, the item in it, and what to say when hovered.
	 *
	 * <p>The tooltip is supplied by whichever renderer built the slot rather
	 * than derived from the item here. A bank slot wants the name and stack;
	 * a Grand Exchange slot wants the account and the offer's progress, which
	 * the item alone cannot answer.
	 */
	static final class Slot
	{
		final Rectangle bounds;
		final BankItem item;
		final String tooltip;

		Slot(Rectangle bounds, BankItem item, String tooltip)
		{
			this.bounds = bounds;
			this.item = item;
			this.tooltip = tooltip;
		}
	}

	/**
	 * A finished image together with where each item was drawn.
	 *
	 * <p>The slot map is returned rather than recomputed by the caller because
	 * only the renderer knows the column count it settled on - recalculating it
	 * outside would be a second implementation of the same layout, free to
	 * drift out of step with this one.
	 */
	static final class Rendered
	{
		final BufferedImage image;
		final List<Slot> slots;

		Rendered(BufferedImage image, List<Slot> slots)
		{
			this.image = image;
			this.slots = slots;
		}

		/** The slot drawn at a point, or null if the point is not on one. */
		Slot slotAt(int x, int y)
		{
			for (Slot slot : slots)
			{
				if (slot.bounds.contains(x, y))
				{
					return slot;
				}
			}
			return null;
		}

		/** What to show when hovering a point, or null off any slot. */
		String tooltipAt(int x, int y)
		{
			Slot slot = slotAt(x, y);
			return slot == null ? null : slot.tooltip;
		}
	}

	/** How the grid is ordered. */
	enum Sort
	{
		VALUE("Stack value, high to low"),
		QUANTITY("Stack size, high to low"),
		ALCH("Alch value, high to low"),
		NAME("Name, A to Z");

		private final String label;

		Sort(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}

		Comparator<BankItem> comparator()
		{
			switch (this)
			{
				case QUANTITY:
					return Comparator.comparingLong((BankItem i) -> i.quantity).reversed();
				case ALCH:
					return Comparator.comparingLong(BankItem::totalHaValue).reversed();
				case NAME:
					return Comparator.comparing(i -> i.name == null ? "" : i.name,
						String.CASE_INSENSITIVE_ORDER);
				case VALUE:
				default:
					return Comparator.comparingLong(BankItem::totalValue).reversed();
			}
		}
	}

	/** Smallest stack size worth drawing. */
	enum MinQuantity
	{
		ANY("Any quantity", 0),
		TEN("10 or more", 10),
		FIFTY("50 or more", 50),
		HUNDRED("100 or more", 100),
		THOUSAND("1,000 or more", 1_000),
		K5("5,000 or more", 5_000),
		K10("10,000 or more", 10_000),
		K50("50,000 or more", 50_000);

		final String label;
		final int floor;

		MinQuantity(String label, int floor)
		{
			this.label = label;
			this.floor = floor;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** Smallest stack value worth drawing. */
	enum MinValue
	{
		ANY("Any value", 0L),
		K10("10K or more", 10_000L),
		K50("50K or more", 50_000L),
		K100("100K or more", 100_000L),
		M1("1M or more", 1_000_000L),
		M10("10M or more", 10_000_000L);

		final String label;
		final long floor;

		MinValue(String label, long floor)
		{
			this.label = label;
			this.floor = floor;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** Members-only, free-to-play, or both. */
	enum Membership
	{
		ANY("All items"),
		FREE("Free-to-play"),
		MEMBERS("Members only");

		final String label;

		Membership(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}

		/**
		 * An item with no captured flag passes either way.
		 *
		 * <p>Unknown is not evidence of either answer, and hiding those items
		 * would understate both sides. A price refresh fills the flag in.
		 */
		boolean accepts(Boolean members)
		{
			if (this == ANY || members == null)
			{
				return true;
			}
			return this == MEMBERS ? members : !members;
		}
	}

	// The game's slots are 36 x 32. The column count is not fixed at the
	// game's eight, because a roster-wide bank at eight across is a tall
	// ribbon that no viewer can zoom usefully.
	private static final int SLOT_W = 36;
	private static final int SLOT_H = 32;
	private static final int MIN_COLS = 8;
	private static final int MAX_COLS = 30;

	// The steel frame's own thickness, and the chrome inside it.
	private static final int EDGE = 8;
	private static final int PAD = 6;
	private static final int TITLE_H = 22;
	private static final int INFO_H = 16;
	private static final int TAB_H = 36;
	private static final int FOOT_H = 20;

	static final Color STONE = new Color(0x3E, 0x35, 0x29);
	static final Color WELL = new Color(0x33, 0x2C, 0x22);
	static final Color BEVEL_HI = new Color(0x6B, 0x60, 0x4E);
	static final Color BEVEL_LO = new Color(0x1E, 0x1A, 0x13);
	static final Color ORANGE = new Color(0xFF, 0x98, 0x1F);
	static final Color PARCHMENT = new Color(0xDC, 0xCF, 0xA8);

	private static final String DOT = "  -  ";

	private BankScreenshot()
	{
	}

	/**
	 * Keeps an item when it clears <em>either</em> threshold.
	 *
	 * <p>Either, not both, on purpose. A quantity floor is there to sweep out
	 * the single leftovers, but applied alone it would also throw away the one
	 * item that matters most - a party hat is a stack of one. Letting a high
	 * value rescue a small stack is what makes the quantity filter safe to use.
	 */
	static boolean keeps(BankItem item, MinQuantity minQuantity, MinValue minValue,
		Membership membership)
	{
		if (item == null || item.quantity <= 0)
		{
			return false;
		}
		if (!membership.accepts(item.members))
		{
			return false;
		}
		if (minQuantity.floor == 0 && minValue.floor == 0L)
		{
			return true;
		}
		boolean byQuantity = minQuantity.floor > 0 && item.quantity >= minQuantity.floor;
		boolean byValue = minValue.floor > 0L && item.totalValue() >= minValue.floor;
		return byQuantity || byValue;
	}

	/**
	 * Columns that keep the picture roughly landscape.
	 *
	 * <p>Eight across is the game's width and fine for one bank, but a
	 * roster-wide export at eight is a column of items thousands of pixels
	 * tall: it cannot be zoomed to read, and most of the screen is wasted.
	 */
	static int autoColumns(int itemCount)
	{
		if (itemCount <= MIN_COLS)
		{
			return MIN_COLS;
		}
		double target = Math.sqrt(itemCount * 1.5d * SLOT_H / SLOT_W);
		int cols = (int) Math.ceil(target);
		return Math.max(MIN_COLS, Math.min(MAX_COLS, cols));
	}

	/**
	 * @param title       heading, normally the account's display name
	 * @param items       the snapshot to draw; not modified
	 * @param sort        ordering applied before the grid is laid out
	 * @param icons       item id to sprite, may return null
	 * @param subtitle    footer note, e.g. when the bank was last seen
	 * @param minQuantity smallest stack size drawn
	 * @param minValue    smallest stack value drawn
	 * @param membership  members-only, free-to-play, or both
	 * @param columns     grid width, or 0 to size it automatically
	 * @param frame       sprite id to the game's frame piece, may return null
	 */
	static Rendered render(String title, List<BankItem> items, Sort sort,
		IntFunction<Image> icons, String subtitle,
		MinQuantity minQuantity, MinValue minValue, Membership membership, int columns,
		IntFunction<BufferedImage> frame)
	{
		List<BankItem> ordered = new ArrayList<>();
		long hiddenValue = 0L;
		int hidden = 0;
		for (BankItem item : items)
		{
			if (item == null || item.quantity <= 0)
			{
				continue;
			}
			if (keeps(item, minQuantity, minValue, membership))
			{
				ordered.add(item);
			}
			else
			{
				hidden++;
				hiddenValue += item.totalValue();
			}
		}
		ordered.sort(sort.comparator());

		int cols = columns > 0 ? columns : autoColumns(ordered.size());
		int rows = Math.max(1, (ordered.size() + cols - 1) / cols);
		int gridW = cols * SLOT_W;
		int gridH = rows * SLOT_H;

		int width = EDGE * 2 + PAD * 2 + gridW;
		int chromeTop = TITLE_H + INFO_H + TAB_H;
		int height = EDGE * 2 + chromeTop + gridH + FOOT_H + PAD;

		long totalValue = 0L;
		for (BankItem item : ordered)
		{
			totalValue += item.totalValue();
		}

		List<Slot> slots = new ArrayList<>(ordered.size());
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		try
		{
			// The game does not antialias its text, and switching it on makes
			// the RuneScape faces look smeared rather than smooth.
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);

			stone(g, width, height);
			steelFrame(g, width, height, frame);

			Font rsBold = FontManager.getRunescapeBoldFont();
			Font rsSmall = FontManager.getRunescapeSmallFont();

			String heading = title == null || title.isEmpty() ? "Bank" : title;
			g.setFont(rsBold);
			int tw = g.getFontMetrics().stringWidth(heading);
			shadowed(g, heading, (width - tw) / 2, EDGE + 15, ORANGE);

			g.setFont(rsSmall);
			String info = Format.exact(ordered.size()) + " items" + DOT
				+ Format.exact(totalValue) + " gp";
			int iw = g.getFontMetrics().stringWidth(info);
			shadowed(g, info, (width - iw) / 2, EDGE + TITLE_H + 11, PARCHMENT);

			int gx = EDGE + PAD;
			int tabsY = EDGE + TITLE_H + INFO_H;
			tabStrip(g, gx, tabsY, gridW, frame);

			int gy = tabsY + TAB_H;
			g.setColor(WELL);
			g.fillRect(gx, gy, gridW, gridH);

			for (int i = 0; i < ordered.size(); i++)
			{
				BankItem item = ordered.get(i);
				int sx = gx + (i % cols) * SLOT_W;
				int sy = gy + (i / cols) * SLOT_H;
				// The drawn stack number is truncated the way the game truncates
				// it, so the exact figure is only available on hover.
				slots.add(new Slot(new Rectangle(sx, sy, SLOT_W, SLOT_H), item,
					item.name + "  x" + Format.exact(item.quantity)
						+ "  (" + Format.gp(item.totalValue()) + ")"));

				Image sprite = icons == null ? null : icons.apply(item.id);
				if (sprite != null)
				{
					int w = sprite.getWidth(null);
					int h = sprite.getHeight(null);
					// An unloaded sprite reports -1; centring on the nominal
					// size is harmless and it fills in on the next render.
					int dx = sx + (SLOT_W - (w > 0 ? w : SLOT_W)) / 2;
					int dy = sy + (SLOT_H - (h > 0 ? h : SLOT_H)) / 2;
					g.drawImage(sprite, dx, dy, null);
				}

				g.setFont(rsSmall);
				shadowed(g, StackFormat.text(item.quantity), sx + 1, sy + 10,
					StackFormat.colour(item.quantity));
			}

			g.setFont(rsSmall);
			StringBuilder foot = new StringBuilder("Sorted by ").append(sort);
			if (hidden > 0)
			{
				// What was left out is stated rather than silently dropped - an
				// export that quietly omits things is worse than a longer one.
				foot.append(DOT).append(Format.exact(hidden)).append(" hidden (")
					.append(Format.gp(hiddenValue)).append(')');
			}
			if (subtitle != null && !subtitle.isEmpty())
			{
				foot.append(DOT).append(subtitle);
			}
			shadowed(g, foot.toString(), gx, gy + gridH + 14, PARCHMENT);
		}
		finally
		{
			g.dispose();
		}
		return new Rendered(image, slots);
	}

	/**
	 * The game's steel window frame: four corner sprites with the edge sprites
	 * tiled between them.
	 *
	 * <p>The side edge sprite is drawn rotated for the left-hand run, which is
	 * what the interface itself does - the cache carries one edge per axis,
	 * not one per side.
	 */
	static void steelFrame(Graphics2D g, int width, int height,
		IntFunction<BufferedImage> frame)
	{
		BufferedImage tl = sprite(frame, SPRITE_CORNER_TL);
		BufferedImage tr = sprite(frame, SPRITE_CORNER_TR);
		BufferedImage bl = sprite(frame, SPRITE_CORNER_BL);
		BufferedImage br = sprite(frame, SPRITE_CORNER_BR);
		BufferedImage top = sprite(frame, SPRITE_EDGE_TOP);
		BufferedImage side = sprite(frame, SPRITE_EDGE_SIDE);

		if (tl == null || top == null || side == null)
		{
			// No sprite cache available - fall back to a drawn bevel so the
			// export still frames itself.
			bevel(g, 0, 0, width, height, true);
			bevel(g, 1, 1, width - 2, height - 2, true);
			return;
		}

		int cw = tl.getWidth();
		int ch = tl.getHeight();

		Graphics2D h = (Graphics2D) g.create();
		try
		{
			h.setPaint(new TexturePaint(top, new Rectangle(0, 0, top.getWidth(), top.getHeight())));
			h.fillRect(cw, 0, Math.max(0, width - cw * 2), top.getHeight());
			h.fillRect(cw, height - top.getHeight(), Math.max(0, width - cw * 2), top.getHeight());
		}
		finally
		{
			h.dispose();
		}

		Graphics2D v = (Graphics2D) g.create();
		try
		{
			v.setPaint(new TexturePaint(side, new Rectangle(0, 0, side.getWidth(), side.getHeight())));
			v.fillRect(0, ch, side.getWidth(), Math.max(0, height - ch * 2));
			v.fillRect(width - side.getWidth(), ch, side.getWidth(), Math.max(0, height - ch * 2));
		}
		finally
		{
			v.dispose();
		}

		g.drawImage(tl, 0, 0, null);
		if (tr != null)
		{
			g.drawImage(tr, width - tr.getWidth(), 0, null);
		}
		if (bl != null)
		{
			g.drawImage(bl, 0, height - bl.getHeight(), null);
		}
		if (br != null)
		{
			g.drawImage(br, width - br.getWidth(), height - br.getHeight(), null);
		}
	}

	/** The row of tab buttons above the bank's item area. */
	private static void tabStrip(Graphics2D g, int x, int y, int w,
		IntFunction<BufferedImage> frame)
	{
		BufferedImage tab = sprite(frame, SPRITE_TAB);
		BufferedImage selected = sprite(frame, SPRITE_TAB_SELECTED);
		BufferedImage icon = sprite(frame, SPRITE_TAB_ICON_ALL);

		if (tab == null)
		{
			g.setColor(BEVEL_LO);
			g.drawLine(x, y + TAB_H - 2, x + w - 1, y + TAB_H - 2);
			return;
		}

		int tabW = tab.getWidth();
		int count = Math.max(1, Math.min(10, w / tabW));
		for (int i = 0; i < count; i++)
		{
			BufferedImage face = i == 0 && selected != null ? selected : tab;
			int tx = x + i * tabW;
			g.drawImage(face, tx, y + (TAB_H - face.getHeight()), null);
			if (i == 0 && icon != null)
			{
				g.drawImage(icon,
					tx + (tabW - icon.getWidth()) / 2,
					y + TAB_H - face.getHeight() + (face.getHeight() - icon.getHeight()) / 2,
					null);
			}
		}
	}

	private static BufferedImage sprite(IntFunction<BufferedImage> frame, int id)
	{
		return frame == null ? null : frame.apply(id);
	}

	/**
	 * The interface's stone ground, behind the frame.
	 *
	 * <p>Generated from the pixel coordinates rather than a random source, so
	 * two renders of the same bank produce byte-identical images - which
	 * matters if anyone diffs or dedupes them. Written into a raster in one
	 * pass rather than as a million one-pixel fills, which on a large bank is
	 * the difference between instant and visibly slow.
	 */
	static void stone(Graphics2D g, int width, int height)
	{
		BufferedImage tile = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				int n = ((x * 73856093) ^ (y * 19349663)) >>> 8;
				int d = (n % 11) - 5;
				int rgb = (clamp(STONE.getRed() + d) << 16)
					| (clamp(STONE.getGreen() + d) << 8)
					| clamp(STONE.getBlue() + d);
				tile.setRGB(x, y, rgb);
			}
		}
		g.drawImage(tile, 0, 0, null);
	}

	/** A RuneScape interface bevel: lit from the top-left, or sunken. */
	static void bevel(Graphics2D g, int x, int y, int w, int h, boolean raised)
	{
		g.setColor(raised ? BEVEL_HI : BEVEL_LO);
		g.drawLine(x, y, x + w - 1, y);
		g.drawLine(x, y, x, y + h - 1);
		g.setColor(raised ? BEVEL_LO : BEVEL_HI);
		g.drawLine(x + w - 1, y, x + w - 1, y + h - 1);
		g.drawLine(x, y + h - 1, x + w - 1, y + h - 1);
	}

	/** Game text is drawn with a hard black shadow one pixel down and right. */
	static void shadowed(Graphics2D g, String text, int x, int y, Color colour)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(colour);
		g.drawString(text, x, y);
	}

	private static int clamp(int v)
	{
		return v < 0 ? 0 : Math.min(v, 255);
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Rolls every account's bank snapshot up into a single cross-account view:
 * one {@link ItemTotal} per distinct item, carrying the per-account split
 * that the pie charts render.
 *
 * <p>Pure computation over already-loaded records - no client access, no IO -
 * so it is safe to call straight from the Swing thread.
 */
final class ItemAggregator
{
	private ItemAggregator()
	{
	}

	/**
	 * One item summed across every account that holds it.
	 */
	static class ItemTotal
	{
		final int itemId;
		final String name;
		long totalQuantity;
		long totalValue;
		int unitPrice;

		/** Members-only, or null when no holder has recorded it yet. */
		Boolean members;

		/** Account hash to quantity held, only for accounts holding it. */
		final Map<Long, Long> byAccount = new LinkedHashMap<>();

		ItemTotal(int itemId, String name)
		{
			this.itemId = itemId;
			this.name = name;
		}

		int accountCount()
		{
			return byAccount.size();
		}
	}

	/**
	 * Aggregates every item across the supplied accounts, ordered by total
	 * value descending - the order the "all items" table renders in.
	 *
	 * <p>Accounts with no bank snapshot contribute nothing; they are not an
	 * empty bank, just an unseen one.
	 *
	 * <p>Also folds in the unsold remainder of every active <b>sell</b>
	 * offer - those items have left the bank container entirely (that is
	 * why the bank event does not see them), but they are still the
	 * account's items, just parked in GE escrow rather than sold. A
	 * <b>buy</b> offer is the opposite case and is deliberately excluded:
	 * the coins are already counted via {@link AccountRecord#geValue()},
	 * but the item itself has not been acquired yet, so counting it here
	 * would claim ownership of something not yet owned.
	 */
	static List<ItemTotal> aggregate(List<AccountRecord> accounts)
	{
		Map<Integer, ItemTotal> byId = new LinkedHashMap<>();

		for (AccountRecord record : accounts)
		{
			for (BankItem item : record.bankItems)
			{
				if (item.quantity <= 0)
				{
					continue;
				}

				ItemTotal total = byId.computeIfAbsent(item.id,
					id -> new ItemTotal(id, item.name == null ? "" : item.name));

				total.totalQuantity += item.quantity;
				total.totalValue += item.totalValue();
				// Snapshots are taken at different times, so unit prices can
				// disagree between accounts. The most recently seen price
				// wins, which is what "Refresh prices" converges everything to.
				total.unitPrice = item.unitPrice;
				// Any holder that has recorded it answers for the item; they all
				// describe the same item id.
				if (item.members != null)
				{
					total.members = item.members;
				}
				total.byAccount.merge(record.accountHash, (long) item.quantity, Long::sum);
			}

			for (GrandExchangeRecord offer : record.geOffers)
			{
				if (!offer.isSell() || !offer.isActive())
				{
					continue;
				}
				int remaining = offer.remainingQuantity();
				if (remaining <= 0)
				{
					continue;
				}

				ItemTotal total = byId.computeIfAbsent(offer.itemId,
					id -> new ItemTotal(id, offer.itemName == null ? "" : offer.itemName));

				// Valued at the market price, never the asking price. Using the
				// listed price here did two kinds of damage: it inflated the
				// total for anything listed optimistically, and - because it
				// also overwrote unitPrice below - it repriced every bank copy
				// of the same item to match the listing.
				int unit = offer.marketPrice > 0 ? offer.marketPrice : total.unitPrice;

				total.totalQuantity += remaining;
				total.totalValue += (long) remaining * unit;
				if (unit > 0)
				{
					total.unitPrice = unit;
				}
				total.byAccount.merge(record.accountHash, (long) remaining, Long::sum);
			}
		}

		List<ItemTotal> totals = new ArrayList<>(byId.values());
		totals.sort(Comparator
			.comparingLong((ItemTotal t) -> t.totalValue).reversed()
			.thenComparing(t -> t.name, String.CASE_INSENSITIVE_ORDER));
		return totals;
	}

	/**
	 * Total wealth per account - bank plus GE escrow - ordered richest
	 * first. Drives the "wealth split across accounts" pie.
	 */
	static List<Slice> wealthByAccount(List<AccountRecord> accounts,
		java.util.function.Function<AccountRecord, String> nameOf)
	{
		List<Slice> slices = new ArrayList<>();
		for (AccountRecord record : accounts)
		{
			long wealth = record.totalWealth();
			if (wealth > 0L)
			{
				// The caller supplies the name so the privacy setting applies.
				// This used record.label() directly, which is the deliberately
				// unmasked persistence accessor - so with masking on, the wealth
				// pie's legend still listed every real character name.
				slices.add(new Slice(nameOf.apply(record), wealth, record.accountHash));
			}
		}
		slices.sort(Comparator.comparingLong((Slice s) -> s.value).reversed());
		return slices;
	}

	/**
	 * Per-account split of one item, ordered by quantity held descending.
	 * Drives the "what percent of this item is on what account" pie.
	 */
	static List<Slice> splitForItem(ItemTotal total, Map<Long, String> accountLabels)
	{
		List<Slice> slices = new ArrayList<>();
		for (Map.Entry<Long, Long> entry : total.byAccount.entrySet())
		{
			String label = accountLabels.getOrDefault(entry.getKey(),
				"Account " + Long.toHexString(entry.getKey()));
			slices.add(new Slice(label, entry.getValue(), entry.getKey()));
		}
		slices.sort(Comparator.comparingLong((Slice s) -> s.value).reversed());
		return slices;
	}

	/**
	 * A single wedge: a label, a magnitude, and the account it belongs to.
	 */
	static class Slice
	{
		final String label;
		final long value;
		final long accountHash;

		Slice(String label, long value, long accountHash)
		{
			this.label = label;
			this.value = value;
			this.accountHash = accountHash;
		}
	}
}

package com.accountalmanac;

import java.time.LocalDate;
import java.time.temporal.WeekFields;
import java.util.Locale;

/**
 * How often the Grand Exchange log is copied into a dated archive.
 *
 * <p>The log keeps a fixed number of events and drops the oldest past that,
 * which is what stops the file growing without limit. An archive is a plain
 * copy taken before that happens, so a year-old purchase price is still
 * recoverable from disk even though the live log no longer reaches back.
 *
 * <p>Public because it is a return type on the public
 * {@link AccountAlmanacConfig} interface, which RuneLite implements with a
 * dynamic proxy from another package - see {@link NamePrivacy} for what a
 * package-private type does there.
 */
public enum GeLogArchive
{
	OFF("Off"),
	WEEKLY("Weekly"),
	FORTNIGHTLY("Every 2 weeks"),
	MONTHLY("Monthly"),
	QUARTERLY("Every 3 months"),
	HALF_YEARLY("Every 6 months"),
	YEARLY("Yearly");

	private final String label;

	GeLogArchive(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}

	boolean isOn()
	{
		return this != OFF;
	}

	/**
	 * Name of the period a date falls in, from the machine's own clock - e.g.
	 * {@code 2026-09} for September on the monthly setting.
	 *
	 * <p>One archive is written per period, the first time the client runs
	 * inside it. That means a monthly archive holds the log as it stood at the
	 * end of the previous month, which is the point of it, and that a client
	 * left closed over a month end still archives when it next opens rather
	 * than missing the period entirely.
	 *
	 * <p>The keys sort chronologically as text, which is what orders the
	 * folder and decides which archives are the oldest when pruning.
	 */
	String periodKey(LocalDate date)
	{
		WeekFields weeks = WeekFields.ISO;
		switch (this)
		{
			case WEEKLY:
				return String.format(Locale.ROOT, "%d-W%02d",
					date.get(weeks.weekBasedYear()), date.get(weeks.weekOfWeekBasedYear()));
			case FORTNIGHTLY:
			{
				int fortnight = (date.get(weeks.weekOfWeekBasedYear()) + 1) / 2;
				return String.format(Locale.ROOT, "%d-F%02d", date.get(weeks.weekBasedYear()), fortnight);
			}
			case MONTHLY:
				return String.format(Locale.ROOT, "%d-%02d", date.getYear(), date.getMonthValue());
			case QUARTERLY:
				return String.format(Locale.ROOT, "%d-Q%d", date.getYear(), (date.getMonthValue() + 2) / 3);
			case HALF_YEARLY:
				return String.format(Locale.ROOT, "%d-H%d", date.getYear(), date.getMonthValue() <= 6 ? 1 : 2);
			case YEARLY:
				return String.format(Locale.ROOT, "%d", date.getYear());
			default:
				return "";
		}
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

/**
 * Groups and filters the account roster for the dropdown above the tables.
 *
 * <p>The options are a mix of two things, deliberately presented as one list
 * because that is how the user thinks about them: real categories they
 * assigned ("Pure", "Mule"), and the two state flags that behave like
 * groupings when you want to browse by them ("Banned", "Hidden"). Keeping
 * banned and hidden as flags on the record rather than as category values is
 * what lets an account be a banned pure, or a hidden main - see
 * {@link AccountCategory} for that reasoning.
 */
final class AccountFilter
{
	/** Everything, including accounts hidden from totals. */
	static final String ALL = "All accounts";

	/** Everything that counts toward totals - the sensible default. */
	static final String ALL_VISIBLE = "All except hidden";

	static final String GROUP_BANNED = "Banned";
	static final String GROUP_HIDDEN = "Hidden";
	static final String GROUP_UNCATEGORISED = "(no category)";

	private AccountFilter()
	{
	}

	/**
	 * Options for the filter dropdown: the two roster-wide choices, then the
	 * state groups that actually apply to at least one account, then every
	 * category in use, alphabetically.
	 *
	 * <p>Empty groups are left out rather than listed and unselectable - an
	 * option that always yields nothing is just noise.
	 */
	static List<String> groupsFor(List<AccountRecord> accounts)
	{
		List<String> groups = new ArrayList<>();
		groups.add(ALL_VISIBLE);
		groups.add(ALL);

		boolean anyBanned = false;
		boolean anyHidden = false;
		boolean anyUncategorised = false;
		Set<String> categories = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);

		for (AccountRecord record : accounts)
		{
			if (record.banned)
			{
				anyBanned = true;
			}
			if (record.hidden)
			{
				anyHidden = true;
			}
			String category = record.categoryLabel();
			if (category.isEmpty())
			{
				anyUncategorised = true;
			}
			else
			{
				categories.add(category);
			}
		}

		if (anyBanned)
		{
			groups.add(GROUP_BANNED);
		}
		if (anyHidden)
		{
			groups.add(GROUP_HIDDEN);
		}
		groups.addAll(categories);
		if (anyUncategorised)
		{
			groups.add(GROUP_UNCATEGORISED);
		}

		return groups;
	}

	/**
	 * Applies a group selection. An unrecognised or null group falls back to
	 * {@link #ALL_VISIBLE} rather than returning nothing, so a category that
	 * disappears (its last account was recategorised) cannot leave the table
	 * mysteriously blank.
	 */
	static List<AccountRecord> apply(List<AccountRecord> accounts, String group)
	{
		if (group == null || ALL_VISIBLE.equals(group))
		{
			return visibleOnly(accounts);
		}
		if (ALL.equals(group))
		{
			return new ArrayList<>(accounts);
		}

		List<AccountRecord> matched = new ArrayList<>();
		for (AccountRecord record : accounts)
		{
			if (matches(record, group))
			{
				matched.add(record);
			}
		}

		if (matched.isEmpty() && !GROUP_BANNED.equals(group) && !GROUP_HIDDEN.equals(group)
			&& !GROUP_UNCATEGORISED.equals(group))
		{
			return visibleOnly(accounts);
		}
		return matched;
	}

	private static boolean matches(AccountRecord record, String group)
	{
		if (GROUP_BANNED.equals(group))
		{
			return record.banned;
		}
		if (GROUP_HIDDEN.equals(group))
		{
			return record.hidden;
		}
		if (GROUP_UNCATEGORISED.equals(group))
		{
			return record.categoryLabel().isEmpty();
		}
		return group.equalsIgnoreCase(record.categoryLabel());
	}

	/**
	 * The accounts that contribute to cross-account totals. This is what every
	 * aggregate view should be built from, so that hiding an account actually
	 * removes it from the numbers rather than only from one table.
	 */
	static List<AccountRecord> visibleOnly(List<AccountRecord> accounts)
	{
		List<AccountRecord> visible = new ArrayList<>(accounts.size());
		for (AccountRecord record : accounts)
		{
			if (record.countsTowardTotals())
			{
				visible.add(record);
			}
		}
		return visible;
	}

	static int hiddenCount(List<AccountRecord> accounts)
	{
		int count = 0;
		for (AccountRecord record : accounts)
		{
			if (record.hidden)
			{
				count++;
			}
		}
		return count;
	}

}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Skill;

/**
 * The order skills appear in the in-game stats interface.
 *
 * <p>This cannot be taken from {@code Skill.values()}: that enum is in a
 * different order entirely (Attack, Defence, Strength, Hitpoints...) and
 * additionally carries {@code OVERALL}, which is a total rather than a
 * skill and has no cell in the panel. The layout is three columns by eight
 * rows, filled left to right.
 */
final class SkillOrder
{
	static final int COLUMNS = 3;

	/**
	 * Panel order, row by row. Held as enum constants rather than strings so
	 * a skill renamed or removed upstream fails at compile time here instead
	 * of silently vanishing from the grid.
	 */
	private static final Skill[] PANEL_ORDER = {
		Skill.ATTACK, Skill.HITPOINTS, Skill.MINING,
		Skill.STRENGTH, Skill.AGILITY, Skill.SMITHING,
		Skill.DEFENCE, Skill.HERBLORE, Skill.FISHING,
		Skill.RANGED, Skill.THIEVING, Skill.COOKING,
		Skill.PRAYER, Skill.CRAFTING, Skill.FIREMAKING,
		Skill.MAGIC, Skill.FLETCHING, Skill.WOODCUTTING,
		Skill.RUNECRAFT, Skill.SLAYER, Skill.FARMING,
		Skill.CONSTRUCTION, Skill.HUNTER, Skill.SAILING,
	};

	private SkillOrder()
	{
	}

	/**
	 * Every skill with a cell in the panel, in display order, followed by
	 * any skill the API knows about that this layout has not been updated
	 * for - so a newly released skill still appears rather than being
	 * silently dropped.
	 */
	@SuppressWarnings("deprecation") // Skill.OVERALL has no replacement; it is deliberately excluded here.
	static List<Skill> panelOrder()
	{
		List<Skill> ordered = new ArrayList<>();
		for (Skill skill : PANEL_ORDER)
		{
			ordered.add(skill);
		}

		for (Skill skill : Skill.values())
		{
			if (skill != Skill.OVERALL && !ordered.contains(skill))
			{
				ordered.add(skill);
			}
		}
		return ordered;
	}

	/**
	 * Panel order as {@code Skill.name()} strings - the keys skills are stored
	 * under in {@link AccountRecord#skillXp} and {@link HistorySnapshot#skillXp}.
	 */
	static List<String> names()
	{
		List<Skill> ordered = panelOrder();
		List<String> names = new ArrayList<>(ordered.size());
		for (Skill skill : ordered)
		{
			names.add(skill.name());
		}
		return names;
	}

	/** ATTACK -> Attack, RUNECRAFT -> Runecraft. */
	static String prettify(String skillName)
	{
		if (skillName == null || skillName.isEmpty())
		{
			return "";
		}
		return skillName.charAt(0)
			+ skillName.substring(1).toLowerCase(java.util.Locale.ROOT);
	}
}

package com.accountalmanac;

import java.util.HashMap;
import java.util.Map;

/**
 * One account's state at one moment, kept so the Stats and Wealth split tabs
 * can answer "what changed over the past 7 days / month / 90 days / year".
 *
 * <p>Wealth and experience are both recorded, because the two tabs ask
 * different questions of the same instant and taking them from separate
 * snapshots would let a bank reprice land between them.
 */
class HistorySnapshot
{
	/** Local PC time this snapshot was taken, epoch millis. */
	long at;

	/** Bank value at {@link #at}, using the prices known then. */
	long bankValue;

	/** Coins committed to Grand Exchange offers at {@link #at}. */
	long geValue;

	long totalXp;
	int totalLevel;
	int combatLevel;

	/**
	 * Skill name to experience, so per-skill gains over a window can be
	 * computed rather than only the total.
	 *
	 * <p>This is the bulk of a snapshot's size on disk - roughly two dozen
	 * entries - which is why {@link AccountHistory} thins older snapshots out
	 * instead of keeping every one forever.
	 */
	Map<String, Integer> skillXp = new HashMap<>();

	HistorySnapshot()
	{
	}

	static HistorySnapshot of(AccountRecord record, long at)
	{
		HistorySnapshot snapshot = new HistorySnapshot();
		snapshot.at = at;
		snapshot.bankValue = record.bankValue;
		snapshot.geValue = record.geValue();
		snapshot.totalXp = record.totalXp();
		snapshot.totalLevel = record.totalLevel();
		snapshot.combatLevel = record.combatLevel;
		snapshot.skillXp = new HashMap<>(record.skillXp);
		return snapshot;
	}

	long totalWealth()
	{
		return bankValue + geValue;
	}

	int skillXpFor(String skillName)
	{
		if (skillXp == null)
		{
			return 0;
		}
		Integer xp = skillXp.get(skillName);
		return xp == null ? 0 : xp;
	}

	/**
	 * True when this snapshot carries nothing worth keeping - no wealth and no
	 * experience. Used to avoid seeding history from an account that has been
	 * seen at the login screen but never actually observed.
	 */
	boolean isEmpty()
	{
		return bankValue == 0L && geValue == 0L && totalXp == 0L;
	}

	void normalise()
	{
		if (skillXp == null)
		{
			skillXp = new HashMap<>();
		}
	}
}

package com.accountalmanac;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Loads and saves the tracked-account file. Disk IO always happens off the
 * client thread via the injected executor; mutations to {@link #data} are
 * synchronized so a background save never races a client-thread update.
 *
 * <p>Collections on a record are always replaced wholesale rather than
 * mutated in place, so the Swing thread reading a record concurrently sees
 * either the old list or the new one - never a half-written one.
 *
 * <p>Renamed from {@code VaultStore} when the credential vault was removed.
 * The on-disk path is deliberately unchanged so existing data keeps loading.
 */
@Slf4j
@Singleton
class AccountStore
{
	private static final String FILE_NAME = "accounts.json";

	/**
	 * How long skill-only changes may wait before being saved. See
	 * {@link #markSkillsDirty()}; also the cadence the plugin refreshes the
	 * logged-in account's history point at while only XP is moving.
	 */
	static final long SKILL_SAVE_INTERVAL_MILLIS = java.util.concurrent.TimeUnit.MINUTES.toMillis(10);

	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final File dataFile;

	private TrackerData data = new TrackerData();
	private volatile boolean dirty;

	/** Skill changes not yet saved. Guarded by this. */
	private boolean skillsDirty;

	/** When the file was last written or read. Guarded by this. */
	private long lastWrittenAt;

	@Inject
	AccountStore(Gson gson, ScheduledExecutorService executor)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.executor = executor;
		this.dataFile = new File(new File(RuneLite.RUNELITE_DIR, "accountalmanac"), FILE_NAME);
	}

	void loadAsync(Runnable onLoaded)
	{
		executor.execute(() ->
		{
			synchronized (this)
			{
				data = readFromDisk();
				// Memory now matches the file, so the skill-save interval
				// counts from here rather than from the epoch.
				lastWrittenAt = System.currentTimeMillis();
			}
			if (onLoaded != null)
			{
				onLoaded.run();
			}
		});
	}

	private TrackerData readFromDisk()
	{
		if (!dataFile.exists())
		{
			return new TrackerData();
		}
		try (Reader reader = new InputStreamReader(new FileInputStream(dataFile), StandardCharsets.UTF_8))
		{
			TrackerData loaded = gson.fromJson(reader, TrackerData.class);
			if (loaded == null)
			{
				return new TrackerData();
			}
			// Files written before the bank-items and GE fields existed
			// leave those collections null rather than empty.
			loaded.normalise();
			return loaded;
		}
		catch (JsonParseException | IOException e)
		{
			log.warn("Failed to read account tracker data; starting empty", e);
			return new TrackerData();
		}
	}

	/**
	 * Marks dirty and queues a flush. Callers are on the client thread, so the
	 * write itself must not happen here.
	 */
	private void saveAsync()
	{
		dirty = true;
		executor.execute(this::flushIfDirty);
	}

	/**
	 * Marks in-memory data as needing a save without writing immediately, for
	 * changes that arrive in bursts - Grand Exchange slots after login, prices
	 * after a reprice - so the periodic {@link #flushIfDue} picks them up.
	 */
	private void markDirty()
	{
		dirty = true;
	}

	/**
	 * Marks skill data as changed. Kept apart from {@link #markDirty()}
	 * because it fires on every XP drop: this file holds every account's bank,
	 * so saving whenever a skill moved rewrote megabytes every few seconds
	 * while training. Skill changes are saved at most every
	 * {@link #SKILL_SAVE_INTERVAL_MILLIS}, or sooner whenever anything else is
	 * written. Nothing is lost for long, and the game re-reports every skill at
	 * login regardless.
	 */
	private void markSkillsDirty()
	{
		skillsDirty = true;
	}

	/**
	 * Writes everything outstanding, skill changes included - for shutdown,
	 * logout, backups and immediate saves.
	 *
	 * @return {@code true} if there was unsaved data and it was flushed.
	 */
	boolean flushIfDirty()
	{
		return flush(true, System.currentTimeMillis());
	}

	/**
	 * The periodic save: other changes are written straight away, skill-only
	 * changes once {@link #SKILL_SAVE_INTERVAL_MILLIS} has passed since the
	 * file was last written.
	 *
	 * @return {@code true} if data was flushed.
	 */
	boolean flushIfDue(long now)
	{
		return flush(false, now);
	}

	private boolean flush(boolean includeSkills, long now)
	{
		String json;
		synchronized (this)
		{
			boolean skillsDue = skillsDirty
				&& (includeSkills || now - lastWrittenAt >= SKILL_SAVE_INTERVAL_MILLIS);
			if (!dirty && !skillsDue)
			{
				return false;
			}
			// Serialised while holding the monitor so the snapshot is
			// consistent, but the disk write happens after releasing it: the
			// client thread contends on this same lock through updateSkill,
			// updateBank and updateGeOffer, and holding it across the write
			// would block the game on IO.
			json = gson.toJson(data);
			dirty = false;
			skillsDirty = false;
		}

		if (JsonFile.writeText(dataFile, json))
		{
			synchronized (this)
			{
				lastWrittenAt = now;
			}
			return true;
		}

		synchronized (this)
		{
			// Cleared only on success. Clearing permanently meant a failed
			// write - a full disk, or the file briefly locked by a sync tool -
			// silently discarded everything accumulated since the last flush.
			dirty = true;
		}
		return false;
	}


	synchronized List<AccountRecord> getAccounts()
	{
		return new ArrayList<>(data.accounts);
	}

	/**
	 * Records the automatically-captured identity fields on login. A blank
	 * {@code loginName} or {@code accountType} is ignored rather than
	 * written, so a client that does not expose one never clears a value
	 * captured earlier.
	 */
	synchronized void touchAccount(long accountHash, String displayName, String loginName, String accountType)
	{
		AccountRecord record = findOrCreate(accountHash);
		record.displayName = displayName;
		record.lastLoginAt = System.currentTimeMillis();
		if (loginName != null && !loginName.isEmpty())
		{
			record.loginName = loginName;
		}
		if (accountType != null && !accountType.isEmpty())
		{
			record.accountType = accountType;
		}
		saveAsync();
	}

	/**
	 * Replaces an account's bank snapshot. Items must already be
	 * canonicalised and priced by the caller on the client thread.
	 */
	synchronized void updateBank(long accountHash, List<BankItem> items, long bankValue)
	{
		AccountRecord record = findOrCreate(accountHash);
		record.bankItems = new ArrayList<>(items);
		record.bankValue = bankValue;
		record.lastUpdated = System.currentTimeMillis();
		record.lastSnapshotAt = record.lastUpdated;
		saveAsync();
	}

	/**
	 * Fires on every XP drop while training, so this only updates in-memory
	 * state and marks skills changed - see {@link #markSkillsDirty()}.
	 */
	synchronized void updateSkill(long accountHash, String skillName, int realLevel, int xp)
	{
		AccountRecord record = findOrCreate(accountHash);

		// Replaced wholesale rather than mutated in place, like every other
		// collection on a record. These two maps were the exception, and it was
		// a real bug: this runs on the client thread under this monitor, while
		// HistorySnapshot.of copies the same maps from the executor thread
		// under HistoryStore's monitor - different locks, so no mutual
		// exclusion. Training a skill during a flush threw
		// ConcurrentModificationException out of periodicFlush, which
		// ScheduledThreadPoolExecutor treats as fatal to the task: flushing and
		// UI refresh stopped for the rest of the session.
		//
		// Copying two ~23-entry maps per XP drop is nothing next to that.
		Map<String, Integer> levels = new HashMap<>(record.skillLevels);
		Map<String, Integer> experience = new HashMap<>(record.skillXp);
		levels.put(skillName, realLevel);
		experience.put(skillName, xp);

		record.skillLevels = levels;
		record.skillXp = experience;
		record.combatLevel = CombatLevel.calculate(levels);
		markSkillsDirty();
	}

	/**
	 * Records one GE slot. The client reports all eight slots shortly after
	 * login, so this is called in bursts rather than continuously; a slot is
	 * matched by index and replaced.
	 *
	 * <p>Returns the state the slot held beforehand, which is what
	 * {@link GeEventTracker} diffs against to decide whether an offer just
	 * started, finished or was collected. Swapping and returning in one
	 * synchronized step keeps that read-then-write atomic - fetching the
	 * previous value in a separate call would leave a window where two updates
	 * could interleave and produce a duplicated or missed event.
	 *
	 * @return the slot's previous contents, or {@code null} if this account has
	 *         never reported that slot before
	 */
	synchronized GrandExchangeRecord updateGeOffer(long accountHash, GrandExchangeRecord offer)
	{
		AccountRecord record = findOrCreate(accountHash);
		GrandExchangeRecord previous = null;
		for (GrandExchangeRecord existing : record.geOffers)
		{
			if (existing.slot == offer.slot)
			{
				previous = existing;
				break;
			}
		}

		List<GrandExchangeRecord> updated = new ArrayList<>(record.geOffers);
		updated.removeIf(existing -> existing.slot == offer.slot);
		updated.add(offer);
		updated.sort((a, b) -> Integer.compare(a.slot, b.slot));
		record.geOffers = updated;
		markDirty();
		return previous;
	}

	/**
	 * Records the account's reported playtime. Zero is ignored rather than
	 * written: the varp reads 0 before the account finishes loading, and
	 * storing that would wipe a good value captured earlier.
	 */
	synchronized void updatePlaytime(long accountHash, int minutes)
	{
		if (minutes <= 0)
		{
			return;
		}
		AccountRecord record = findOrCreate(accountHash);
		if (record.playtimeMinutes != minutes)
		{
			record.playtimeMinutes = minutes;
			markDirty();
		}
	}

	/**
	 * Records the account's quest points and the game's current maximum.
	 *
	 * <p>A maximum of zero is ignored, the same way playtime ignores zero:
	 * the varbit is unpopulated for the first few ticks after login, and a
	 * zero denominator would render as an obviously wrong "0/0". The score
	 * itself is trusted at zero, because a fresh account really does have
	 * none.
	 */
	synchronized void updateQuestPoints(long accountHash, int points, int max)
	{
		if (max <= 0 || points < 0)
		{
			return;
		}
		AccountRecord record = findOrCreate(accountHash);
		if (record.questPoints != points || record.questPointsMax != max)
		{
			record.questPoints = points;
			record.questPointsMax = max;
			markDirty();
		}
	}

	/**
	 * Quests completed and collection log slots filled, both read from vars.
	 *
	 * <p>A zero total is ignored the same way quest points ignore one: the vars
	 * are unpopulated for the first few ticks after login, and writing that
	 * would replace a real figure with "0/0".
	 */
	synchronized void updateSummaryCounts(long accountHash, int questsDone, int questsTotal,
		int collectionsDone, int collectionsTotal)
	{
		AccountRecord record = findOrCreate(accountHash);
		boolean changed = false;

		if (questsTotal > 0 && questsDone >= 0
			&& (record.questsCompleted != questsDone || record.questsTotal != questsTotal))
		{
			record.questsCompleted = questsDone;
			record.questsTotal = questsTotal;
			changed = true;
		}
		if (collectionsTotal > 0 && collectionsDone >= 0
			&& (record.collectionsLogged != collectionsDone || record.collectionsTotal != collectionsTotal))
		{
			record.collectionsLogged = collectionsDone;
			record.collectionsTotal = collectionsTotal;
			changed = true;
		}

		if (changed)
		{
			markDirty();
		}
	}

	/**
	 * Achievement diary tasks and combat tasks, as read off the Account Summary
	 * screen. Either may be absent from a given read, so a zero total leaves
	 * whatever was captured before alone.
	 */
	synchronized void updateSummaryTasks(long accountHash, int achievementsDone, int achievementsTotal,
		int combatDone, int combatTotal)
	{
		AccountRecord record = findOrCreate(accountHash);
		boolean changed = false;

		if (achievementsTotal > 0 && achievementsDone >= 0
			&& (record.achievementsCompleted != achievementsDone || record.achievementsTotal != achievementsTotal))
		{
			record.achievementsCompleted = achievementsDone;
			record.achievementsTotal = achievementsTotal;
			changed = true;
		}
		if (combatTotal > 0 && combatDone >= 0
			&& (record.combatTasksCompleted != combatDone || record.combatTasksTotal != combatTotal))
		{
			record.combatTasksCompleted = combatDone;
			record.combatTasksTotal = combatTotal;
			changed = true;
		}

		if (changed)
		{
			markDirty();
		}
	}

	synchronized void updateCategory(long accountHash, String category)
	{
		AccountRecord record = findOrCreate(accountHash);
		record.category = AccountCategory.normalise(category);
		saveAsync();
	}

	synchronized void updateHidden(long accountHash, boolean hidden)
	{
		AccountRecord record = findOrCreate(accountHash);
		record.hidden = hidden;
		saveAsync();
	}

	/**
	 * Marks or clears the banned flag, stamping when it was set so the
	 * "recheck this" prompt has an age to work from. Clearing resets the
	 * stamp, so un-banning and re-banning starts the clock again.
	 */
	synchronized void updateBanned(long accountHash, boolean banned)
	{
		AccountRecord record = findOrCreate(accountHash);
		record.banned = banned;
		record.bannedAt = banned ? System.currentTimeMillis() : 0L;
		saveAsync();
	}

	/** Looks up one account, or {@code null} if it is not tracked. */
	synchronized AccountRecord findAccount(long accountHash)
	{
		for (AccountRecord record : data.accounts)
		{
			if (record.accountHash == accountHash)
			{
				return record;
			}
		}
		return null;
	}

	/** Display label for an account hash, without exposing the record itself. */
	synchronized String labelFor(long accountHash)
	{
		AccountRecord record = findAccount(accountHash);
		return record == null ? ("Account " + Long.toHexString(accountHash)) : record.label();
	}

	File file()
	{
		return dataFile;
	}

	/**
	 * Overrides the display name captured on login.
	 *
	 * <p>An empty value clears the override, so the next login sets it from the
	 * client again rather than leaving the account permanently blank.
	 */
	synchronized void updateDisplayName(long accountHash, String displayName)
	{
		AccountRecord record = findOrCreate(accountHash);
		record.displayName = displayName == null ? "" : displayName;
		saveAsync();
	}

	synchronized void updateLoginLabel(long accountHash, String loginLabel)
	{
		AccountRecord record = findOrCreate(accountHash);
		record.loginLabel = loginLabel == null ? "" : loginLabel;
		saveAsync();
	}

	synchronized void updateNote(long accountHash, String note)
	{
		AccountRecord record = findOrCreate(accountHash);
		record.note = note == null ? "" : note;
		saveAsync();
	}

	synchronized void removeAccount(long accountHash)
	{
		data.accounts.removeIf(r -> r.accountHash == accountHash);
		saveAsync();
	}

	/**
	 * Every distinct item id across every account's bank snapshot, so the
	 * caller can price them all in one pass on the client thread.
	 */
	synchronized Set<Integer> allBankItemIds()
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (AccountRecord record : data.accounts)
		{
			for (BankItem item : record.bankItems)
			{
				ids.add(item.id);
			}
			// Items sitting in a sell offer need a market price too - they are
			// counted as owned stock, and without a price they would be valued
			// at nothing.
			for (GrandExchangeRecord offer : record.geOffers)
			{
				if (offer.isActive() && offer.itemId > 0)
				{
					ids.add(offer.itemId);
				}
			}
		}
		return ids;
	}

	/**
	 * Applies freshly-fetched unit prices to every stored snapshot and
	 * recomputes each account's bank value. Item ids missing from
	 * {@code pricesById} keep their previous price.
	 *
	 * @return {@code true} if any account's value actually changed.
	 */
	synchronized boolean applyPrices(Map<Integer, Integer> pricesById)
	{
		boolean changed = false;
		for (AccountRecord record : data.accounts)
		{
			List<BankItem> repriced = new ArrayList<>(record.bankItems.size());
			long total = 0L;
			boolean recordChanged = false;

			for (BankItem item : record.bankItems)
			{
				Integer fresh = pricesById.get(item.id);
				int price = fresh != null ? fresh : item.unitPrice;
				if (price != item.unitPrice)
				{
					recordChanged = true;
				}
				// haPrice carried through: alch value is fixed per item and is not
				// part of what a reprice refreshes.
				repriced.add(new BankItem(item.id, item.quantity, item.name, price, item.haPrice));
				total += (long) price * item.quantity;
			}

			// Offers carry their own market price, refreshed from the same feed.
			for (GrandExchangeRecord offer : record.geOffers)
			{
				Integer fresh = pricesById.get(offer.itemId);
				if (fresh != null && fresh != offer.marketPrice)
				{
					offer.marketPrice = fresh;
					recordChanged = true;
				}
			}

			if (recordChanged || total != record.bankValue)
			{
				record.bankItems = repriced;
				record.bankValue = total;
				changed = true;
			}
		}
		if (changed)
		{
			markDirty();
		}
		return changed;
	}

	/**
	 * Whether any stored item currently carries a non-zero price.
	 *
	 * <p>Used to tell a reprice that genuinely ran from one that found the
	 * price cache still empty and quietly did nothing.
	 */
	synchronized boolean hasPricedItems()
	{
		for (AccountRecord record : data.accounts)
		{
			for (BankItem item : record.bankItems)
			{
				if (item.unitPrice > 0)
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Fills in high alchemy values on every stored item.
	 *
	 * <p>Separate from {@link #applyPrices} because these do not change: an
	 * item's alch value is fixed, so this is a backfill rather than a refresh,
	 * and an item that already has one is left alone.
	 *
	 * @return {@code true} if anything was filled in
	 */
	/**
	 * Fills in the members flag for stored items that predate it being
	 * recorded.
	 *
	 * <p>Unlike the alch backfill this overwrites a known value rather than
	 * only filling blanks: whether an item is members-only is a property of
	 * the item, and if the game changes it the newer answer is the right one.
	 */
	synchronized boolean applyMembersFlags(Map<Integer, Boolean> membersById)
	{
		boolean changed = false;
		for (AccountRecord record : data.accounts)
		{
			for (BankItem item : record.bankItems)
			{
				Boolean members = membersById.get(item.id);
				if (members != null && !members.equals(item.members))
				{
					item.members = members;
					changed = true;
				}
			}
		}
		if (changed)
		{
			markDirty();
		}
		return changed;
	}

	synchronized boolean applyAlchPrices(Map<Integer, Integer> alchById)
	{
		boolean changed = false;
		for (AccountRecord record : data.accounts)
		{
			for (BankItem item : record.bankItems)
			{
				if (item.haPrice > 0)
				{
					continue;
				}
				Integer ha = alchById.get(item.id);
				if (ha != null && ha > 0)
				{
					item.haPrice = ha;
					changed = true;
				}
			}
		}
		if (changed)
		{
			markDirty();
		}
		return changed;
	}

	private AccountRecord findOrCreate(long accountHash)
	{
		for (AccountRecord record : data.accounts)
		{
			if (record.accountHash == accountHash)
			{
				return record;
			}
		}
		AccountRecord record = new AccountRecord();
		record.accountHash = accountHash;
		data.accounts.add(record);
		return record;
	}
}

package com.accountalmanac;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Accounts that are overdue for a login, longest overdue first.
 *
 * <h2>On the two week mark</h2>
 *
 * <p>The threshold defaults to 14 days because that is where a Grand Exchange
 * offer stops being trustworthy - not because the offer is removed. Offers in
 * Old School RuneScape stay in their slot until they complete or are
 * cancelled; they are not deleted for age, and items and coins sitting in the
 * collection box are held indefinitely. What actually decays is the price: an
 * offer listed a fortnight ago is quoting a fortnight-old market, so a buy may
 * have stopped filling and a sell may be well under what the item is now
 * worth.
 *
 * <p>The reminder is therefore framed as "these need a look", which is true
 * either way, rather than as "these are about to expire", which is not. The
 * threshold is configurable if a different cadence suits better.
 */
final class LoginReminders
{
	private LoginReminders()
	{
	}

	static class Reminder
	{
		final AccountRecord record;
		final long daysSinceLogin;
		final int liveOfferCount;
		final long committedGp;

		Reminder(AccountRecord record, long daysSinceLogin, int liveOfferCount, long committedGp)
		{
			this.record = record;
			this.daysSinceLogin = daysSinceLogin;
			this.liveOfferCount = liveOfferCount;
			this.committedGp = committedGp;
		}

		/** One-line summary for the reminder list, with names masked if configured. */
		String describe(NamePrivacy privacy)
		{
			StringBuilder sb = new StringBuilder();
			sb.append(NameMasker.display(record, privacy))
				.append(" - last login ")
				.append(daysSinceLogin)
				.append(daysSinceLogin == 1 ? " day ago" : " days ago");
			if (liveOfferCount > 0)
			{
				sb.append(", ").append(liveOfferCount)
					.append(liveOfferCount == 1 ? " live GE offer" : " live GE offers")
					.append(" holding ").append(Format.gp(committedGp));
			}
			return sb.toString();
		}
	}

	/**
	 * Accounts overdue for a login.
	 *
	 * <p>Banned accounts are never included. There is nothing to log into, so a
	 * reminder about one is noise by definition - it was briefly an option and
	 * there was no case where turning it on helped.
	 *
	 * @param onlyWithOffers restrict to accounts with outstanding offers
	 */
	static List<Reminder> overdue(
		List<AccountRecord> accounts,
		long now,
		int afterDays,
		boolean onlyWithOffers)
	{
		List<Reminder> due = new ArrayList<>();

		for (AccountRecord record : accounts)
		{
			if (record.banned)
			{
				continue;
			}
			if (record.hidden)
			{
				// Hidden accounts are excluded from totals by the user's own
				// choice; nagging about them would defeat the point.
				continue;
			}

			long days = LoginAge.daysSince(record.lastLoginAt, now);
			if (days < afterDays)
			{
				// Includes "never logged in" (-1). An account seen only at the
				// login screen has no login date to be overdue against.
				continue;
			}

			int liveOffers = 0;
			long committed = 0L;
			for (GrandExchangeRecord offer : record.geOffers)
			{
				if (offer.isActive())
				{
					liveOffers++;
					committed += offer.committedValue();
				}
			}

			if (onlyWithOffers && liveOffers == 0)
			{
				continue;
			}

			due.add(new Reminder(record, days, liveOffers, committed));
		}

		// Longest overdue first, then by how much is tied up in offers, so the
		// most consequential account to log into is at the top.
		due.sort(Comparator
			.comparingLong((Reminder r) -> r.daysSinceLogin).reversed()
			.thenComparing(Comparator.comparingLong((Reminder r) -> r.committedGp).reversed()));
		return due;
	}

}
